UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites arithmétiques et géométriques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites arithmétiques (raison $r$ par addition, $u_n = u_0 + nr$) et géométriques (raison $q$ par multiplication, $u_n = u_0 q^n$). Sommes : Gauss pour les arithmétiques, $u_0 (1-q^{n+1})/(1-q)$ pour les géométriques.","exercices":[{"number":1,"title_fr":"Identification arithmétique","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 2$ et $u_{n+1} = u_n + 4$.","questions":[{"number":1,"stem_fr":"Justifier que $(u_n)$ est arithmétique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Par définition : $(u_n)$ arithmétique $\\iff u_{n+1} - u_n = r$ constant. Ici $u_{n+1} - u_n = (u_n + 4) - u_n = 4$."},{"text_fr":"La différence est **constante et vaut 4**, indépendante de $n$. Donc $(u_n)$ est arithmétique de **raison $r = 4$**."}],"final_answer_fr":"$r = 4$"}},{"number":2,"stem_fr":"Donner $u_n$ en fonction de $n$ puis calculer $u_{20}$.","points":2,"solution":{"steps":[{"text_fr":"**Terme général arithmétique** : $u_n = u_0 + nr = 2 + 4n$."},{"text_fr":"$u_{20} = 2 + 4 \\times 20 = 82$.","tip_fr":"L''expression explicite $u_n = u_0 + nr$ permet d''accéder à n''importe quel terme sans énumérer les précédents."}],"final_answer_fr":"$u_n = 2 + 4n$, $u_{20} = 82$"}},{"number":3,"stem_fr":"Calculer la somme $S = u_0 + u_1 + \\dots + u_{20}$ (21 termes).","points":1,"solution":{"steps":[{"text_fr":"**Formule de Gauss** : $S = \\text{(nb termes)} \\times \\dfrac{\\text{premier} + \\text{dernier}}{2}$."},{"text_fr":"$S = 21 \\times (u_0 + u_{20})/2 = 21 \\times (2 + 82)/2 = 21 \\times 42 = 882$."}],"final_answer_fr":"$S = 882$"}}]},{"number":2,"title_fr":"Identification géométrique","points":5,"preamble_fr":"Soit $(v_n)$ définie par $v_0 = 3$ et $v_{n+1} = 2 v_n$.","questions":[{"number":1,"stem_fr":"Montrer que $(v_n)$ est géométrique et préciser sa raison.","points":2,"solution":{"steps":[{"text_fr":"$(v_n)$ géométrique $\\iff v_{n+1}/v_n = q$ constant (avec $v_n \\ne 0$). Ici $v_{n+1}/v_n = 2 v_n / v_n = 2$."},{"text_fr":"Donc $(v_n)$ est géométrique de **raison $q = 2$**.","mistake_fr":"Ne pas confondre arithmétique (différence constante) et géométrique (rapport constant) — le doublement, triplement, etc. est géométrique."}],"final_answer_fr":"$q = 2$"}},{"number":2,"stem_fr":"Donner $v_n$ en fonction de $n$ et calculer $v_{10}$.","points":1,"solution":{"steps":[{"text_fr":"**Terme général géométrique** : $v_n = v_0 q^n = 3 \\cdot 2^n$."},{"text_fr":"$v_{10} = 3 \\times 1024 = 3072$."}],"final_answer_fr":"$v_n = 3 \\cdot 2^n$, $v_{10} = 3072$"}},{"number":3,"stem_fr":"Calculer $S = v_0 + v_1 + \\dots + v_{10}$.","points":2,"solution":{"steps":[{"text_fr":"**Formule géométrique** : $S = v_0 \\dfrac{1 - q^{n+1}}{1 - q}$ pour $n+1$ termes ($q \\ne 1$)."},{"text_fr":"Ici 11 termes ($v_0$ à $v_{10}$), $v_0 = 3$, $q = 2$. $S = 3 \\cdot \\dfrac{1 - 2^{11}}{1 - 2} = 3 \\cdot \\dfrac{1 - 2048}{-1} = 3 \\times 2047 = 6141$."}],"final_answer_fr":"$S = 6141$"}}]},{"number":3,"title_fr":"Sens de variation et limites","points":5,"preamble_fr":"Étudier le comportement à l''infini selon la nature et les paramètres de la suite.","questions":[{"number":1,"stem_fr":"Suites arithmétiques.","points":2,"subparts":[{"letter":"a","stem_fr":"Donner le sens de variation d''une suite arithmétique selon le signe de $r$.","points":1,"solution":{"steps":[{"text_fr":"$u_{n+1} - u_n = r$. Donc : $r > 0$ → strictement croissante ; $r < 0$ → strictement décroissante ; $r = 0$ → constante."}]}},{"letter":"b","stem_fr":"Donner $\\lim u_n$ selon le signe de $r$.","points":1,"solution":{"steps":[{"text_fr":"$r > 0$ : $u_n \\to +\\infty$. $r < 0$ : $u_n \\to -\\infty$. $r = 0$ : suite constante, limite $= u_0$."}],"final_answer_fr":"Limite $= \\pm\\infty$ sauf si $r = 0$"}}]},{"number":2,"stem_fr":"Suites géométriques ($u_0 > 0$).","points":3,"subparts":[{"letter":"a","stem_fr":"Sens de variation selon $q$.","points":1,"solution":{"steps":[{"text_fr":"$u_{n+1} - u_n = u_n(q - 1)$. Avec $u_0 > 0$ et $q > 0$ : $q > 1$ → croissante, $0 < q < 1$ → décroissante."},{"text_fr":"Si $q < 0$, les termes alternent de signe — pas de monotonie."}]}},{"letter":"b","stem_fr":"Limites selon $q$.","points":2,"solution":{"steps":[{"text_fr":"**$q > 1$** : $q^n \\to +\\infty$ donc $u_n \\to +\\infty$."},{"text_fr":"**$q = 1$** : suite constante, limite $= u_0$."},{"text_fr":"**$|q| < 1$** : $q^n \\to 0$ donc $u_n \\to 0$."},{"text_fr":"**$q \\le -1$** : la suite oscille (pas de limite).","tip_fr":"Mémo : pour les géométriques, seule la position de $q$ par rapport à $\\pm 1$ détermine le comportement asymptotique."}]}}]}]},{"number":4,"title_fr":"Application — capital à intérêts composés","points":5,"preamble_fr":"Un capital $C_0 = 5000\\,\\text{DH}$ est placé à 4% d''intérêts composés annuels. Soit $C_n$ le capital après $n$ années.","questions":[{"number":1,"stem_fr":"Exprimer $C_{n+1}$ en fonction de $C_n$ et identifier la nature de la suite.","points":2,"solution":{"steps":[{"text_fr":"Chaque année, le capital est multiplié par $1{,}04$ (capital initial + 4% d''intérêt). Donc $C_{n+1} = 1{,}04 \\cdot C_n$."},{"text_fr":"$(C_n)$ est **géométrique** de raison $q = 1{,}04$ et de premier terme $C_0 = 5000$."}],"final_answer_fr":"Géométrique, $q = 1{,}04$"}},{"number":2,"stem_fr":"Calculer $C_{10}$ et $C_{20}$.","points":2,"solution":{"steps":[{"text_fr":"$C_n = 5000 \\times 1{,}04^n$. $1{,}04^{10} \\approx 1{,}4802$ → $C_{10} \\approx 7401\\,\\text{DH}$."},{"text_fr":"$1{,}04^{20} \\approx 2{,}1911$ → $C_{20} \\approx 10\\,956\\,\\text{DH}$.","tip_fr":"Règle de 72 : à 4%, doublement en environ $72/4 = 18$ ans. Cohérent avec $C_{20} \\approx 2 C_0$."}],"final_answer_fr":"$C_{10} \\approx 7401$ DH, $C_{20} \\approx 10\\,956$ DH"}},{"number":3,"stem_fr":"Au bout de combien d''années le capital aura-t-il triplé ?","points":1,"solution":{"steps":[{"text_fr":"Résoudre $1{,}04^n = 3 \\iff n \\ln(1{,}04) = \\ln 3 \\iff n = \\ln 3 / \\ln(1{,}04) \\approx 1{,}0986 / 0{,}0392 \\approx 28\\,\\text{ans}$."}],"final_answer_fr":"$n \\approx 28$ ans"}}]}]}'::jsonb WHERE code = 'pc_arithmetic_geom_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Convergence des suites","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Convergence, théorème des gendarmes, théorème de la limite monotone, opérations sur les limites.","exercices":[{"number":1,"title_fr":"Limites usuelles","points":5,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{n \\to \\infty} 1/n$, $\\lim 1/n^2$, $\\lim 1/\\sqrt{n}$.","points":2,"solution":{"steps":[{"text_fr":"**Règle générale** : pour tout $\\alpha > 0$, $\\lim_{n \\to \\infty} 1/n^\\alpha = 0$ (avec $\\sqrt n = n^{1/2}$)."},{"text_fr":"Les trois limites valent donc **0**. Plus $\\alpha$ est grand, plus la décroissance est rapide."}],"final_answer_fr":"Toutes valent 0"}},{"number":2,"stem_fr":"$\\lim_{n \\to \\infty} \\dfrac{3n^2 + n + 1}{n^2 - 2}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty/\\infty$ : on **factorise le terme dominant** (ici $n^2$) en haut et en bas."},{"text_fr":"$\\dfrac{3n^2 + n + 1}{n^2 - 2} = \\dfrac{n^2(3 + 1/n + 1/n^2)}{n^2(1 - 2/n^2)} = \\dfrac{3 + 1/n + 1/n^2}{1 - 2/n^2} \\to \\dfrac{3}{1} = 3$."},{"text_fr":"**Règle** : pour un quotient de polynômes de même degré, la limite est le rapport des coefficients dominants."}],"final_answer_fr":"$\\lim = 3$"}},{"number":3,"stem_fr":"$\\lim_{n \\to \\infty} \\sqrt{n+1} - \\sqrt{n}$.","points":1,"solution":{"steps":[{"text_fr":"Forme indéterminée $\\infty - \\infty$. **Astuce de la quantité conjuguée** : multiplier par $\\dfrac{\\sqrt{n+1} + \\sqrt{n}}{\\sqrt{n+1} + \\sqrt{n}}$."},{"text_fr":"$\\sqrt{n+1} - \\sqrt{n} = \\dfrac{(n+1) - n}{\\sqrt{n+1} + \\sqrt{n}} = \\dfrac{1}{\\sqrt{n+1} + \\sqrt{n}} \\to 0$.","mistake_fr":"Ne pas conclure que $\\sqrt{n+1} - \\sqrt{n} \\to \\infty - \\infty = 0$ : cette ''soustraction'' n''a pas de sens, il faut lever l''indétermination."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":2,"title_fr":"Théorème des gendarmes","points":5,"preamble_fr":"Soit $u_n = \\dfrac{\\cos(n)}{n}$ pour $n \\ge 1$.","questions":[{"number":1,"stem_fr":"Encadrer $u_n$.","points":2,"solution":{"steps":[{"text_fr":"Pour tout $n$, $-1 \\le \\cos(n) \\le 1$. Comme $n > 0$, on divise par $n$ sans changer le sens : $-1/n \\le \\cos(n)/n \\le 1/n$."}],"final_answer_fr":"$-1/n \\le u_n \\le 1/n$"}},{"number":2,"stem_fr":"En déduire $\\lim u_n$.","points":3,"solution":{"steps":[{"text_fr":"Les deux bornes $-1/n$ et $1/n$ tendent vers 0 quand $n \\to \\infty$."},{"text_fr":"Par le **théorème des gendarmes**, $u_n$ est encadrée par deux suites convergeant vers la même limite 0. Donc $\\lim u_n = 0$.","tip_fr":"$\\cos(n)$ n''a pas de limite (oscille entre -1 et 1), mais $\\cos(n)/n$ converge grâce à la décroissance dominante de $1/n$."}],"final_answer_fr":"$\\lim u_n = 0$"}}]},{"number":3,"title_fr":"Théorème de la limite monotone","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 1$ et $u_{n+1} = \\sqrt{2 + u_n}$.","questions":[{"number":1,"stem_fr":"Étude de $(u_n)$.","points":4,"subparts":[{"letter":"a","stem_fr":"Montrer par récurrence que $0 \\le u_n \\le 2$.","points":2,"solution":{"steps":[{"text_fr":"**Init** : $u_0 = 1 \\in [0, 2]$ ✓."},{"text_fr":"**Hérédité** : si $0 \\le u_n \\le 2$, alors $2 \\le 2 + u_n \\le 4$, donc $\\sqrt 2 \\le u_{n+1} \\le 2$. Comme $\\sqrt 2 \\approx 1{,}41 > 0$, on a bien $0 \\le u_{n+1} \\le 2$."}]}},{"letter":"b","stem_fr":"Montrer que $(u_n)$ est croissante.","points":1,"solution":{"steps":[{"text_fr":"Étude de signe : $u_{n+1}^2 - u_n^2 = (2 + u_n) - u_n^2 = -(u_n - 2)(u_n + 1)$. Sur $[0, 2]$, $(u_n - 2) \\le 0$ et $(u_n + 1) > 0$, donc $u_{n+1}^2 - u_n^2 \\ge 0$."},{"text_fr":"Comme $u_n, u_{n+1} \\ge 0$, ceci entraîne $u_{n+1} \\ge u_n$. La suite est croissante."}]}},{"letter":"c","stem_fr":"Conclure sur la convergence et calculer la limite.","points":1,"solution":{"steps":[{"text_fr":"($u_n$) est croissante et majorée par 2 → par le **théorème de la limite monotone**, elle converge vers une limite $L \\le 2$."},{"text_fr":"$L$ vérifie $L = \\sqrt{2 + L}$ (passage à la limite). Élever au carré : $L^2 = 2 + L \\iff L^2 - L - 2 = 0 \\iff (L-2)(L+1) = 0$, donc $L = 2$ (puisque $L \\ge 0$)."}],"final_answer_fr":"$L = 2$"}}]}]},{"number":4,"title_fr":"Opérations sur les limites","points":5,"preamble_fr":"Calculer ou justifier l''absence de limite pour les suites suivantes.","questions":[{"number":1,"stem_fr":"$u_n = (-1)^n$.","points":2,"solution":{"steps":[{"text_fr":"$u_n$ vaut alternativement $+1$ ($n$ pair) et $-1$ ($n$ impair). Elle prend deux valeurs distinctes à l''infini."},{"text_fr":"Donc $(u_n)$ **n''a pas de limite** (la suite des termes pairs converge vers 1, celle des impairs vers -1 — limites différentes → divergence)."}],"final_answer_fr":"Pas de limite"}},{"number":2,"stem_fr":"$v_n = n - n^2$.","points":1,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. Factoriser : $v_n = n(1 - n) = -n(n - 1)$."},{"text_fr":"Quand $n \\to \\infty$, $n(n-1) \\to +\\infty$ donc $v_n \\to -\\infty$."}],"final_answer_fr":"$\\lim v_n = -\\infty$"}},{"number":3,"stem_fr":"$w_n = \\dfrac{(-1)^n}{n} + 3$.","points":2,"solution":{"steps":[{"text_fr":"$(-1)^n / n$ est encadrée par $-1/n$ et $1/n$, donc tend vers 0 (gendarmes)."},{"text_fr":"Par somme des limites : $\\lim w_n = 0 + 3 = 3$."}],"final_answer_fr":"$\\lim w_n = 3$"}}]}]}'::jsonb WHERE code = 'pc_seq_convergence';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites récurrentes","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites définies par $u_{n+1} = f(u_n)$, points fixes, suites arithmético-géométriques, convergence par monotonie + bornes.","exercices":[{"number":1,"title_fr":"Récurrence affine simple","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 0$ et $u_{n+1} = \\dfrac{u_n + 6}{2}$.","questions":[{"number":1,"stem_fr":"Calculer $u_1, u_2, u_3$ et conjecturer le comportement.","points":2,"solution":{"steps":[{"text_fr":"$u_1 = (0 + 6)/2 = 3$. $u_2 = (3 + 6)/2 = 4{,}5$. $u_3 = (4{,}5 + 6)/2 = 5{,}25$."},{"text_fr":"La suite semble **croître et se stabiliser autour de 6** : 0, 3, 4.5, 5.25, 5.625, ..."}],"final_answer_fr":"Conjecture : croissante, limite $\\approx 6$"}},{"number":2,"stem_fr":"Trouver le point fixe de $f(x) = (x+6)/2$ et le comparer à la conjecture.","points":2,"solution":{"steps":[{"text_fr":"**Point fixe** : $L = f(L) \\iff L = (L + 6)/2 \\iff 2L = L + 6 \\iff L = 6$. ✓ avec la conjecture."},{"text_fr":"Le point fixe est un **candidat-limite** ; pour conclure rigoureusement, il faut prouver la convergence (monotonie + bornes).","mistake_fr":"Trouver le point fixe ne prouve pas la convergence : certaines suites n''atteignent jamais leur point fixe (ex. $u_{n+1} = 2 u_n - 6$ avec $u_0 = 0$ diverge bien que 6 soit un point fixe)."}],"final_answer_fr":"$L = 6$"}},{"number":3,"stem_fr":"Montrer que $(u_n)$ est croissante et majorée par 6, puis conclure.","points":1,"solution":{"steps":[{"text_fr":"**Majoration** par récurrence : si $u_n \\le 6$, alors $u_{n+1} = (u_n + 6)/2 \\le (6 + 6)/2 = 6$. Init OK avec $u_0 = 0 \\le 6$."},{"text_fr":"**Croissance** : $u_{n+1} - u_n = (u_n + 6)/2 - u_n = (6 - u_n)/2 > 0$ tant que $u_n < 6$."},{"text_fr":"Croissante + majorée → converge vers le point fixe $L = 6$."}]}}]},{"number":2,"title_fr":"Récurrence non linéaire","points":5,"preamble_fr":"Soit $(u_n)$ telle que $u_0 = 1$ et $u_{n+1} = \\sqrt{3 u_n + 4}$.","questions":[{"number":1,"stem_fr":"Étude complète.","points":4,"subparts":[{"letter":"a","stem_fr":"Trouver le(s) point(s) fixe(s).","points":1,"solution":{"steps":[{"text_fr":"$L = \\sqrt{3L + 4} \\Rightarrow L^2 = 3L + 4 \\Rightarrow L^2 - 3L - 4 = 0$."},{"text_fr":"Discriminant : $9 + 16 = 25$. Racines : $L = (3 + 5)/2 = 4$ ou $L = (3 - 5)/2 = -1$. La racine carrée étant positive, $L \\ge 0$, donc $L = 4$."}],"final_answer_fr":"$L = 4$"}},{"letter":"b","stem_fr":"Montrer par récurrence que $1 \\le u_n \\le 4$.","points":2,"solution":{"steps":[{"text_fr":"Init : $u_0 = 1 \\in [1, 4]$ ✓."},{"text_fr":"Hérédité : si $1 \\le u_n \\le 4$, alors $7 \\le 3 u_n + 4 \\le 16$, donc $\\sqrt 7 \\le u_{n+1} \\le 4$. Comme $\\sqrt 7 \\approx 2{,}65 > 1$, on a bien $1 \\le u_{n+1} \\le 4$."}]}},{"letter":"c","stem_fr":"Conclure sur la convergence.","points":1,"solution":{"steps":[{"text_fr":"Étude de signe : $u_{n+1}^2 - u_n^2 = (3 u_n + 4) - u_n^2 = -(u_n - 4)(u_n + 1)$. Sur $[1, 4]$, $(u_n - 4) \\le 0$ et $(u_n + 1) > 0$ → $u_{n+1}^2 \\ge u_n^2$ → $u_{n+1} \\ge u_n$ (les termes étant positifs)."},{"text_fr":"Croissante + majorée par 4 → converge. La limite vérifie l''équation du point fixe → $L = 4$."}],"final_answer_fr":"$\\lim u_n = 4$"}}]},{"number":2,"stem_fr":"Combien d''itérations pour atteindre $|u_n - 4| < 10^{-3}$ ?","points":1,"solution":{"steps":[{"text_fr":"Calcul itératif : $u_0 = 1$ (err = 3), $u_1 = \\sqrt 7 \\approx 2{,}65$ (err ≈ 1.35), $u_2 \\approx \\sqrt{11{,}95} \\approx 3{,}46$ (err ≈ 0.54), $u_3 \\approx \\sqrt{14{,}37} \\approx 3{,}79$ (err ≈ 0.21), $u_4 \\approx 3{,}92$, $u_5 \\approx 3{,}97$, $u_6 \\approx 3{,}99$, $u_7 \\approx 3{,}996$ (err ≈ 4×10⁻³), $u_8 \\approx 3{,}998$ (err ≈ 1.5×10⁻³), $u_9\\approx 3{,}9994$ (err < 10⁻³)."},{"text_fr":"Donc dès $n = 9$, la précision est atteinte."}],"final_answer_fr":"$n \\approx 9$"}}]},{"number":3,"title_fr":"Suite arithmético-géométrique","points":5,"preamble_fr":"Soit $(u_n)$ avec $u_0 = 1$ et $u_{n+1} = 3 u_n - 4$.","questions":[{"number":1,"stem_fr":"Trouver le point fixe $\\ell$ de $f(x) = 3x - 4$.","points":1,"solution":{"steps":[{"text_fr":"$\\ell = 3 \\ell - 4 \\iff 2 \\ell = 4 \\iff \\ell = 2$."}],"final_answer_fr":"$\\ell = 2$"}},{"number":2,"stem_fr":"Poser $v_n = u_n - \\ell$. Montrer que $(v_n)$ est géométrique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"$v_{n+1} = u_{n+1} - 2 = (3 u_n - 4) - 2 = 3 u_n - 6 = 3(u_n - 2) = 3 v_n$."},{"text_fr":"Donc $(v_n)$ est **géométrique de raison $q = 3$**.","tip_fr":"**Astuce arithmético-géométrique** : pour $u_{n+1} = a u_n + b$ avec $a \\ne 1$, le changement de variable $v_n = u_n - \\ell$ (où $\\ell$ est le point fixe $\\ell = b/(1-a)$) rend la suite géométrique pure."}],"final_answer_fr":"Géométrique, $q = 3$"}},{"number":3,"stem_fr":"Déterminer l''expression explicite de $u_n$ et sa limite.","points":2,"solution":{"steps":[{"text_fr":"$v_0 = u_0 - 2 = -1$. Donc $v_n = v_0 q^n = -3^n$."},{"text_fr":"Et $u_n = v_n + 2 = 2 - 3^n$."},{"text_fr":"Vérification : $u_0 = 2 - 1 = 1$ ✓. $u_1 = 2 - 3 = -1$ ; formule $3(1) - 4 = -1$ ✓."},{"text_fr":"Quand $n \\to \\infty$, $3^n \\to +\\infty$ donc $u_n \\to -\\infty$. La suite **diverge** ; le point fixe 2 est **répulsif** ($|q| > 1$)."}],"final_answer_fr":"$u_n = 2 - 3^n$, $\\lim = -\\infty$"}}]},{"number":4,"title_fr":"Application — modèle démographique","points":5,"preamble_fr":"Dans une cuve de production, la population de bactéries triple chaque heure mais 200 bactéries sont prélevées pour analyse. À $t = 0$, on a 500 bactéries.","questions":[{"number":1,"stem_fr":"Modéliser la population $P_n$ après $n$ heures.","points":1,"solution":{"steps":[{"text_fr":"$P_0 = 500$. Chaque heure : triplement ($\\times 3$) puis prélèvement ($-200$). Donc $P_{n+1} = 3 P_n - 200$."}],"final_answer_fr":"$P_{n+1} = 3 P_n - 200$, $P_0 = 500$"}},{"number":2,"stem_fr":"Déterminer l''expression explicite $P_n$.","points":3,"solution":{"steps":[{"text_fr":"Point fixe : $\\ell = 3 \\ell - 200 \\iff 2\\ell = 200 \\iff \\ell = 100$."},{"text_fr":"Posons $Q_n = P_n - 100$. Alors $Q_{n+1} = P_{n+1} - 100 = 3 P_n - 200 - 100 = 3(P_n - 100) = 3 Q_n$."},{"text_fr":"$(Q_n)$ géométrique de raison 3, $Q_0 = 500 - 100 = 400$. Donc $Q_n = 400 \\cdot 3^n$ et **$P_n = 100 + 400 \\cdot 3^n$**."}],"final_answer_fr":"$P_n = 100 + 400 \\cdot 3^n$"}},{"number":3,"stem_fr":"Calculer $P_5$ et conclure sur le comportement à long terme.","points":1,"solution":{"steps":[{"text_fr":"$P_5 = 100 + 400 \\cdot 3^5 = 100 + 400 \\times 243 = 100 + 97\\,200 = 97\\,300$ bactéries."},{"text_fr":"Quand $n \\to \\infty$, $3^n \\to +\\infty$ donc $P_n \\to +\\infty$ : la population **explose exponentiellement** malgré les prélèvements, car la croissance interne ($\\times 3$) domine largement la décroissance externe ($-200$)."}],"final_answer_fr":"$P_5 = 97\\,300$, explose"}}]}]}'::jsonb WHERE code = 'pc_seq_recursive';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Calcul de limites","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Limites en un point et à l''infini, formes indéterminées, factorisation, quantités conjuguées, croissances comparées.","exercices":[{"number":1,"title_fr":"Limites par calcul direct","points":5,"preamble_fr":"Calculer les limites suivantes en justifiant la méthode.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 2}(x^3 - 2x^2 + 1)$.","points":1,"solution":{"steps":[{"text_fr":"Polynôme continu sur $\\mathbb{R}$ → substitution directe : $8 - 8 + 1 = 1$."}],"final_answer_fr":"$\\lim = 1$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x - 3}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$ (numérateur et dénominateur s''annulent en 3). Factoriser : $x^2 - 9 = (x-3)(x+3)$."},{"text_fr":"$\\dfrac{(x-3)(x+3)}{x-3} = x + 3 \\to 6$ quand $x \\to 3$.","tip_fr":"Forme $0/0$ avec polynômes : factoriser par $(x - a)$ pour faire apparaître une simplification."}],"final_answer_fr":"$\\lim = 6$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 1} \\dfrac{x^3 - 1}{x^2 - 1}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$. $x^3 - 1 = (x-1)(x^2 + x + 1)$ ; $x^2 - 1 = (x-1)(x+1)$."},{"text_fr":"Fraction : $\\dfrac{x^2 + x + 1}{x + 1}$ pour $x \\ne 1$."},{"text_fr":"Limite en 1 : $\\dfrac{1 + 1 + 1}{1 + 1} = \\dfrac{3}{2}$."}],"final_answer_fr":"$\\lim = 3/2$"}}]},{"number":2,"title_fr":"Quantité conjuguée","points":5,"preamble_fr":"Calculer ces limites par la technique du conjugué.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\sqrt{1 + x} - 1}{x}$.","points":3,"solution":{"steps":[{"text_fr":"Forme $0/0$. Multiplier haut et bas par la quantité conjuguée $\\sqrt{1+x} + 1$."},{"text_fr":"$\\dfrac{(\\sqrt{1+x} - 1)(\\sqrt{1+x} + 1)}{x(\\sqrt{1+x} + 1)} = \\dfrac{(1 + x) - 1}{x(\\sqrt{1+x} + 1)} = \\dfrac{x}{x(\\sqrt{1+x} + 1)} = \\dfrac{1}{\\sqrt{1+x} + 1}$."},{"text_fr":"Limite en 0 : $\\dfrac{1}{\\sqrt 1 + 1} = \\dfrac{1}{2}$.","tip_fr":"Multiplier par le conjugué $(a + b)$ d''une expression $(a - b)$ donne $a^2 - b^2$ — fait disparaître les racines."}],"final_answer_fr":"$\\lim = 1/2$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty}\\sqrt{x^2 + x} - x$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. Conjuguée : multiplier par $(\\sqrt{x^2+x} + x)/(\\sqrt{x^2+x} + x)$."},{"text_fr":"Numérateur : $(x^2 + x) - x^2 = x$. Dénominateur : $\\sqrt{x^2 + x} + x$. Pour $x \\to +\\infty$, $\\sqrt{x^2 + x} \\sim x$, donc dénominateur $\\sim 2x$."},{"text_fr":"Limite : $\\dfrac{x}{2x} = \\dfrac{1}{2}$."}],"final_answer_fr":"$\\lim = 1/2$"}}]},{"number":3,"title_fr":"Limites à l''infini et croissances comparées","points":5,"preamble_fr":"Étudier le comportement asymptotique.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{3x^2 - x + 1}{x^2 + 2}$.","points":2,"solution":{"steps":[{"text_fr":"Quotient de polynômes de **même degré 2**. Factoriser $x^2$ en haut et en bas : $\\dfrac{x^2(3 - 1/x + 1/x^2)}{x^2(1 + 2/x^2)} \\to \\dfrac{3}{1} = 3$."},{"text_fr":"**Règle pratique** : pour un quotient de polynômes de même degré, limite = rapport des coefficients dominants."}],"final_answer_fr":"$\\lim = 3$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{\\ln x}{x}$ et $\\lim_{x \\to +\\infty} \\dfrac{e^x}{x^{10}}$.","points":2,"solution":{"steps":[{"text_fr":"**Croissances comparées** : à l''infini, l''exponentielle l''emporte sur toute puissance, qui l''emporte sur $\\ln$."},{"text_fr":"Donc $\\lim \\dfrac{\\ln x}{x} = 0$ et $\\lim \\dfrac{e^x}{x^{10}} = +\\infty$.","tip_fr":"Hiérarchie universelle : $e^x \\gg x^n \\gg \\ln x$ à l''infini. Elle décide qui ''gagne'' dans toute forme indéterminée $\\infty/\\infty$."}],"final_answer_fr":"$0$ et $+\\infty$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0^+} x \\ln x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $0 \\cdot (-\\infty)$. Changement de variable $u = 1/x$ ($u \\to +\\infty$ quand $x \\to 0^+$) : $x \\ln x = (1/u) \\ln(1/u) = -\\ln u / u \\to 0$ par croissances comparées."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":4,"title_fr":"Asymptotes","points":5,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 + 1}{x - 1}$ définie sur $\\mathbb{R} \\setminus \\{1\\}$.","questions":[{"number":1,"stem_fr":"Calculer les limites de $f$ en $1^+$, $1^-$, $+\\infty$, $-\\infty$.","points":2,"solution":{"steps":[{"text_fr":"En 1 : numérateur $\\to 2 > 0$, dénominateur $\\to 0$. Signe à droite : $x - 1 > 0$ → $f \\to +\\infty$. Signe à gauche : $x - 1 < 0$ → $f \\to -\\infty$."},{"text_fr":"À $\\pm \\infty$ : numérateur degré 2, dénominateur degré 1 → $f \\to \\pm \\infty$ (numérateur l''emporte)."}],"final_answer_fr":"$\\pm\\infty$ en 1; $\\pm\\infty$ à $\\pm\\infty$"}},{"number":2,"stem_fr":"Effectuer la division euclidienne pour écrire $f(x) = ax + b + c/(x-1)$.","points":2,"solution":{"steps":[{"text_fr":"Division : $x^2 + 1 = (x - 1)(x + 1) + 2$ (car $(x-1)(x+1) = x^2 - 1$ et reste = $1 - (-1) = 2$)."},{"text_fr":"Donc $f(x) = x + 1 + \\dfrac{2}{x - 1}$."}],"final_answer_fr":"$f(x) = x + 1 + 2/(x-1)$"}},{"number":3,"stem_fr":"En déduire l''asymptote oblique en $\\pm\\infty$.","points":1,"solution":{"steps":[{"text_fr":"Quand $x \\to \\pm\\infty$, $\\dfrac{2}{x-1} \\to 0$, donc $f(x) - (x + 1) \\to 0$."},{"text_fr":"La droite $y = x + 1$ est **asymptote oblique** à la courbe de $f$ en $\\pm\\infty$.","tip_fr":"Asymptote oblique : la partie polynômiale après division euclidienne donne l''équation de l''asymptote. Le reste tend vers 0."}],"final_answer_fr":"$y = x + 1$"}}]}]}'::jsonb WHERE code = 'pc_limit_calc';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Continuité et théorème des valeurs intermédiaires","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Continuité ($\\lim_a f = f(a)$), prolongement par continuité, TVI ($f$ continue sur $[a,b]$ + signes opposés → racine).","exercices":[{"number":1,"title_fr":"Continuité par morceaux","points":5,"preamble_fr":"Soit $f(x) = \\begin{cases} x^2 + 1 & \\text{si } x \\le 1 \\\\ ax + b & \\text{si } x > 1 \\end{cases}$.","questions":[{"number":1,"stem_fr":"Déterminer $a, b$ pour que $f$ soit continue et dérivable en $x = 1$.","points":4,"solution":{"steps":[{"text_fr":"**Continuité en 1** : $\\lim_{1^-} f = 1^2 + 1 = 2$ et $f(1) = 2$. Limite à droite : $\\lim_{1^+} ax + b = a + b$. Égalité : $a + b = 2$."},{"text_fr":"**Dérivabilité en 1** : les dérivées à gauche et à droite doivent coïncider. À gauche : $f''(x) = 2x$ donc $f''_g(1) = 2$. À droite : $f''(x) = a$, donc $a = 2$."},{"text_fr":"Avec $a = 2$ et $a + b = 2$ : $b = 0$. Donc $f(x) = 2x$ pour $x > 1$.","tip_fr":"Pour ''recoller'' deux morceaux avec dérivabilité, deux conditions : (1) mêmes valeurs (continuité), (2) mêmes pentes (dérivabilité)."}],"final_answer_fr":"$a = 2$, $b = 0$"}},{"number":2,"stem_fr":"Avec ces valeurs, vérifier la continuité et la dérivabilité.","points":1,"solution":{"steps":[{"text_fr":"$\\lim_{1^-} f = 2$, $\\lim_{1^+} f = 2 \\cdot 1 + 0 = 2$, $f(1) = 2$ ✓ continue. $f''_g(1) = 2$, $f''_d(1) = 2$ ✓ dérivable."}]}}]},{"number":2,"title_fr":"Prolongement par continuité","points":5,"preamble_fr":"Étudier la possibilité de prolonger par continuité.","questions":[{"number":1,"stem_fr":"$f(x) = \\dfrac{x^2 - 4}{x - 2}$ en $x = 2$.","points":3,"solution":{"steps":[{"text_fr":"$f$ n''est pas définie en 2 (dénominateur s''annule). Calcul de la limite : $\\dfrac{x^2 - 4}{x - 2} = \\dfrac{(x-2)(x+2)}{x - 2} = x + 2$ pour $x \\ne 2$."},{"text_fr":"$\\lim_{x \\to 2} f(x) = 4$ existe et est finie."},{"text_fr":"**Prolongement par continuité** : $\\tilde f(2) = 4$. La fonction prolongée est simplement $x + 2$ partout, continue sur $\\mathbb{R}$.","tip_fr":"Discontinuité ''apparente'' (forme $0/0$) → prolongeable. Discontinuité ''essentielle'' (limites infinies ou limites latérales différentes) → non-prolongeable."}],"final_answer_fr":"$\\tilde f(2) = 4$"}},{"number":2,"stem_fr":"$g(x) = \\dfrac{1}{x^2}$ en $x = 0$.","points":2,"solution":{"steps":[{"text_fr":"$\\lim_{x \\to 0} 1/x^2 = +\\infty$ (des deux côtés). Pas de limite finie."},{"text_fr":"**Impossible** de prolonger par continuité — la discontinuité est essentielle (asymptote verticale)."}],"final_answer_fr":"Non prolongeable"}}]},{"number":3,"title_fr":"TVI — existence et unicité","points":5,"preamble_fr":"Soit $f(x) = x^3 + 2x - 5$.","questions":[{"number":1,"stem_fr":"Étude de l''équation $f(x) = 0$.","points":4,"subparts":[{"letter":"a","stem_fr":"Justifier que l''équation admet au moins une solution dans $[1, 2]$.","points":2,"solution":{"steps":[{"text_fr":"$f$ est polynômiale → **continue sur $\\mathbb{R}$**, en particulier sur $[1, 2]$."},{"text_fr":"$f(1) = 1 + 2 - 5 = -2 < 0$ et $f(2) = 8 + 4 - 5 = 7 > 0$. Signes opposés → par **TVI**, $\\exists \\alpha \\in [1, 2] : f(\\alpha) = 0$."}],"final_answer_fr":"$\\exists \\alpha \\in [1, 2]$"}},{"letter":"b","stem_fr":"Montrer l''unicité.","points":1,"solution":{"steps":[{"text_fr":"$f''(x) = 3x^2 + 2 > 0$ pour tout $x$ (somme de positifs). Donc $f$ est **strictement croissante** sur $\\mathbb{R}$ → la solution est unique."}]}},{"letter":"c","stem_fr":"Donner un encadrement à $10^{-1}$ près.","points":1,"solution":{"steps":[{"text_fr":"$f(1{,}3) = 2{,}197 + 2{,}6 - 5 = -0{,}203 < 0$. $f(1{,}4) = 2{,}744 + 2{,}8 - 5 = 0{,}544 > 0$. Donc $\\alpha \\in ]1{,}3,\\, 1{,}4[$."}],"final_answer_fr":"$\\alpha \\in ]1{,}3,\\, 1{,}4[$"}}]}]},{"number":4,"title_fr":"Équation transcendante","points":5,"preamble_fr":"Soit $g(x) = e^x + x - 3$.","questions":[{"number":1,"stem_fr":"Montrer que $g(x) = 0$ admet une unique solution $\\alpha$ dans $\\mathbb{R}$.","points":3,"solution":{"steps":[{"text_fr":"**Existence** : $g$ est continue (somme de continues). $g(0) = 1 + 0 - 3 = -2 < 0$ ; $g(1) = e + 1 - 3 \\approx 0{,}72 > 0$. TVI sur $[0, 1]$ → solution."},{"text_fr":"**Unicité** : $g''(x) = e^x + 1 > 0$ partout → $g$ strictement croissante → solution unique."},{"text_fr":"**Domaine global** : $\\lim_{-\\infty} g = 0 - \\infty - 3 = -\\infty$ ; $\\lim_{+\\infty} g = +\\infty$. $g$ atteint toute valeur réelle, l''unique solution est dans $\\mathbb{R}$."}],"final_answer_fr":"$\\exists ! \\alpha \\approx 0{,}79$"}},{"number":2,"stem_fr":"Donner un encadrement de $\\alpha$ à $10^{-2}$ près par dichotomie.","points":2,"solution":{"steps":[{"text_fr":"On part de $[0, 1]$. Milieu $0{,}5$ : $g(0{,}5) = e^{0{,}5} + 0{,}5 - 3 \\approx 1{,}649 - 2{,}5 = -0{,}851 < 0$ → $\\alpha \\in ]0{,}5, 1[$."},{"text_fr":"Milieu $0{,}75$ : $g(0{,}75) \\approx 2{,}117 + 0{,}75 - 3 = -0{,}133 < 0$ → $\\alpha \\in ]0{,}75, 1[$."},{"text_fr":"Milieu $0{,}875$ : $g(0{,}875) \\approx 2{,}399 + 0{,}875 - 3 = 0{,}274 > 0$ → $\\alpha \\in ]0{,}75, 0{,}875[$. Milieu $0{,}8125$ : $g \\approx 2{,}253 + 0{,}8125 - 3 = 0{,}066 > 0$ → $\\alpha \\in ]0{,}75, 0{,}8125[$. Encore quelques étapes : $\\alpha \\approx 0{,}79$.","tip_fr":"**Dichotomie** : précision divisée par 2 à chaque étape. Pour $10^{-2}$ partant de longueur 1, il faut environ 7 itérations."}],"final_answer_fr":"$\\alpha \\approx 0{,}79$"}}]}]}'::jsonb WHERE code = 'pc_continuity_tvi';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Règles de dérivation","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Linéarité, produit $(uv)'' = u''v + uv''$, quotient $(u/v)'' = (u''v - uv'')/v^2$, composition $(f \\circ g)'' = (f'' \\circ g) \\cdot g''$.","exercices":[{"number":1,"title_fr":"Dérivées usuelles et linéarité","points":5,"preamble_fr":"Calculer la dérivée de chaque fonction.","questions":[{"number":1,"stem_fr":"$f(x) = 3x^4 - 2x^3 + 5x - 7$.","points":1,"solution":{"steps":[{"text_fr":"Linéarité — dériver terme à terme : $f''(x) = 12 x^3 - 6 x^2 + 5$."}],"final_answer_fr":"$f''(x) = 12x^3 - 6x^2 + 5$"}},{"number":2,"stem_fr":"$g(x) = \\dfrac{2}{x^3} + 4 \\sqrt x$ (sur $]0, +\\infty[$).","points":2,"solution":{"steps":[{"text_fr":"Réécrire en puissances : $g(x) = 2 x^{-3} + 4 x^{1/2}$."},{"text_fr":"$g''(x) = 2 \\cdot (-3) x^{-4} + 4 \\cdot (1/2) x^{-1/2} = -\\dfrac{6}{x^4} + \\dfrac{2}{\\sqrt x}$."}],"final_answer_fr":"$g''(x) = -6/x^4 + 2/\\sqrt x$"}},{"number":3,"stem_fr":"$h(x) = \\cos x + 2 \\sin x$.","points":2,"solution":{"steps":[{"text_fr":"$(\\cos x)'' = -\\sin x$ et $(\\sin x)'' = \\cos x$. Linéarité : $h''(x) = -\\sin x + 2 \\cos x$."}],"final_answer_fr":"$h''(x) = -\\sin x + 2\\cos x$"}}]},{"number":2,"title_fr":"Produit et quotient","points":5,"preamble_fr":"Appliquer les règles $(uv)''$ et $(u/v)''$.","questions":[{"number":1,"stem_fr":"$f(x) = x \\sin x$.","points":1,"solution":{"steps":[{"text_fr":"**Produit** : $u = x$, $u'' = 1$ ; $v = \\sin x$, $v'' = \\cos x$."},{"text_fr":"$f''(x) = 1 \\cdot \\sin x + x \\cdot \\cos x = \\sin x + x \\cos x$."}],"final_answer_fr":"$f''(x) = \\sin x + x \\cos x$"}},{"number":2,"stem_fr":"$g(x) = (x^2 + 1)(2x - 3)$.","points":2,"solution":{"steps":[{"text_fr":"$g''(x) = 2x \\cdot (2x - 3) + (x^2 + 1) \\cdot 2 = 4x^2 - 6x + 2x^2 + 2 = 6x^2 - 6x + 2$."},{"text_fr":"Vérification (développer $g$ puis dériver) : $g(x) = 2x^3 - 3x^2 + 2x - 3$, $g''(x) = 6x^2 - 6x + 2$ ✓."}],"final_answer_fr":"$g''(x) = 6x^2 - 6x + 2$"}},{"number":3,"stem_fr":"$h(x) = \\dfrac{x}{x^2 + 1}$.","points":2,"solution":{"steps":[{"text_fr":"**Quotient** : $u = x$, $u'' = 1$ ; $v = x^2 + 1$, $v'' = 2x$."},{"text_fr":"$(u/v)'' = (u''v - uv'')/v^2 = \\dfrac{1 \\cdot (x^2 + 1) - x \\cdot 2x}{(x^2 + 1)^2} = \\dfrac{x^2 + 1 - 2x^2}{(x^2+1)^2} = \\dfrac{1 - x^2}{(x^2+1)^2}$.","mistake_fr":"Ne pas oublier le signe **moins** au milieu : $u''v - uv''$ (et pas $u''v + uv''$)."}],"final_answer_fr":"$h''(x) = (1 - x^2)/(x^2+1)^2$"}}]},{"number":3,"title_fr":"Composition (règle de la chaîne)","points":5,"preamble_fr":"Appliquer $(f \\circ g)'' = (f'' \\circ g) \\cdot g''$.","questions":[{"number":1,"stem_fr":"$f(x) = (3x + 1)^4$.","points":2,"solution":{"steps":[{"text_fr":"Composition $u^4$ avec $u(x) = 3x + 1$. Règle : $(u^n)'' = n u^{n-1} u''$."},{"text_fr":"$u'' = 3$, donc $f''(x) = 4 (3x + 1)^3 \\cdot 3 = 12(3x + 1)^3$.","mistake_fr":"Erreur fréquente : oublier le $\\times u'' = \\times 3$. La dérivée de l''intérieur est essentielle."}],"final_answer_fr":"$f''(x) = 12(3x+1)^3$"}},{"number":2,"stem_fr":"$g(x) = \\sqrt{x^2 + 1}$.","points":2,"solution":{"steps":[{"text_fr":"Composition $\\sqrt u$ avec $u = x^2 + 1$. Règle : $(\\sqrt u)'' = u'' / (2 \\sqrt u)$."},{"text_fr":"$u'' = 2x$, donc $g''(x) = \\dfrac{2x}{2\\sqrt{x^2 + 1}} = \\dfrac{x}{\\sqrt{x^2 + 1}}$."}],"final_answer_fr":"$g''(x) = x/\\sqrt{x^2+1}$"}},{"number":3,"stem_fr":"$h(x) = \\sin(2x + \\pi/3)$.","points":1,"solution":{"steps":[{"text_fr":"Composition $\\sin u$ avec $u = 2x + \\pi/3$. $u'' = 2$."},{"text_fr":"$h''(x) = \\cos(2x + \\pi/3) \\cdot 2 = 2 \\cos(2x + \\pi/3)$."}],"final_answer_fr":"$h''(x) = 2 \\cos(2x + \\pi/3)$"}}]},{"number":4,"title_fr":"Tangentes","points":5,"preamble_fr":"Soit $f(x) = x^3 - 3x^2 + 2$.","questions":[{"number":1,"stem_fr":"Donner l''équation de la tangente $T$ à la courbe en $x_0 = 1$.","points":3,"solution":{"steps":[{"text_fr":"Équation de la tangente : $y = f''(x_0)(x - x_0) + f(x_0)$."},{"text_fr":"$f(1) = 1 - 3 + 2 = 0$. $f''(x) = 3x^2 - 6x$, donc $f''(1) = 3 - 6 = -3$."},{"text_fr":"Donc $T : y = -3(x - 1) + 0 = -3x + 3$."}],"final_answer_fr":"$T : y = -3x + 3$"}},{"number":2,"stem_fr":"En quels points la tangente est-elle horizontale ?","points":2,"solution":{"steps":[{"text_fr":"Tangente horizontale $\\iff$ pente nulle $\\iff f''(x) = 0 \\iff 3x^2 - 6x = 0 \\iff 3x(x - 2) = 0$."},{"text_fr":"Solutions : $x = 0$ ($f(0) = 2$) et $x = 2$ ($f(2) = 8 - 12 + 2 = -2$). Tangentes horizontales aux points $(0, 2)$ et $(2, -2)$.","tip_fr":"Les tangentes horizontales correspondent aux **extrema locaux** ; ici $f(0) = 2$ est un max local et $f(2) = -2$ un min local."}],"final_answer_fr":"$(0, 2)$ et $(2, -2)$"}}]}]}'::jsonb WHERE code = 'pc_deriv_rules';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Applications de la dérivation","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Étude de variations, extrema, optimisation, démonstration d''inégalités via étude de fonction.","exercices":[{"number":1,"title_fr":"Étude de variations","points":5,"preamble_fr":"Soit $f(x) = x^3 - 3x + 1$ définie sur $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"Calculer $f''(x)$, étudier son signe et dresser le tableau de variations.","points":3,"solution":{"steps":[{"text_fr":"$f''(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x - 1)(x + 1)$."},{"text_fr":"Signe de $f''$ : $f''(x) > 0$ sur $]-\\infty, -1[$ ; $f''(x) < 0$ sur $]-1, 1[$ ; $f''(x) > 0$ sur $]1, +\\infty[$."},{"text_fr":"Variations : $f$ **croissante** sur $]-\\infty, -1]$, **décroissante** sur $[-1, 1]$, **croissante** sur $[1, +\\infty[$."}],"final_answer_fr":"Max local en $-1$, min local en $1$"}},{"number":2,"stem_fr":"Donner les extrema locaux et leurs valeurs.","points":2,"solution":{"steps":[{"text_fr":"**Maximum local** en $x = -1$ : $f(-1) = -1 + 3 + 1 = 3$."},{"text_fr":"**Minimum local** en $x = 1$ : $f(1) = 1 - 3 + 1 = -1$.","tip_fr":"À un extremum local d''une fonction dérivable : la tangente est horizontale, donc $f''$ s''annule en changeant de signe."}],"final_answer_fr":"$f(-1) = 3$, $f(1) = -1$"}}]},{"number":2,"title_fr":"Optimisation — boîte à volume maximal","points":5,"preamble_fr":"Une feuille de carton carrée de côté 30 cm. On découpe un carré de côté $x$ à chaque coin, puis on plie pour former une boîte sans couvercle. Volume : $V(x) = x(30 - 2x)^2$ pour $0 < x < 15$.","questions":[{"number":1,"stem_fr":"Calculer $V''(x)$ et trouver la valeur de $x$ qui maximise $V$.","points":4,"solution":{"steps":[{"text_fr":"**Produit** : $V''(x) = 1 \\cdot (30 - 2x)^2 + x \\cdot 2(30 - 2x)(-2) = (30 - 2x)^2 - 4x(30 - 2x)$."},{"text_fr":"Factoriser par $(30 - 2x)$ : $V''(x) = (30 - 2x)[(30 - 2x) - 4x] = (30 - 2x)(30 - 6x) = 12(15 - x)(5 - x)$."},{"text_fr":"Racines : $x = 5$ et $x = 15$ (exclu). Sur $]0, 5[$ : $V''(0) = 12 \\cdot 15 \\cdot 5 = 900 > 0$. Sur $]5, 15[$ : $V''(10) = 12 \\cdot 5 \\cdot (-5) = -300 < 0$. $V''$ s''annule en $x = 5$ en changeant de signe → **maximum**."},{"text_fr":"Volume maximum : $V(5) = 5 \\cdot 20^2 = 5 \\cdot 400 = 2000\\,\\text{cm}^3 = 2\\,\\text{L}$.","tip_fr":"Recette d''optimisation : (1) exprimer la grandeur à optimiser, (2) délimiter le domaine, (3) dériver, (4) trouver les points critiques, (5) vérifier le signe de la dérivée."}],"final_answer_fr":"$x = 5$ cm, $V_{\\max} = 2000$ cm³"}}]},{"number":3,"title_fr":"Inégalité par étude de fonction","points":5,"preamble_fr":"Démontrer que pour tout $x > 0$, $\\ln(1 + x) < x$.","questions":[{"number":1,"stem_fr":"Étude de la fonction $f(x) = x - \\ln(1 + x)$.","points":4,"subparts":[{"letter":"a","stem_fr":"Donner le domaine de $f$ et calculer $f(0)$.","points":1,"solution":{"steps":[{"text_fr":"$\\ln(1 + x)$ définie pour $1 + x > 0 \\iff x > -1$. Domaine : $]-1, +\\infty[$."},{"text_fr":"$f(0) = 0 - \\ln 1 = 0$."}]}},{"letter":"b","stem_fr":"Calculer $f''(x)$ et étudier son signe sur $]0, +\\infty[$.","points":2,"solution":{"steps":[{"text_fr":"$f''(x) = 1 - \\dfrac{1}{1 + x} = \\dfrac{(1 + x) - 1}{1 + x} = \\dfrac{x}{1 + x}$."},{"text_fr":"Sur $]0, +\\infty[$ : $x > 0$ et $1 + x > 0$, donc $f''(x) > 0$."}]}},{"letter":"c","stem_fr":"Conclure.","points":1,"solution":{"steps":[{"text_fr":"$f$ est strictement croissante sur $[0, +\\infty[$ avec $f(0) = 0$. Donc pour $x > 0$, $f(x) > 0 \\iff x - \\ln(1 + x) > 0 \\iff \\ln(1 + x) < x$ ✓.","tip_fr":"Pour démontrer une inégalité $g(x) < h(x)$, étudier la fonction différence $h - g$ et montrer qu''elle est positive."}]}}]}]},{"number":4,"title_fr":"Étude complète","points":5,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 - 1}{x}$ définie sur $\\mathbb{R}^*$.","questions":[{"number":1,"stem_fr":"Étude complète.","points":5,"subparts":[{"letter":"a","stem_fr":"Calculer $f''(x)$ et étudier son signe.","points":2,"solution":{"steps":[{"text_fr":"Réécrire : $f(x) = x - 1/x$. Donc $f''(x) = 1 + 1/x^2$."},{"text_fr":"$f''(x) = 1 + 1/x^2 > 0$ partout sur $\\mathbb{R}^*$ → $f$ **strictement croissante** sur chacun de ses intervalles $]-\\infty, 0[$ et $]0, +\\infty[$."}],"final_answer_fr":"$f$ strictement croissante sur $\\mathbb{R}^*$"}},{"letter":"b","stem_fr":"Calculer les limites aux bornes.","points":2,"solution":{"steps":[{"text_fr":"À $\\pm \\infty$ : $f(x) = x - 1/x \\to \\pm \\infty$ (terme dominant $x$)."},{"text_fr":"En $0^+$ : $f(x) = x - 1/x \\to 0 - (+\\infty) = -\\infty$. En $0^-$ : $-1/x \\to +\\infty$, donc $f \\to +\\infty$."}]}},{"letter":"c","stem_fr":"Donner les asymptotes.","points":1,"solution":{"steps":[{"text_fr":"**Verticale** : $x = 0$ (limites infinies)."},{"text_fr":"**Oblique** en $\\pm \\infty$ : $f(x) - x = -1/x \\to 0$, donc la droite $y = x$ est asymptote oblique.","tip_fr":"Asymptote oblique $y = ax + b$ $\\iff f(x) - (ax + b) \\to 0$ en $\\pm\\infty$."}],"final_answer_fr":"V: $x = 0$; O: $y = x$"}}]}]}]}'::jsonb WHERE code = 'pc_deriv_apps';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Fonction logarithme népérien","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Fonction $\\ln$ définie sur $]0, +\\infty[$, $\\ln 1 = 0$, $\\ln e = 1$. Propriétés : $\\ln(ab) = \\ln a + \\ln b$, $(\\ln u)'' = u''/u$.","exercices":[{"number":1,"title_fr":"Propriétés algébriques et équations","points":5,"preamble_fr":"Rappel : $\\ln(ab) = \\ln a + \\ln b$, $\\ln(a/b) = \\ln a - \\ln b$, $\\ln(a^n) = n \\ln a$ pour $a, b > 0$.","questions":[{"number":1,"stem_fr":"Simplifier $A = \\ln 8 + \\ln 3 - 2 \\ln 2 - \\ln 6$.","points":2,"solution":{"steps":[{"text_fr":"Réécrire : $2 \\ln 2 = \\ln 4$ et regrouper. $A = \\ln 8 - \\ln 4 + \\ln 3 - \\ln 6 = \\ln(8/4) + \\ln(3/6) = \\ln 2 + \\ln(1/2)$."},{"text_fr":"$\\ln(1/2) = -\\ln 2$, donc $A = \\ln 2 - \\ln 2 = 0$.","tip_fr":"Regrouper les $\\ln$ par somme/différence avant de calculer numériquement — souvent tout se simplifie."}],"final_answer_fr":"$A = 0$"}},{"number":2,"stem_fr":"Résoudre dans $\\mathbb{R}$ : $\\ln(2x - 1) = \\ln(x + 3)$.","points":2,"solution":{"steps":[{"text_fr":"**Domaine** : $2x - 1 > 0$ et $x + 3 > 0$, soit $x > 1/2$ (plus restrictif)."},{"text_fr":"Par injectivité de $\\ln$ : $\\ln u = \\ln v \\iff u = v$. $2x - 1 = x + 3 \\iff x = 4$."},{"text_fr":"$x = 4 > 1/2$ ✓ → $S = \\{4\\}$.","mistake_fr":"Toujours vérifier les conditions d''existence avant d''utiliser l''injectivité — une solution ''algébrique'' peut être hors-domaine."}],"final_answer_fr":"$S = \\{4\\}$"}},{"number":3,"stem_fr":"Résoudre $\\ln(x^2 - 1) = \\ln 3 + \\ln(x + 1)$.","points":1,"solution":{"steps":[{"text_fr":"**Domaine** : $x^2 - 1 > 0 \\iff x < -1$ ou $x > 1$ ; $x + 1 > 0 \\iff x > -1$. Intersection : $x > 1$."},{"text_fr":"Équation : $\\ln(x^2 - 1) - \\ln(x + 1) = \\ln 3 \\iff \\ln\\left(\\dfrac{x^2 - 1}{x + 1}\\right) = \\ln 3 \\iff \\ln(x - 1) = \\ln 3$ (car $(x^2-1)/(x+1) = x - 1$)."},{"text_fr":"Donc $x - 1 = 3 \\iff x = 4 > 1$ ✓. $S = \\{4\\}$."}],"final_answer_fr":"$S = \\{4\\}$"}}]},{"number":2,"title_fr":"Dérivation et étude","points":5,"preamble_fr":"Soit $f(x) = x - \\ln x$ sur $]0, +\\infty[$.","questions":[{"number":1,"stem_fr":"Étude de $f$.","points":4,"subparts":[{"letter":"a","stem_fr":"Calculer $f''(x)$ et étudier son signe.","points":2,"solution":{"steps":[{"text_fr":"$f''(x) = 1 - 1/x = \\dfrac{x - 1}{x}$."},{"text_fr":"Sur $]0, +\\infty[$ : $x > 0$ → signe de $f''$ = signe de $x - 1$. $f'' < 0$ sur $]0, 1[$, $f'' > 0$ sur $]1, +\\infty[$, $f''(1) = 0$."}],"final_answer_fr":"$f''(x) = (x-1)/x$"}},{"letter":"b","stem_fr":"Tableau de variations et minimum.","points":1,"solution":{"steps":[{"text_fr":"$f$ décroît sur $]0, 1]$, croît sur $[1, +\\infty[$. **Minimum global** en $x = 1$ : $f(1) = 1 - \\ln 1 = 1$."},{"text_fr":"**Conséquence** : pour tout $x > 0$, $f(x) \\ge 1 \\iff x - \\ln x \\ge 1 \\iff \\ln x \\le x - 1$. Inégalité classique.","tip_fr":"L''inégalité $\\ln x \\le x - 1$ (égalité en 1) est très utile pour borner $\\ln$ par un polynôme."}],"final_answer_fr":"Min $f(1) = 1$; $\\ln x \\le x - 1$"}},{"letter":"c","stem_fr":"Limites aux bornes.","points":1,"solution":{"steps":[{"text_fr":"En $0^+$ : $\\ln x \\to -\\infty$ donc $f(x) = x - \\ln x \\to 0 - (-\\infty) = +\\infty$."},{"text_fr":"En $+\\infty$ : factoriser $f(x) = x(1 - \\ln x / x)$. Par croissances comparées, $\\ln x / x \\to 0$, donc $f(x) \\to +\\infty$."}],"final_answer_fr":"$+\\infty$ aux deux bornes"}}]}]},{"number":3,"title_fr":"Composition","points":5,"preamble_fr":"Soit $g(x) = \\ln(x^2 + 1)$ sur $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"Justifier le domaine.","points":1,"solution":{"steps":[{"text_fr":"$x^2 + 1 \\ge 1 > 0$ pour tout $x \\in \\mathbb{R}$, donc $\\ln(x^2 + 1)$ est défini partout. $\\mathcal D_g = \\mathbb{R}$."}]}},{"number":2,"stem_fr":"Calculer $g''(x)$ et étudier les variations.","points":2,"solution":{"steps":[{"text_fr":"**Règle** : $(\\ln u)'' = u''/u$. Ici $u = x^2 + 1$, $u'' = 2x$."},{"text_fr":"$g''(x) = \\dfrac{2x}{x^2 + 1}$. Dénominateur $> 0$, donc signe = signe de $2x$."},{"text_fr":"$g$ décroît sur $]-\\infty, 0]$, croît sur $[0, +\\infty[$. **Minimum** en $x = 0$ : $g(0) = \\ln 1 = 0$."}],"final_answer_fr":"$g''(x) = 2x/(x^2+1)$; min $g(0) = 0$"}},{"number":3,"stem_fr":"Limites en $\\pm\\infty$.","points":2,"solution":{"steps":[{"text_fr":"Quand $x \\to \\pm\\infty$, $x^2 + 1 \\to +\\infty$ et $\\ln t \\to +\\infty$ quand $t \\to +\\infty$."},{"text_fr":"Par composition : $\\lim_{\\pm\\infty} g = +\\infty$.","tip_fr":"$g$ est paire ($g(-x) = g(x)$) — mêmes valeurs et mêmes limites en $\\pm\\infty$."}],"final_answer_fr":"$\\lim = +\\infty$ aux deux bornes"}}]},{"number":4,"title_fr":"Inégalité","points":5,"preamble_fr":"Démontrer pour tout $x > 0$ : $\\ln(1 + x) \\le x$.","questions":[{"number":1,"stem_fr":"Étudier la fonction $h(x) = x - \\ln(1 + x)$ sur $]-1, +\\infty[$.","points":4,"solution":{"steps":[{"text_fr":"$h(0) = 0 - \\ln 1 = 0$."},{"text_fr":"$h''(x) = 1 - \\dfrac{1}{1 + x} = \\dfrac{x}{1 + x}$."},{"text_fr":"Sur $]0, +\\infty[$ : $x > 0$ et $1 + x > 0$ → $h''(x) > 0$. $h$ strictement croissante."},{"text_fr":"Donc pour $x > 0$ : $h(x) > h(0) = 0 \\iff x - \\ln(1+x) > 0 \\iff \\ln(1 + x) < x$ ✓.","tip_fr":"Stratégie classique : pour montrer $f < g$ sur $I$, étudier $g - f$ et montrer qu''elle est strictement positive."}],"final_answer_fr":"$\\ln(1+x) < x$ pour $x > 0$"}},{"number":2,"stem_fr":"Application : encadrer $\\ln 2$.","points":1,"solution":{"steps":[{"text_fr":"Avec $x = 1$ : $\\ln 2 < 1$. On peut aussi montrer $\\ln(1+x) \\ge x - x^2/2$ pour $x \\ge 0$, ce qui donne $\\ln 2 \\ge 1/2$. Encadrement $1/2 < \\ln 2 < 1$. Valeur exacte $\\ln 2 \\approx 0{,}693$."}],"final_answer_fr":"$0{,}5 < \\ln 2 < 1$"}}]}]}'::jsonb WHERE code = 'pc_ln_function';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Fonction exponentielle","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Fonction $\\exp(x) = e^x$ : $(e^x)'' = e^x$, $e^x > 0$ partout, $e^0 = 1$. Croissances comparées $e^x \\gg x^n$.","exercices":[{"number":1,"title_fr":"Propriétés algébriques","points":5,"preamble_fr":"Rappel : $e^a \\cdot e^b = e^{a+b}$, $e^a/e^b = e^{a-b}$, $(e^a)^n = e^{na}$, $e^{-a} = 1/e^a$.","questions":[{"number":1,"stem_fr":"Simplifier $A = \\dfrac{e^3 \\cdot e^{-1}}{e^4}$.","points":1,"solution":{"steps":[{"text_fr":"Numérateur : $e^3 \\cdot e^{-1} = e^{3-1} = e^2$."},{"text_fr":"Quotient : $e^2 / e^4 = e^{2-4} = e^{-2}$."}],"final_answer_fr":"$A = e^{-2}$"}},{"number":2,"stem_fr":"Résoudre $e^{2x} - 3 e^x + 2 = 0$.","points":3,"solution":{"steps":[{"text_fr":"**Astuce** : poser $X = e^x$ ($X > 0$). $e^{2x} = X^2$, l''équation devient $X^2 - 3X + 2 = 0$."},{"text_fr":"Discriminant : $\\Delta = 9 - 8 = 1$. Racines : $X = 2$ ou $X = 1$. Les deux sont positives ✓."},{"text_fr":"Retour à $x$ : $e^x = 2 \\iff x = \\ln 2$ ; $e^x = 1 \\iff x = 0$. $S = \\{0, \\ln 2\\}$.","tip_fr":"Pour une équation polynomiale en $e^x$, substituer $X = e^x$ ramène à un polynôme classique."}],"final_answer_fr":"$S = \\{0, \\ln 2\\}$"}},{"number":3,"stem_fr":"Résoudre $e^x \\ge 5$.","points":1,"solution":{"steps":[{"text_fr":"$\\ln$ étant strictement croissante, on applique $\\ln$ aux deux membres : $e^x \\ge 5 \\iff x \\ge \\ln 5 \\approx 1{,}609$."}],"final_answer_fr":"$x \\ge \\ln 5$"}}]},{"number":2,"title_fr":"Étude de $f(x) = x e^{-x}$","points":5,"preamble_fr":"Soit $f(x) = x e^{-x}$ sur $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"Calculer $f''(x)$ et étudier son signe.","points":2,"solution":{"steps":[{"text_fr":"**Produit** : $u = x$ ($u'' = 1$), $v = e^{-x}$ ($v'' = -e^{-x}$)."},{"text_fr":"$f''(x) = 1 \\cdot e^{-x} + x \\cdot (-e^{-x}) = e^{-x}(1 - x)$."},{"text_fr":"$e^{-x} > 0$ toujours → signe de $f''$ = signe de $1 - x$. $f'' > 0$ sur $]-\\infty, 1[$, $f'' < 0$ sur $]1, +\\infty[$."}],"final_answer_fr":"$f''(x) = e^{-x}(1 - x)$"}},{"number":2,"stem_fr":"Tableau de variations et extremum.","points":1,"solution":{"steps":[{"text_fr":"$f$ croît sur $]-\\infty, 1]$, décroît sur $[1, +\\infty[$. **Maximum global** en $x = 1$ : $f(1) = 1 \\cdot e^{-1} = 1/e \\approx 0{,}368$."}],"final_answer_fr":"Max $f(1) = 1/e$"}},{"number":3,"stem_fr":"Limites en $\\pm\\infty$.","points":2,"solution":{"steps":[{"text_fr":"En $-\\infty$ : $x \\to -\\infty$ et $e^{-x} \\to +\\infty$ — produit (négatif) × (positif) → $f \\to -\\infty$."},{"text_fr":"En $+\\infty$ : $f(x) = x/e^x$. Par croissances comparées, $\\lim x/e^x = 0$. Donc $f \\to 0$.","tip_fr":"**Croissances comparées** : $\\lim_{x \\to +\\infty} x^n/e^x = 0$ pour tout $n$. L''exponentielle domine toute puissance."}],"final_answer_fr":"$-\\infty$ et $0$"}}]},{"number":3,"title_fr":"Limites et croissances comparées","points":5,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{e^x}{x^3}$.","points":1,"solution":{"steps":[{"text_fr":"Croissances comparées : $\\lim e^x / x^n = +\\infty$. Donc limite = $+\\infty$."}],"final_answer_fr":"$+\\infty$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} x^2 e^{-x}$.","points":2,"solution":{"steps":[{"text_fr":"Réécrire : $x^2 e^{-x} = x^2/e^x$. Forme $\\infty/\\infty$."},{"text_fr":"Par croissances comparées : $\\lim x^2/e^x = 0$. Donc limite = 0."}],"final_answer_fr":"$\\lim = 0$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{e^x - 1}{x}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$. Reconnaître le **taux d''accroissement** de $\\exp$ en 0 : $\\dfrac{e^x - e^0}{x - 0}$. Sa limite quand $x \\to 0$ est $\\exp''(0) = e^0 = 1$.","tip_fr":"**Limites usuelles** : $\\lim_0 (e^x - 1)/x = 1$, $\\lim_0 \\sin x/x = 1$, $\\lim_0 \\ln(1+x)/x = 1$."}],"final_answer_fr":"$\\lim = 1$"}}]},{"number":4,"title_fr":"Modèle de décroissance — radioactivité","points":5,"preamble_fr":"Une quantité $Q(t)$ vérifie $Q(t) = Q_0 e^{-\\lambda t}$ avec $Q_0 = 100$ et $Q(2) = 60$.","questions":[{"number":1,"stem_fr":"Calculer la constante $\\lambda$.","points":2,"solution":{"steps":[{"text_fr":"$Q(2) = 100 e^{-2\\lambda} = 60 \\iff e^{-2\\lambda} = 0{,}6$."},{"text_fr":"Appliquer $\\ln$ : $-2\\lambda = \\ln(0{,}6)$, donc $\\lambda = -\\ln(0{,}6)/2 = \\ln(5/3)/2 \\approx 0{,}255$."}],"final_answer_fr":"$\\lambda \\approx 0{,}255$"}},{"number":2,"stem_fr":"Déterminer la demi-vie $t_{1/2}$.","points":2,"solution":{"steps":[{"text_fr":"$Q(t_{1/2}) = Q_0/2 \\iff e^{-\\lambda t_{1/2}} = 1/2 \\iff -\\lambda t_{1/2} = -\\ln 2 \\iff t_{1/2} = \\ln 2 / \\lambda$."},{"text_fr":"Avec $\\lambda \\approx 0{,}255$ : $t_{1/2} \\approx 0{,}693/0{,}255 \\approx 2{,}72$.","tip_fr":"**Formule fondamentale** : $t_{1/2} = \\ln 2 / \\lambda$. Indépendante de $Q_0$ — caractéristique du matériau."}],"final_answer_fr":"$t_{1/2} \\approx 2{,}72$"}},{"number":3,"stem_fr":"Calculer $\\lim_{t \\to +\\infty} Q(t)$ et interpréter.","points":1,"solution":{"steps":[{"text_fr":"Quand $t \\to +\\infty$, $-\\lambda t \\to -\\infty$, $e^{-\\lambda t} \\to 0^+$. Donc $Q(t) \\to 0$."},{"text_fr":"**Interprétation** : décroissance asymptotique — il reste toujours un peu de matière. Cohérent avec la radioactivité."}],"final_answer_fr":"$\\lim Q = 0$"}}]}]}'::jsonb WHERE code = 'pc_exp_function';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Primitives","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Primitive : fonction $F$ telle que $F'' = f$. Unicité à une constante près. Primitives usuelles + formes $u''/u$, $u'' u^n$, $u'' e^u$.","exercices":[{"number":1,"title_fr":"Primitives usuelles","points":5,"preamble_fr":"Donner une primitive de chaque fonction sur le domaine indiqué.","questions":[{"number":1,"stem_fr":"$f(x) = x^3 - 4x + 2$ sur $\\mathbb{R}$.","points":1,"solution":{"steps":[{"text_fr":"Linéarité et primitive de $x^n$ = $x^{n+1}/(n+1)$ (pour $n \\ne -1$)."},{"text_fr":"$F(x) = \\dfrac{x^4}{4} - 2 x^2 + 2 x + C$. Vérif : $F''(x) = x^3 - 4x + 2$ ✓."}],"final_answer_fr":"$F(x) = x^4/4 - 2x^2 + 2x + C$"}},{"number":2,"stem_fr":"$g(x) = 1/x^2$ sur $]0, +\\infty[$.","points":1,"solution":{"steps":[{"text_fr":"$g(x) = x^{-2}$, primitive $x^{-1}/(-1) = -1/x$. $G(x) = -1/x + C$."}],"final_answer_fr":"$G(x) = -1/x + C$"}},{"number":3,"stem_fr":"$h(x) = \\sin(2x) + \\cos(3x)$ sur $\\mathbb{R}$.","points":2,"solution":{"steps":[{"text_fr":"Pour $\\sin(ax)$, primitive $-\\cos(ax)/a$. Pour $\\cos(ax)$, primitive $\\sin(ax)/a$."},{"text_fr":"$H(x) = -\\cos(2x)/2 + \\sin(3x)/3 + C$. Vérif : $H''(x) = \\sin(2x) \\cdot 1 + \\cos(3x) \\cdot 1$ ✓.","tip_fr":"Le facteur $1/a$ compense la dérivation interne — sans lui, la dérivée serait $a\\sin(ax)$ au lieu de $\\sin(ax)$."}],"final_answer_fr":"$H(x) = -\\cos(2x)/2 + \\sin(3x)/3 + C$"}},{"number":4,"stem_fr":"$k(x) = e^{3x + 1}$ sur $\\mathbb{R}$.","points":1,"solution":{"steps":[{"text_fr":"Primitive de $e^{ax + b}$ : $e^{ax+b}/a$. $K(x) = e^{3x+1}/3 + C$."}],"final_answer_fr":"$K(x) = e^{3x+1}/3 + C$"}}]},{"number":2,"title_fr":"Primitive avec condition","points":5,"preamble_fr":"Soit $f(x) = 3 x^2 - 6x + 5$.","questions":[{"number":1,"stem_fr":"Donner la forme générale des primitives.","points":1,"solution":{"steps":[{"text_fr":"$F(x) = x^3 - 3 x^2 + 5x + C$ (où $C \\in \\mathbb{R}$)."}],"final_answer_fr":"$F(x) = x^3 - 3x^2 + 5x + C$"}},{"number":2,"stem_fr":"Trouver la primitive $F$ vérifiant $F(1) = 0$.","points":2,"solution":{"steps":[{"text_fr":"Condition : $F(1) = 1 - 3 + 5 + C = 3 + C = 0 \\Rightarrow C = -3$."},{"text_fr":"Donc $F(x) = x^3 - 3 x^2 + 5x - 3$. Vérification : $F(1) = 1 - 3 + 5 - 3 = 0$ ✓.","tip_fr":"Toute primitive a une **constante d''intégration libre**, fixée par une condition initiale (souvent $F(x_0) = y_0$)."}],"final_answer_fr":"$F(x) = x^3 - 3x^2 + 5x - 3$"}},{"number":3,"stem_fr":"Combien y a-t-il de primitives de $f$ ?","points":2,"solution":{"steps":[{"text_fr":"Il y a une **infinité** de primitives, toutes différant d''une constante (la ''constante d''intégration''). Une condition $F(x_0) = y_0$ en sélectionne exactement une."},{"text_fr":"Mathématiquement : si $F_1$ et $F_2$ sont primitives de $f$ alors $(F_1 - F_2)'' = 0$ donc $F_1 - F_2 = \\text{const}$."}],"final_answer_fr":"Infinité, à constante près"}}]},{"number":3,"title_fr":"Formes reconnaissables","points":5,"preamble_fr":"Calculer les primitives en reconnaissant $u''/u$, $u'' u^n$ ou $u'' e^u$.","questions":[{"number":1,"stem_fr":"$\\int \\dfrac{2x}{x^2 + 1}\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Forme $u''/u$ avec $u = x^2 + 1$ (et $u'' = 2x$). Primitive : $\\ln|u| + C$."},{"text_fr":"Comme $x^2 + 1 > 0$, on omet la valeur absolue : $\\ln(x^2 + 1) + C$."}],"final_answer_fr":"$\\ln(x^2+1) + C$"}},{"number":2,"stem_fr":"$\\int (2x + 1)^5\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Forme $u'' u^n$ avec $u = 2x + 1$, $u'' = 2$. Le facteur 2 manque — multiplier-diviser par 2."},{"text_fr":"$(2x + 1)^5 = \\dfrac{1}{2} \\cdot 2 (2x+1)^5$. Primitive : $\\dfrac{1}{2} \\cdot \\dfrac{(2x+1)^6}{6} = \\dfrac{(2x+1)^6}{12} + C$."}],"final_answer_fr":"$(2x+1)^6/12 + C$"}},{"number":3,"stem_fr":"$\\int x e^{x^2}\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Forme $u'' e^u$ avec $u = x^2$, $u'' = 2x$. Facteur 2 manquant : $x e^{x^2} = \\dfrac{1}{2} \\cdot 2x \\cdot e^{x^2}$."},{"text_fr":"Primitive : $\\dfrac{1}{2} e^{x^2} + C$. Vérif : $\\dfrac{d}{dx}\\left(\\frac{1}{2} e^{x^2}\\right) = \\dfrac{1}{2} \\cdot 2x e^{x^2} = x e^{x^2}$ ✓.","tip_fr":"Pour $u'' e^u$, la primitive est simplement $e^u$. Si le coefficient ne colle pas, ajuster par multiplication-division."}],"final_answer_fr":"$e^{x^2}/2 + C$"}}]},{"number":4,"title_fr":"Intégration par parties (introduction)","points":5,"preamble_fr":"On rappelle : $\\int u v'' = [u v] - \\int u'' v$.","questions":[{"number":1,"stem_fr":"Calculer $\\int x \\cos x\\,dx$.","points":3,"solution":{"steps":[{"text_fr":"**Choix** : $u = x$ (devient simple en dérivant) et $v'' = \\cos x$ (donc $v = \\sin x$)."},{"text_fr":"Application : $\\int x \\cos x\\,dx = x \\sin x - \\int 1 \\cdot \\sin x\\,dx = x \\sin x + \\cos x + C$."},{"text_fr":"Vérification : $(x \\sin x + \\cos x)'' = \\sin x + x \\cos x - \\sin x = x \\cos x$ ✓."}],"final_answer_fr":"$x \\sin x + \\cos x + C$"}},{"number":2,"stem_fr":"Calculer $\\int \\ln x\\,dx$ par IPP.","points":2,"solution":{"steps":[{"text_fr":"Astuce : $\\ln x = 1 \\cdot \\ln x$. Poser $u = \\ln x$ ($u'' = 1/x$) et $v'' = 1$ ($v = x$)."},{"text_fr":"$\\int \\ln x\\,dx = x \\ln x - \\int (1/x) \\cdot x\\,dx = x \\ln x - \\int 1\\,dx = x \\ln x - x + C$.","tip_fr":"**Astuce célèbre** : pour intégrer $\\ln$, l''écrire $1 \\cdot \\ln$ et faire une IPP."}],"final_answer_fr":"$x \\ln x - x + C$"}}]}]}'::jsonb WHERE code = 'pc_primitives';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Calcul intégral","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Intégrale définie via Newton-Leibniz : $\\int_a^b f = F(b) - F(a)$. Propriétés : linéarité, Chasles, positivité. Aires et valeur moyenne.","exercices":[{"number":1,"title_fr":"Calculs directs","points":5,"preamble_fr":"Calculer les intégrales.","questions":[{"number":1,"stem_fr":"$\\int_0^2 (x^2 + 1)\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Primitive : $F(x) = x^3/3 + x$."},{"text_fr":"$\\int_0^2 = F(2) - F(0) = (8/3 + 2) - 0 = 8/3 + 6/3 = 14/3$."}],"final_answer_fr":"$14/3$"}},{"number":2,"stem_fr":"$\\int_1^e \\dfrac{dx}{x}$.","points":1,"solution":{"steps":[{"text_fr":"Primitive : $\\ln x$. $\\int = \\ln e - \\ln 1 = 1 - 0 = 1$.","tip_fr":"**Définition historique de $e$** : $\\int_1^e dt/t = 1$. $e$ est le réel dont le logarithme népérien vaut 1."}],"final_answer_fr":"$\\int = 1$"}},{"number":3,"stem_fr":"$\\int_0^\\pi \\sin x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Primitive : $-\\cos x$. $\\int = -\\cos\\pi - (-\\cos 0) = 1 + 1 = 2$."}],"final_answer_fr":"$\\int = 2$"}},{"number":4,"stem_fr":"$\\int_0^1 e^x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Primitive : $e^x$. $\\int = e^1 - e^0 = e - 1 \\approx 1{,}718$."}],"final_answer_fr":"$\\int = e - 1$"}}]},{"number":2,"title_fr":"Propriétés (Chasles, linéarité)","points":5,"preamble_fr":"Utiliser les propriétés.","questions":[{"number":1,"stem_fr":"Sachant $\\int_0^3 f = 7$ et $\\int_3^5 f = 2$, calculer $\\int_0^5 f$.","points":1,"solution":{"steps":[{"text_fr":"**Relation de Chasles** : $\\int_a^c = \\int_a^b + \\int_b^c$. Donc $\\int_0^5 = 7 + 2 = 9$."}],"final_answer_fr":"$\\int = 9$"}},{"number":2,"stem_fr":"Sachant $\\int_0^1 f = 5$ et $\\int_0^1 g = 3$, calculer $\\int_0^1 (2f - 3g)$.","points":2,"solution":{"steps":[{"text_fr":"**Linéarité** : $\\int (\\alpha f + \\beta g) = \\alpha \\int f + \\beta \\int g$."},{"text_fr":"$\\int_0^1 (2f - 3g) = 2 \\cdot 5 - 3 \\cdot 3 = 10 - 9 = 1$."}],"final_answer_fr":"$\\int = 1$"}},{"number":3,"stem_fr":"Si $\\int_2^5 f = 4$, calculer $\\int_5^2 f$.","points":1,"solution":{"steps":[{"text_fr":"$\\int_a^b = -\\int_b^a$. Donc $\\int_5^2 f = -4$."}],"final_answer_fr":"$-4$"}},{"number":4,"stem_fr":"Positivité : si $f \\ge 0$ et $f$ continue non identiquement nulle sur $[a, b]$, que dire de $\\int_a^b f$ ?","points":1,"solution":{"steps":[{"text_fr":"$\\int_a^b f > 0$ strictement. La continuité + positivité non triviale garantit une aire strictement positive."}],"final_answer_fr":"$\\int > 0$"}}]},{"number":3,"title_fr":"Aire entre deux courbes","points":5,"preamble_fr":"Soient $f(x) = x^2 + 1$ et $g(x) = x + 3$.","questions":[{"number":1,"stem_fr":"Trouver les points d''intersection.","points":2,"solution":{"steps":[{"text_fr":"$f(x) = g(x) \\iff x^2 + 1 = x + 3 \\iff x^2 - x - 2 = 0 \\iff (x - 2)(x + 1) = 0$."},{"text_fr":"Solutions : $x = -1$ et $x = 2$. Points : $(-1, 2)$ et $(2, 5)$."}],"final_answer_fr":"$x = -1$ et $x = 2$"}},{"number":2,"stem_fr":"Calculer l''aire du domaine entre les deux courbes.","points":3,"solution":{"steps":[{"text_fr":"Sur $[-1, 2]$, on compare : à $x = 0$, $f(0) = 1$ et $g(0) = 3$ → $g \\ge f$ sur l''intervalle."},{"text_fr":"$A = \\int_{-1}^{2} (g - f)\\,dx = \\int_{-1}^{2} (x + 3 - x^2 - 1)\\,dx = \\int_{-1}^{2} (-x^2 + x + 2)\\,dx$."},{"text_fr":"Primitive : $-x^3/3 + x^2/2 + 2x$. En 2 : $-8/3 + 2 + 4 = -8/3 + 6 = 10/3$. En -1 : $1/3 + 1/2 - 2 = 2/6 + 3/6 - 12/6 = -7/6$."},{"text_fr":"Différence : $10/3 - (-7/6) = 20/6 + 7/6 = 27/6 = 9/2$.","tip_fr":"**Aire entre deux courbes** : $\\int_a^b |f - g|\\,dx$. En pratique, identifier laquelle est au-dessus puis ne pas mettre la valeur absolue."}],"final_answer_fr":"$A = 9/2$"}}]},{"number":4,"title_fr":"Valeur moyenne","points":5,"preamble_fr":"Valeur moyenne : $\\bar f = \\dfrac{1}{b - a} \\int_a^b f$.","questions":[{"number":1,"stem_fr":"Calculer la valeur moyenne de $f(x) = x^2$ sur $[0, 2]$.","points":2,"solution":{"steps":[{"text_fr":"$\\int_0^2 x^2\\,dx = [x^3/3]_0^2 = 8/3$."},{"text_fr":"$\\bar f = \\dfrac{1}{2 - 0} \\cdot \\dfrac{8}{3} = \\dfrac{4}{3}$."},{"text_fr":"**Interprétation** : si on remplaçait $f$ par sa moyenne constante $4/3$ sur $[0, 2]$, l''aire totale serait identique : $(4/3) \\times 2 = 8/3$ ✓."}],"final_answer_fr":"$\\bar f = 4/3$"}},{"number":2,"stem_fr":"Théorème de la moyenne : trouver $c \\in [0, 2]$ tel que $f(c) = \\bar f$.","points":2,"solution":{"steps":[{"text_fr":"On cherche $c^2 = 4/3$, soit $c = \\pm 2/\\sqrt 3$. La valeur dans $[0, 2]$ : $c = 2/\\sqrt 3 \\approx 1{,}155$."},{"text_fr":"**Théorème de la moyenne** : si $f$ est continue sur $[a, b]$, il existe $c \\in [a, b]$ tel que $f(c) = \\bar f$. Conséquence du TVI.","tip_fr":"Ce théorème garantit l''existence du point — utile pour les démonstrations, même si on ne sait pas calculer $c$ explicitement."}],"final_answer_fr":"$c = 2/\\sqrt 3$"}},{"number":3,"stem_fr":"Application physique : un mobile a vitesse $v(t) = 3 t^2$ m/s sur $[0, 4]$ secondes. Distance parcourue ?","points":1,"solution":{"steps":[{"text_fr":"Distance = $\\int_0^4 v(t)\\,dt = \\int_0^4 3 t^2\\,dt = [t^3]_0^4 = 64$ m."},{"text_fr":"Vérification : vitesse moyenne = $64/4 = 16$ m/s. $\\bar v = (1/4) \\int_0^4 3t^2 = 64/4 = 16$ ✓."}],"final_answer_fr":"$d = 64$ m"}}]}]}'::jsonb WHERE code = 'pc_integral_calc';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Nombres complexes (forme algébrique)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Forme algébrique $z = a + bi$ avec $i^2 = -1$. Module $|z| = \\sqrt{a^2 + b^2}$, conjugué $\\bar z = a - bi$, $z \\bar z = |z|^2$.","exercices":[{"number":1,"title_fr":"Opérations algébriques","points":5,"preamble_fr":"Soit $z_1 = 2 + 3i$ et $z_2 = 1 - i$.","questions":[{"number":1,"stem_fr":"Calculer $z_1 + z_2$, $z_1 \\cdot z_2$, $z_1/z_2$.","points":4,"solution":{"steps":[{"text_fr":"**Somme** : $(2 + 1) + (3 - 1)i = 3 + 2i$."},{"text_fr":"**Produit** : $(2 + 3i)(1 - i) = 2 - 2i + 3i - 3i^2 = 2 + i + 3 = 5 + i$ (utiliser $i^2 = -1$)."},{"text_fr":"**Quotient** : multiplier numérateur et dénominateur par le conjugué $\\bar z_2 = 1 + i$."},{"text_fr":"$\\dfrac{2 + 3i}{1 - i} = \\dfrac{(2 + 3i)(1 + i)}{(1 - i)(1 + i)} = \\dfrac{2 + 2i + 3i + 3i^2}{1 + 1} = \\dfrac{-1 + 5i}{2} = -\\dfrac{1}{2} + \\dfrac{5}{2} i$.","tip_fr":"Pour diviser deux complexes, toujours multiplier par le conjugué du dénominateur — ça rationalise (résultat avec dénominateur réel)."}],"final_answer_fr":"$3+2i$, $5+i$, $-1/2 + 5i/2$"}},{"number":2,"stem_fr":"Calculer $|z_1|$ et $|z_2|$.","points":1,"solution":{"steps":[{"text_fr":"$|z_1| = \\sqrt{2^2 + 3^2} = \\sqrt{13}$. $|z_2| = \\sqrt{1 + 1} = \\sqrt 2$."}],"final_answer_fr":"$\\sqrt{13}$ et $\\sqrt 2$"}}]},{"number":2,"title_fr":"Conjugué","points":5,"preamble_fr":"Pour $z = a + bi$, le conjugué est $\\bar z = a - bi$.","questions":[{"number":1,"stem_fr":"Démontrer $z + \\bar z = 2 \\text{Re}(z)$ et $z - \\bar z = 2i \\text{Im}(z)$.","points":2,"solution":{"steps":[{"text_fr":"$z + \\bar z = (a + bi) + (a - bi) = 2a = 2 \\text{Re}(z)$."},{"text_fr":"$z - \\bar z = (a + bi) - (a - bi) = 2bi = 2i \\text{Im}(z)$."},{"text_fr":"**Conséquences** : $z \\in \\mathbb{R} \\iff z = \\bar z$ ; $z$ imaginaire pur $\\iff z = -\\bar z$."}]}},{"number":2,"stem_fr":"Montrer que $z \\bar z = |z|^2$.","points":1,"solution":{"steps":[{"text_fr":"$z \\bar z = (a + bi)(a - bi) = a^2 - (bi)^2 = a^2 + b^2 = |z|^2$.","tip_fr":"Cette identité fondamentale justifie la technique ''multiplier par le conjugué'' pour rationaliser $1/z$."}],"final_answer_fr":"$z \\bar z = |z|^2 \\in \\mathbb{R}^+$"}},{"number":3,"stem_fr":"Calculer $1/z$ pour $z = 3 - 4i$.","points":2,"solution":{"steps":[{"text_fr":"$1/z = \\dfrac{\\bar z}{z \\bar z} = \\dfrac{3 + 4i}{|z|^2} = \\dfrac{3 + 4i}{9 + 16} = \\dfrac{3 + 4i}{25} = \\dfrac{3}{25} + \\dfrac{4}{25} i$."},{"text_fr":"Vérification : $z \\cdot (1/z) = (3 - 4i)(3/25 + 4i/25) = (9 + 12i - 12i + 16)/25 = 25/25 = 1$ ✓."}],"final_answer_fr":"$1/z = 3/25 + 4i/25$"}}]},{"number":3,"title_fr":"Équation du second degré","points":5,"preamble_fr":"Résoudre $(E) : z^2 + 4z + 13 = 0$ dans $\\mathbb{C}$.","questions":[{"number":1,"stem_fr":"Calculer le discriminant.","points":1,"solution":{"steps":[{"text_fr":"$\\Delta = b^2 - 4ac = 16 - 52 = -36$. $\\Delta < 0$ → deux racines complexes conjuguées."}],"final_answer_fr":"$\\Delta = -36$"}},{"number":2,"stem_fr":"Résoudre.","points":3,"solution":{"steps":[{"text_fr":"Pour $\\Delta < 0$ : racines $z = \\dfrac{-b \\pm i\\sqrt{-\\Delta}}{2a}$. Ici $\\sqrt{-\\Delta} = \\sqrt{36} = 6$."},{"text_fr":"$z = \\dfrac{-4 \\pm 6i}{2} = -2 \\pm 3i$."},{"text_fr":"$S = \\{-2 + 3i,\\, -2 - 3i\\}$ — racines conjuguées.","tip_fr":"Pour un trinôme à coefficients **réels**, les racines complexes vont toujours par paire de conjugués."}],"final_answer_fr":"$S = \\{-2 \\pm 3i\\}$"}},{"number":3,"stem_fr":"Vérification par Viète.","points":1,"solution":{"steps":[{"text_fr":"Somme $z_1 + z_2 = (-2 + 3i) + (-2 - 3i) = -4 = -b/a$ ✓. Produit $z_1 z_2 = (-2)^2 - (3i)^2 = 4 + 9 = 13 = c/a$ ✓."}]}}]},{"number":4,"title_fr":"Module et argument","points":5,"preamble_fr":"Soit $z = -1 + i \\sqrt 3$.","questions":[{"number":1,"stem_fr":"Calculer $|z|$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt{(-1)^2 + (\\sqrt 3)^2} = \\sqrt{1 + 3} = 2$."}],"final_answer_fr":"$|z| = 2$"}},{"number":2,"stem_fr":"Déterminer un argument $\\theta$ de $z$ (à $2\\pi$ près).","points":3,"solution":{"steps":[{"text_fr":"$\\cos\\theta = \\text{Re}(z)/|z| = -1/2$. $\\sin\\theta = \\text{Im}(z)/|z| = \\sqrt 3/2$."},{"text_fr":"Re < 0 et Im > 0 → $z$ dans le **2ème quadrant**. Les valeurs $\\cos\\theta = -1/2$ et $\\sin\\theta = \\sqrt 3/2$ correspondent à $\\theta = 2\\pi/3$."},{"text_fr":"Donc $\\arg z = 2\\pi/3$ (à $2\\pi$ près).","mistake_fr":"Une seule équation ($\\cos\\theta$ ou $\\sin\\theta$) ne suffit pas — il faut les deux pour identifier le quadrant et donc l''angle sans ambiguïté."}],"final_answer_fr":"$\\arg z = 2\\pi/3$"}},{"number":3,"stem_fr":"Représenter $z$ dans le plan complexe.","points":1,"solution":{"steps":[{"text_fr":"Point d''affixe $z$ : coordonnées $(-1, \\sqrt 3) \\approx (-1, 1{,}73)$. Sur le cercle de rayon 2 centré en O, dans le 2ème quadrant."}]}}]}]}'::jsonb WHERE code = 'pc_complex_algebra';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Forme trigonométrique et formule de Moivre","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Forme trigonométrique $z = r(\\cos\\theta + i\\sin\\theta)$, forme exponentielle $z = r e^{i\\theta}$, formule de Moivre $(e^{i\\theta})^n = e^{in\\theta}$, racines n-ièmes.","exercices":[{"number":1,"title_fr":"Passage à la forme exponentielle","points":5,"preamble_fr":"Mettre chaque complexe sous forme exponentielle.","questions":[{"number":1,"stem_fr":"$z = 1 + i$.","points":2,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt 2$. $\\cos\\theta = 1/\\sqrt 2$, $\\sin\\theta = 1/\\sqrt 2$ → $\\theta = \\pi/4$."},{"text_fr":"Forme exponentielle : $z = \\sqrt 2\\, e^{i\\pi/4}$."}],"final_answer_fr":"$z = \\sqrt 2\\, e^{i\\pi/4}$"}},{"number":2,"stem_fr":"$z = -2$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = 2$, $\\arg z = \\pi$ (axe réel négatif). Donc $z = 2 e^{i\\pi}$."},{"text_fr":"**Identité d''Euler** : $e^{i\\pi} = -1$, soit $e^{i\\pi} + 1 = 0$ — souvent appelée la plus belle formule des mathématiques."}],"final_answer_fr":"$z = 2 e^{i\\pi}$"}},{"number":3,"stem_fr":"$z = i$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = 1$, $\\arg z = \\pi/2$ → $z = e^{i\\pi/2}$."},{"text_fr":"Cohérent avec $i^2 = e^{i\\pi} = -1$ ✓."}],"final_answer_fr":"$z = e^{i\\pi/2}$"}},{"number":4,"stem_fr":"$z = -\\sqrt 3 + i$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt{3 + 1} = 2$. $\\cos\\theta = -\\sqrt 3/2$, $\\sin\\theta = 1/2$ → $\\theta = 5\\pi/6$."},{"text_fr":"$z = 2 e^{i 5\\pi/6}$."}],"final_answer_fr":"$z = 2 e^{i 5\\pi/6}$"}}]},{"number":2,"title_fr":"Formule de Moivre","points":5,"preamble_fr":"Utiliser $(e^{i\\theta})^n = e^{i n\\theta}$.","questions":[{"number":1,"stem_fr":"Calculer $(1 + i)^{10}$.","points":3,"solution":{"steps":[{"text_fr":"$1 + i = \\sqrt 2\\, e^{i\\pi/4}$."},{"text_fr":"$(1 + i)^{10} = (\\sqrt 2)^{10} \\cdot e^{i \\cdot 10\\pi/4} = 2^5 \\cdot e^{i 5\\pi/2} = 32 \\cdot e^{i\\pi/2}$ (car $5\\pi/2 = 2\\pi + \\pi/2$)."},{"text_fr":"$e^{i\\pi/2} = i$. Donc $(1+i)^{10} = 32 i$.","tip_fr":"Pour des puissances élevées, la forme exponentielle est beaucoup plus rapide que le développement binomial."}],"final_answer_fr":"$(1+i)^{10} = 32i$"}},{"number":2,"stem_fr":"Établir l''identité $\\cos(2\\theta) = \\cos^2\\theta - \\sin^2\\theta$.","points":2,"solution":{"steps":[{"text_fr":"$e^{i 2\\theta} = (e^{i\\theta})^2 = (\\cos\\theta + i\\sin\\theta)^2 = \\cos^2\\theta + 2i\\sin\\theta\\cos\\theta + (i\\sin\\theta)^2$."},{"text_fr":"$(i\\sin\\theta)^2 = -\\sin^2\\theta$. Donc $e^{i 2\\theta} = (\\cos^2\\theta - \\sin^2\\theta) + 2i\\sin\\theta\\cos\\theta$."},{"text_fr":"Identifier parties réelle et imaginaire : $\\cos(2\\theta) = \\cos^2\\theta - \\sin^2\\theta$ et $\\sin(2\\theta) = 2\\sin\\theta\\cos\\theta$.","tip_fr":"Les identités trigonométriques classiques sont des conséquences directes de Moivre — pas besoin de les mémoriser séparément."}]}}]},{"number":3,"title_fr":"Racines n-ièmes","points":5,"preamble_fr":"Résoudre $z^3 = 1$ dans $\\mathbb{C}$.","questions":[{"number":1,"stem_fr":"Trouver les 3 racines cubiques de l''unité.","points":4,"solution":{"steps":[{"text_fr":"$1 = e^{i \\cdot 0}$. Cherchons $z = r e^{i\\theta}$ avec $r^3 = 1$ et $3\\theta \\equiv 0 \\pmod{2\\pi}$."},{"text_fr":"$r = 1$ (réel positif), $\\theta = 2k\\pi/3$ pour $k = 0, 1, 2$."},{"text_fr":"$z_0 = e^{i \\cdot 0} = 1$ ; $z_1 = e^{i 2\\pi/3} = -1/2 + i\\sqrt 3/2$ ; $z_2 = e^{i 4\\pi/3} = -1/2 - i\\sqrt 3/2$."},{"text_fr":"**Géométriquement** : les 3 racines forment un **triangle équilatéral** inscrit dans le cercle unité, sommets espacés de $2\\pi/3$.","tip_fr":"Les $n$ racines n-ièmes de l''unité forment un polygone régulier à $n$ sommets sur le cercle unité, espacés de $2\\pi/n$."}],"final_answer_fr":"$\\{1,\\, -1/2 \\pm i\\sqrt 3/2\\}$"}},{"number":2,"stem_fr":"Vérifier que la somme des 3 racines vaut 0.","points":1,"solution":{"steps":[{"text_fr":"Somme : $1 + (-1/2 + i\\sqrt 3/2) + (-1/2 - i\\sqrt 3/2) = 1 - 1 + 0 = 0$ ✓."},{"text_fr":"Cohérent avec Viète : pour $z^3 - 1 = 0$, somme des racines = $-(\\text{coeff de }z^2)/(\\text{coeff dominant}) = -0/1 = 0$."}]}}]},{"number":4,"title_fr":"Application — équation $z^n = a$","points":5,"preamble_fr":"Résoudre $z^4 = -16$.","questions":[{"number":1,"stem_fr":"Mettre $-16$ sous forme exponentielle.","points":1,"solution":{"steps":[{"text_fr":"$-16 = 16 \\cdot (-1) = 16 e^{i\\pi}$."}],"final_answer_fr":"$-16 = 16 e^{i\\pi}$"}},{"number":2,"stem_fr":"Trouver les 4 racines.","points":4,"solution":{"steps":[{"text_fr":"$z = r e^{i\\theta}$ avec $r^4 = 16$ et $4\\theta \\equiv \\pi \\pmod{2\\pi}$."},{"text_fr":"$r = 2$ (réelle positive). $\\theta = \\pi/4 + k\\pi/2$ pour $k = 0, 1, 2, 3$ : $\\theta = \\pi/4, 3\\pi/4, 5\\pi/4, 7\\pi/4$."},{"text_fr":"Racines : $z_k = 2 e^{i(\\pi/4 + k\\pi/2)}$. En forme algébrique : $z_0 = \\sqrt 2(1 + i)$, $z_1 = \\sqrt 2(-1 + i)$, $z_2 = \\sqrt 2(-1 - i)$, $z_3 = \\sqrt 2(1 - i)$."},{"text_fr":"Vérification : $z_0^4 = (\\sqrt 2(1+i))^4 = (\\sqrt 2)^4 (1+i)^4 = 4 \\cdot (2i)^2 = 4 \\cdot (-4) = -16$ ✓.","tip_fr":"**Méthode générale** pour $z^n = a$ avec $a = |a| e^{i\\alpha}$ : $n$ racines $z_k = |a|^{1/n} e^{i(\\alpha + 2k\\pi)/n}$."}],"final_answer_fr":"$z_k = 2 e^{i(\\pi/4 + k\\pi/2)}$, $k=0..3$"}}]}]}'::jsonb WHERE code = 'pc_complex_trig';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Équations différentielles du 1er ordre","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"EDO $y'' = ay$ → $y = C e^{ax}$. EDO $y'' = ay + b$ → solution = homogène + particulière. Applications : refroidissement, charge RC, désintégration.","exercices":[{"number":1,"title_fr":"EDO homogène","points":5,"preamble_fr":"Soit $(E) : y'' = 3y$.","questions":[{"number":1,"stem_fr":"Donner la solution générale.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : la solution générale de $y'' = ay$ est $y(x) = C e^{ax}$, $C \\in \\mathbb{R}$."},{"text_fr":"Ici $a = 3$ : $y(x) = C e^{3x}$."}],"final_answer_fr":"$y(x) = C e^{3x}$"}},{"number":2,"stem_fr":"Solution vérifiant $y(0) = 2$.","points":2,"solution":{"steps":[{"text_fr":"$y(0) = C = 2$. Donc $y(x) = 2 e^{3x}$."}],"final_answer_fr":"$y(x) = 2 e^{3x}$"}},{"number":3,"stem_fr":"À quel instant $y$ atteint-elle 100 ?","points":1,"solution":{"steps":[{"text_fr":"$2 e^{3x} = 100 \\iff e^{3x} = 50 \\iff x = \\dfrac{\\ln 50}{3} \\approx 1{,}30$."}],"final_answer_fr":"$x \\approx 1{,}30$"}}]},{"number":2,"title_fr":"EDO avec second membre constant","points":5,"preamble_fr":"Soit $(E) : y'' = -2y + 10$.","questions":[{"number":1,"stem_fr":"Trouver une solution particulière constante $y_p$.","points":1,"solution":{"steps":[{"text_fr":"$y_p$ constante → $y_p'' = 0$. $0 = -2 y_p + 10 \\iff y_p = 5$."}],"final_answer_fr":"$y_p = 5$"}},{"number":2,"stem_fr":"Solution générale de l''équation homogène $y'' = -2y$.","points":1,"solution":{"steps":[{"text_fr":"$y_h(x) = C e^{-2x}$."}],"final_answer_fr":"$y_h = C e^{-2x}$"}},{"number":3,"stem_fr":"Donner la solution générale de $(E)$, puis la solution avec $y(0) = 8$.","points":3,"solution":{"steps":[{"text_fr":"**Principe de superposition** : $y = y_h + y_p = C e^{-2x} + 5$."},{"text_fr":"$y(0) = C + 5 = 8 \\iff C = 3$. Donc $y(x) = 3 e^{-2x} + 5$."},{"text_fr":"**Comportement asymptotique** : $\\lim_{+\\infty} y = 5$ — la solution tend vers l''équilibre $y_p$. Le terme transitoire $3 e^{-2x}$ s''atténue.","tip_fr":"Pour une EDO linéaire à coeffs constants, la solution = transitoire (terme en $e^{at}$) + régime permanent (solution particulière)."}],"final_answer_fr":"$y(x) = 3 e^{-2x} + 5$"}}]},{"number":3,"title_fr":"Loi de Newton — refroidissement","points":5,"preamble_fr":"Un café à 80°C est posé dans une pièce à 20°C. La température $T(t)$ vérifie $T''(t) = -k(T - 20)$ avec $k > 0$.","questions":[{"number":1,"stem_fr":"Résoudre l''EDO avec $T(0) = 80$.","points":3,"solution":{"steps":[{"text_fr":"Poser $\\theta = T - 20$ (écart à l''ambiance). $\\theta'' = T'' = -k(T - 20) = -k\\theta$."},{"text_fr":"Solution : $\\theta(t) = C e^{-kt}$. Condition initiale : $\\theta(0) = T(0) - 20 = 60 = C$."},{"text_fr":"Retour à T : $T(t) = 20 + 60 e^{-kt}$."}],"final_answer_fr":"$T(t) = 20 + 60 e^{-kt}$"}},{"number":2,"stem_fr":"Si $T(5) = 50$°C, déterminer $k$ et la ''demi-vie thermique''.","points":2,"solution":{"steps":[{"text_fr":"$T(5) = 50 \\iff 20 + 60 e^{-5k} = 50 \\iff e^{-5k} = 1/2 \\iff -5k = -\\ln 2 \\iff k = \\dfrac{\\ln 2}{5} \\approx 0{,}139\\,\\text{min}^{-1}$."},{"text_fr":"Demi-vie thermique : $t_{1/2} = \\ln 2 / k = 5$ minutes. L''écart à l''ambiance est divisé par 2 toutes les 5 min.","tip_fr":"**Loi de Newton du refroidissement** : structure identique à la désintégration radioactive et à la décharge RC (toutes des cinétiques d''ordre 1)."}],"final_answer_fr":"$k \\approx 0{,}139$/min"}}]},{"number":4,"title_fr":"Désintégration radioactive","points":5,"preamble_fr":"Le nombre de noyaux $N(t)$ d''un isotope vérifie $N''(t) = -\\lambda N(t)$. À $t = 0$, $N_0 = 10^{12}$ noyaux ; demi-vie 8 jours.","questions":[{"number":1,"stem_fr":"Donner l''expression de $N(t)$.","points":2,"solution":{"steps":[{"text_fr":"EDO de référence $N'' = -\\lambda N$ → $N(t) = N_0 e^{-\\lambda t} = 10^{12} e^{-\\lambda t}$."},{"text_fr":"Demi-vie $t_{1/2}$ : $N(t_{1/2}) = N_0/2 \\iff e^{-\\lambda t_{1/2}} = 1/2 \\iff \\lambda = \\ln 2 / t_{1/2}$."},{"text_fr":"Avec $t_{1/2} = 8$ jours : $\\lambda = \\ln 2 / 8 \\approx 0{,}0866\\,\\text{jour}^{-1}$."}],"final_answer_fr":"$N(t) = 10^{12} e^{-\\lambda t}$, $\\lambda = \\ln 2/8$"}},{"number":2,"stem_fr":"Au bout de combien de temps reste-t-il 1% des noyaux initiaux ?","points":2,"solution":{"steps":[{"text_fr":"$N(t)/N_0 = 0{,}01 \\iff e^{-\\lambda t} = 0{,}01 \\iff t = -\\ln(0{,}01)/\\lambda = \\ln 100 / \\lambda$."},{"text_fr":"$\\ln 100 \\approx 4{,}605$. $t \\approx 4{,}605 / 0{,}0866 \\approx 53\\,\\text{jours}$, soit environ 6,6 demi-vies (\\(53/8\\))."},{"text_fr":"**Vérification** : après $n$ demi-vies, il reste $1/2^n$ ; $1/2^7 \\approx 0{,}008$, ce qui est cohérent avec ≈ 1% à $n \\approx 6{,}6$.","tip_fr":"**Règle de chiffre** : il reste 1% après ≈ 7 demi-vies ($1/2^7 = 1/128 \\approx 0{,}8\\%$). Utile pour estimer rapidement."}],"final_answer_fr":"$t \\approx 53$ jours"}},{"number":3,"stem_fr":"Calculer $\\lim_{t \\to +\\infty} N(t)$ et interpréter.","points":1,"solution":{"steps":[{"text_fr":"$\\lim_{+\\infty} e^{-\\lambda t} = 0$ donc $\\lim N(t) = 0$. La désintégration est asymptotiquement complète mais ne touche jamais 0 mathématiquement."}],"final_answer_fr":"$\\lim N = 0$"}}]}]}'::jsonb WHERE code = 'pc_ode_first_order';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Loi binomiale","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Schéma de Bernoulli (n essais identiques indépendants à 2 issues, succès $p$), loi binomiale $\\mathcal B(n, p)$. Espérance $E = np$, variance $V = np(1-p)$.","exercices":[{"number":1,"title_fr":"Schéma de Bernoulli","points":5,"preamble_fr":"Un examen comporte 20 QCM, chacune à 4 réponses dont 1 correcte. Un candidat répond au hasard. Soit X = nombre de bonnes réponses.","questions":[{"number":1,"stem_fr":"Justifier que $X \\sim \\mathcal B(n, p)$ et préciser $n, p$.","points":2,"solution":{"steps":[{"text_fr":"**Schéma de Bernoulli** : $n$ essais identiques, indépendants, à 2 issues ''succès/échec'', succès de probabilité $p$ constante."},{"text_fr":"Ici : $n = 20$ questions, indépendantes, succès = ''bonne réponse'' avec $p = 1/4$. Donc $X \\sim \\mathcal B(20, 1/4)$."}],"final_answer_fr":"$X \\sim \\mathcal B(20, 1/4)$"}},{"number":2,"stem_fr":"Calculer $E(X)$ et $V(X)$.","points":2,"solution":{"steps":[{"text_fr":"**Formules binomiales** : $E(X) = np$, $V(X) = np(1-p)$."},{"text_fr":"$E(X) = 20 \\times 1/4 = 5$. $V(X) = 20 \\times 1/4 \\times 3/4 = 15/4 = 3{,}75$. $\\sigma = \\sqrt V \\approx 1{,}94$."},{"text_fr":"**Interprétation** : en répondant au hasard, on attend en moyenne 5/20 (= 25% = $p$). La plupart des candidats au hasard obtiennent entre $E - 2\\sigma \\approx 1$ et $E + 2\\sigma \\approx 9$ bonnes réponses."}],"final_answer_fr":"$E = 5$, $V = 3{,}75$"}},{"number":3,"stem_fr":"Calculer $P(X = 10)$.","points":1,"solution":{"steps":[{"text_fr":"**Formule** : $P(X = k) = \\binom{n}{k} p^k (1-p)^{n-k}$."},{"text_fr":"$P(X = 10) = \\binom{20}{10} (1/4)^{10} (3/4)^{10} \\approx 184756 \\times 9{,}54 \\cdot 10^{-7} \\times 0{,}0563 \\approx 0{,}0099 \\approx 1\\%$."}],"final_answer_fr":"$P(X = 10) \\approx 1\\%$"}}]},{"number":2,"title_fr":"Bernoulli somme = binomiale","points":5,"preamble_fr":"Soient $X_1, \\ldots, X_n$ des Bernoulli indépendantes de paramètre $p$.","questions":[{"number":1,"stem_fr":"Que vaut $S = X_1 + X_2 + \\dots + X_n$ en termes de loi ?","points":3,"solution":{"steps":[{"text_fr":"Chaque $X_i$ vaut 0 ou 1, avec $P(X_i = 1) = p$. La somme $S$ compte le nombre de ''1'' parmi les $n$ tirages."},{"text_fr":"C''est **exactement la définition** d''une variable binomiale : $S \\sim \\mathcal B(n, p)$."},{"text_fr":"**Conséquence immédiate** : $E(S) = \\sum E(X_i) = n \\cdot p$ (linéarité). $V(S) = \\sum V(X_i) = n \\cdot p(1-p)$ (indépendance).","tip_fr":"La binomiale n''est rien d''autre qu''une somme de $n$ Bernoulli. Cette décomposition permet de retrouver les formules d''espérance/variance sans calcul direct."}],"final_answer_fr":"$S \\sim \\mathcal B(n, p)$"}},{"number":2,"stem_fr":"Application : on tire 50 cartes **avec remise** dans un jeu de 52. Espérance du nombre d''as obtenus.","points":2,"solution":{"steps":[{"text_fr":"Chaque tirage = Bernoulli avec $p = 4/52 = 1/13$ (4 as parmi 52 cartes)."},{"text_fr":"Nombre d''as = somme de 50 Bernoulli indépendantes → $\\mathcal B(50, 1/13)$. Espérance : $E = np = 50/13 \\approx 3{,}85$.","mistake_fr":"Sans remise, les tirages ne seraient plus indépendants ($p$ changerait à chaque tirage). La binomiale s''applique seulement avec remise."}],"final_answer_fr":"$E \\approx 3{,}85$ as"}}]},{"number":3,"title_fr":"Probabilités cumulées","points":5,"preamble_fr":"Dans une usine, 2% des pièces sont défectueuses. On contrôle un lot de 100 pièces. Soit $D$ le nombre de défectueuses.","questions":[{"number":1,"stem_fr":"Justifier $D \\sim \\mathcal B(100,\\, 0{,}02)$ et calculer $E(D)$, $\\sigma(D)$.","points":2,"solution":{"steps":[{"text_fr":"Modèle : chaque pièce est indépendamment défectueuse avec proba 0,02. Le contrôle = 100 tirages indépendants."},{"text_fr":"$E(D) = 100 \\times 0{,}02 = 2$. $V(D) = 100 \\times 0{,}02 \\times 0{,}98 = 1{,}96$, $\\sigma \\approx 1{,}40$."}],"final_answer_fr":"$E = 2$, $\\sigma \\approx 1{,}40$"}},{"number":2,"stem_fr":"Calculer $P(D = 0)$ — probabilité qu''aucune pièce ne soit défectueuse.","points":2,"solution":{"steps":[{"text_fr":"$P(D = 0) = \\binom{100}{0} \\cdot 0{,}02^0 \\cdot 0{,}98^{100} = 0{,}98^{100}$."},{"text_fr":"$0{,}98^{100} = e^{100 \\ln 0{,}98} \\approx e^{100 \\times (-0{,}0202)} = e^{-2{,}02} \\approx 0{,}133$."},{"text_fr":"Donc $P(D = 0) \\approx 13\\%$. Plutôt faible — un lot ''parfait'' est rare avec un taux de défaut de 2%."}],"final_answer_fr":"$P(D=0) \\approx 0{,}133$"}},{"number":3,"stem_fr":"Calculer $P(D \\le 1)$ — au plus 1 défectueuse.","points":1,"solution":{"steps":[{"text_fr":"$P(D \\le 1) = P(D = 0) + P(D = 1)$. $P(D = 1) = \\binom{100}{1} \\cdot 0{,}02 \\cdot 0{,}98^{99} = 100 \\times 0{,}02 \\times 0{,}98^{99}$."},{"text_fr":"$0{,}98^{99} \\approx 0{,}136$. Donc $P(D = 1) \\approx 2 \\times 0{,}136 = 0{,}271$. Total : $P(D \\le 1) \\approx 0{,}133 + 0{,}271 = 0{,}404$."}],"final_answer_fr":"$P(D \\le 1) \\approx 0{,}40$"}}]},{"number":4,"title_fr":"Espérance de jeu","points":5,"preamble_fr":"Un jeu : on gagne 10 DH avec proba 0,1 ; 2 DH avec proba 0,4 ; on perd 3 DH avec proba 0,5.","questions":[{"number":1,"stem_fr":"Calculer l''espérance de gain par partie.","points":3,"solution":{"steps":[{"text_fr":"Soit $G$ le gain (positif ou négatif). $E(G) = \\sum g \\cdot P(G = g)$."},{"text_fr":"$E(G) = 10 \\times 0{,}1 + 2 \\times 0{,}4 + (-3) \\times 0{,}5 = 1 + 0{,}8 - 1{,}5 = 0{,}3\\,\\text{DH}$."},{"text_fr":"Jeu **favorable** (espérance > 0). Sur le long terme, on gagne en moyenne 0,30 DH par partie."}],"final_answer_fr":"$E(G) = 0{,}30$ DH"}},{"number":2,"stem_fr":"Quel doit être le coût d''entrée $c$ pour un jeu équitable ?","points":2,"solution":{"steps":[{"text_fr":"**Jeu équitable** : espérance du gain net $G - c$ nulle, soit $E(G) - c = 0 \\iff c = E(G) = 0{,}30$ DH."},{"text_fr":"En pratique, un casino fixerait $c > 0{,}30$ pour avoir une espérance favorable à la maison — c''est leur marge.","tip_fr":"Loi des grands nombres : sur un grand nombre de parties, la moyenne empirique converge vers $E(G)$ — d''où l''importance de cette grandeur pour évaluer un jeu."}],"final_answer_fr":"$c = 0{,}30$ DH"}}]}]}'::jsonb WHERE code = 'pc_prob_binomial';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Lois de Newton","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Trois lois : 1ère (inertie), 2ème $\\sum \\vec F = m \\vec a$, 3ème (action-réaction). Applications : équilibre, plan incliné, poulies, mouvement circulaire.","exercices":[{"number":1,"title_fr":"Équilibre statique","points":5,"preamble_fr":"Une caisse de 50 kg est suspendue par deux cordes formant chacune un angle de 30° avec la verticale. Prendre $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Faire le bilan des forces sur la caisse.","points":1,"solution":{"steps":[{"text_fr":"Forces : poids $\\vec P$ vertical descendant ($P = mg = 500\\,\\text{N}$). Tensions $\\vec T_1$ et $\\vec T_2$ le long des cordes, vers le haut. Par symétrie, $T_1 = T_2 = T$."}]}},{"number":2,"stem_fr":"Calculer la tension dans chaque corde.","points":3,"solution":{"steps":[{"text_fr":"**1ère loi de Newton** (équilibre) : $\\sum \\vec F = \\vec 0$."},{"text_fr":"Projection sur la verticale : $2 T \\cos 30° - P = 0$. Soit $2 T \\cdot \\dfrac{\\sqrt 3}{2} = 500$, donc $T = \\dfrac{500}{\\sqrt 3} \\approx 289\\,\\text{N}$."},{"text_fr":"Projection horizontale : les composantes $\\pm T \\sin 30°$ s''annulent ✓.","tip_fr":"Quand l''angle des cordes $\\to 90°$ (cordes horizontales), $\\cos \\to 0$ et $T \\to \\infty$. C''est pourquoi tendre une corde demande des forces énormes."}],"final_answer_fr":"$T \\approx 289$ N"}},{"number":3,"stem_fr":"Si l''angle passe à 60°, quelle est la nouvelle tension ?","points":1,"solution":{"steps":[{"text_fr":"$T = P/(2\\cos 60°) = 500/(2 \\times 0{,}5) = 500\\,\\text{N}$. La tension a augmenté de 73% en doublant l''écartement."}],"final_answer_fr":"$T = 500$ N"}}]},{"number":2,"title_fr":"Plan incliné avec frottement","points":5,"preamble_fr":"Un bloc de 10 kg est posé sur un plan incliné à $\\alpha = 25°$. Coefficient de frottement statique $\\mu_s = 0{,}5$, $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Le bloc glisse-t-il spontanément ?","points":3,"solution":{"steps":[{"text_fr":"Composante du poids selon le plan (qui tire le bloc vers le bas) : $P_\\parallel = mg \\sin\\alpha = 10 \\times 10 \\times \\sin 25° \\approx 42{,}3\\,\\text{N}$."},{"text_fr":"Réaction normale : $R = mg \\cos\\alpha = 100 \\times \\cos 25° \\approx 90{,}6\\,\\text{N}$. Frottement statique maximal : $f_\\text{max} = \\mu_s R = 0{,}5 \\times 90{,}6 \\approx 45{,}3\\,\\text{N}$."},{"text_fr":"Comparaison : $P_\\parallel \\approx 42{,}3 < f_\\text{max} \\approx 45{,}3$. Le frottement compense exactement → **le bloc reste statique**.","tip_fr":"**Critère d''équilibre sur plan incliné** : $\\tan\\alpha < \\mu_s$. Ici $\\tan 25° \\approx 0{,}466 < 0{,}5$ ✓."}],"final_answer_fr":"Non, équilibre"}},{"number":2,"stem_fr":"Calculer l''angle critique $\\alpha_c$ à partir duquel le bloc glisse.","points":2,"solution":{"steps":[{"text_fr":"Au seuil : $\\tan\\alpha_c = \\mu_s \\iff \\alpha_c = \\arctan(\\mu_s) = \\arctan(0{,}5) \\approx 26{,}57°$."},{"text_fr":"Au-delà, la composante du poids dépasse la friction maximale et le bloc accélère."}],"final_answer_fr":"$\\alpha_c \\approx 26{,}6°$"}}]},{"number":3,"title_fr":"Système avec poulie","points":5,"preamble_fr":"Deux blocs de masses $m_1 = 5\\,\\text{kg}$ et $m_2 = 3\\,\\text{kg}$ sont reliés par un fil inextensible passant sur une poulie sans frottement. Le bloc lourd descend.","questions":[{"number":1,"stem_fr":"Déterminer l''accélération du système et la tension du fil.","points":4,"solution":{"steps":[{"text_fr":"**2ème loi de Newton** sur chaque bloc, en orientant positivement le sens du mouvement."},{"text_fr":"Bloc 1 (5 kg, descend) : $m_1 g - T = m_1 a \\iff 50 - T = 5a$."},{"text_fr":"Bloc 2 (3 kg, monte) : $T - m_2 g = m_2 a \\iff T - 30 = 3a$."},{"text_fr":"Sommer : $50 - 30 = 8a \\Rightarrow a = 2{,}5\\,\\text{m/s}^2$. Tension : $T = 30 + 3 \\times 2{,}5 = 37{,}5\\,\\text{N}$.","tip_fr":"Vérification : $T < m_1 g$ (le bloc 1 descend) et $T > m_2 g$ (le bloc 2 monte). Ici $30 < 37{,}5 < 50$ ✓."}],"final_answer_fr":"$a = 2{,}5$ m/s², $T = 37{,}5$ N"}},{"number":2,"stem_fr":"Vitesse du système après 2 s, partant du repos.","points":1,"solution":{"steps":[{"text_fr":"Mouvement uniformément accéléré : $v = a t = 2{,}5 \\times 2 = 5\\,\\text{m/s}$."}],"final_answer_fr":"$v = 5$ m/s"}}]},{"number":4,"title_fr":"Mouvement circulaire uniforme","points":5,"preamble_fr":"Un satellite tourne autour de la Terre à altitude $h = 400\\,\\text{km}$ (ISS). $R_T = 6400\\,\\text{km}$, $g_0 = 9{,}81\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Gravité $g$ à cette altitude.","points":2,"solution":{"steps":[{"text_fr":"Loi de gravitation : $g \\propto 1/r^2$. $g/g_0 = (R_T/(R_T + h))^2 = (6400/6800)^2 \\approx 0{,}886$."},{"text_fr":"$g \\approx 9{,}81 \\times 0{,}886 \\approx 8{,}69\\,\\text{m/s}^2$. Encore 89% de $g_0$ — l''apesanteur orbitale n''est pas une absence de gravité mais une chute libre permanente."}],"final_answer_fr":"$g \\approx 8{,}69$ m/s²"}},{"number":2,"stem_fr":"Vitesse orbitale et période de révolution.","points":3,"solution":{"steps":[{"text_fr":"**Mouvement circulaire uniforme** : la gravité fournit la force centripète. $m g = m v^2 / r \\Rightarrow v = \\sqrt{g r}$ avec $r = R_T + h = 6{,}8 \\times 10^6\\,\\text{m}$."},{"text_fr":"$v = \\sqrt{8{,}69 \\times 6{,}8 \\times 10^6} \\approx 7690\\,\\text{m/s} \\approx 27\\,700\\,\\text{km/h}$."},{"text_fr":"Période : $T = 2\\pi r / v = 2\\pi \\times 6{,}8 \\times 10^6 / 7690 \\approx 5556\\,\\text{s} \\approx 92{,}6\\,\\text{min}$. L''ISS fait un tour de Terre en ~93 min.","tip_fr":"Valeurs à retenir : vitesse orbitale ~28000 km/h, période ~90 min pour les orbites basses. Ordres de grandeur classiques."}],"final_answer_fr":"$v \\approx 7690$ m/s, $T \\approx 93$ min"}}]}]}'::jsonb WHERE code = 'pc_newton_laws';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Mouvement d''un projectile","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Chute libre ($y = \\frac{1}{2} g t^2$), tir parabolique (séparation des composantes $x, y$), portée, hauteur maximale.","exercices":[{"number":1,"title_fr":"Chute libre","points":5,"preamble_fr":"Une pierre est lâchée du haut d''une falaise sans vitesse initiale. Elle touche le sol après 4 s. $g = 9{,}8\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Hauteur de la falaise.","points":2,"solution":{"steps":[{"text_fr":"**MRUA en chute libre** : $h = \\dfrac{1}{2} g t^2 = 0{,}5 \\times 9{,}8 \\times 16 = 78{,}4\\,\\text{m}$."}],"final_answer_fr":"$h = 78{,}4$ m"}},{"number":2,"stem_fr":"Vitesse à l''impact.","points":2,"solution":{"steps":[{"text_fr":"$v = g t = 9{,}8 \\times 4 = 39{,}2\\,\\text{m/s} \\approx 141\\,\\text{km/h}$."},{"text_fr":"Vérification énergétique : $mgh = \\frac{1}{2} m v^2 \\Rightarrow v = \\sqrt{2gh} = \\sqrt{2 \\times 9{,}8 \\times 78{,}4} \\approx 39{,}2\\,\\text{m/s}$ ✓.","tip_fr":"Deux approches : cinématique ($v = g t$) ou énergétique ($v = \\sqrt{2 g h}$). Donnent le même résultat — utile pour double-vérification."}],"final_answer_fr":"$v \\approx 39{,}2$ m/s"}},{"number":3,"stem_fr":"Distance parcourue durant la 3ème seconde.","points":1,"solution":{"steps":[{"text_fr":"$\\Delta h = h(3) - h(2) = \\frac{1}{2} g (9 - 4) = 0{,}5 \\times 9{,}8 \\times 5 = 24{,}5\\,\\text{m}$."},{"text_fr":"**Observation** : les distances parcourues à chaque seconde sont proportionnelles aux nombres impairs (4,9 m, 14,7 m, 24,5 m, 34,3 m ...) — propriété galiléenne de la chute libre."}],"final_answer_fr":"$\\Delta h = 24{,}5$ m"}}]},{"number":2,"title_fr":"Tir parabolique — équations horaires","points":5,"preamble_fr":"Un projectile est lancé avec vitesse initiale $v_0 = 25\\,\\text{m/s}$ à un angle $\\alpha = 30°$ au-dessus de l''horizontale. $g = 9{,}81\\,\\text{m/s}^2$, origine au point de lancement.","questions":[{"number":1,"stem_fr":"Équations horaires.","points":4,"subparts":[{"letter":"a","stem_fr":"Donner les composantes initiales $v_{0x}, v_{0y}$.","points":1,"solution":{"steps":[{"text_fr":"$v_{0x} = v_0 \\cos\\alpha = 25 \\times \\dfrac{\\sqrt 3}{2} \\approx 21{,}65\\,\\text{m/s}$."},{"text_fr":"$v_{0y} = v_0 \\sin\\alpha = 25 \\times 0{,}5 = 12{,}5\\,\\text{m/s}$."}],"final_answer_fr":"$v_{0x} \\approx 21{,}65$, $v_{0y} = 12{,}5$"}},{"letter":"b","stem_fr":"Équations horaires $x(t), y(t)$.","points":2,"solution":{"steps":[{"text_fr":"**Axe x (horizontal, sans force)** : MRU, $x(t) = v_{0x} t \\approx 21{,}65\\,t$."},{"text_fr":"**Axe y (vertical, poids)** : MRUA, $y(t) = v_{0y} t - \\dfrac{1}{2} g t^2 = 12{,}5\\,t - 4{,}905\\,t^2$."}]}},{"letter":"c","stem_fr":"Trouver l''équation de la trajectoire $y(x)$.","points":1,"solution":{"steps":[{"text_fr":"De $x = v_{0x} t$ : $t = x/v_{0x}$. Substituer dans $y(t)$ :"},{"text_fr":"$y = v_{0y} \\dfrac{x}{v_{0x}} - \\dfrac{g}{2} \\dfrac{x^2}{v_{0x}^2} = x \\tan\\alpha - \\dfrac{g x^2}{2 v_0^2 \\cos^2\\alpha}$."},{"text_fr":"C''est une **parabole** — d''où le nom ''tir parabolique''.","tip_fr":"Forme générale : $y = (\\tan\\alpha) x - \\dfrac{g}{2 v_0^2 \\cos^2\\alpha} x^2$. À mémoriser."}]}}]}]},{"number":3,"title_fr":"Portée et hauteur maximale","points":5,"preamble_fr":"Mêmes données qu''à l''Ex 2.","questions":[{"number":1,"stem_fr":"Calculer la portée $x_p$ (distance horizontale atteinte au retour au sol).","points":3,"solution":{"steps":[{"text_fr":"Durée totale du vol : $y(t_p) = 0\\) avec $t_p > 0\\), soit $t_p (v_{0y} - g t_p/2) = 0 \\Rightarrow t_p = 2 v_{0y}/g = 25/9{,}81 \\approx 2{,}55\\,\\text{s}$."},{"text_fr":"Portée : $x_p = v_{0x} \\cdot t_p \\approx 21{,}65 \\times 2{,}55 \\approx 55{,}2\\,\\text{m}$."},{"text_fr":"**Formule synthétique** : $x_p = \\dfrac{v_0^2 \\sin(2\\alpha)}{g} = \\dfrac{625 \\times \\sin 60°}{9{,}81} \\approx 55{,}2\\,\\text{m}$ ✓.","tip_fr":"Portée maximale pour $\\sin(2\\alpha) = 1 \\iff \\alpha = 45°$. Au-delà ou en deçà, la portée diminue."}],"final_answer_fr":"$x_p \\approx 55{,}2$ m"}},{"number":2,"stem_fr":"Hauteur maximale.","points":2,"solution":{"steps":[{"text_fr":"Au sommet : $v_y = 0 \\iff t_s = v_{0y}/g \\approx 1{,}274\\,\\text{s}$."},{"text_fr":"Hauteur : $h_\\text{max} = y(t_s) = v_{0y}^2/(2g) = 156{,}25/19{,}62 \\approx 7{,}97\\,\\text{m}$."},{"text_fr":"Ou avec la formule : $h_\\text{max} = \\dfrac{v_0^2 \\sin^2\\alpha}{2g} \\approx 7{,}97\\,\\text{m}$ ✓."}],"final_answer_fr":"$h_\\text{max} \\approx 8$ m"}}]},{"number":4,"title_fr":"Tir horizontal","points":5,"preamble_fr":"Un ballon est lancé horizontalement à 15 m/s du haut d''une tour de 80 m. $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Durée de chute.","points":1,"solution":{"steps":[{"text_fr":"Chute libre verticale ($v_{0y} = 0$) : $h = \\dfrac{1}{2} g t^2 \\iff t = \\sqrt{2 h /g} = \\sqrt{160/10} = 4\\,\\text{s}$."}],"final_answer_fr":"$t = 4$ s"}},{"number":2,"stem_fr":"Distance horizontale au sol (portée).","points":2,"solution":{"steps":[{"text_fr":"Mouvement horizontal uniforme : $x = v_0 t = 15 \\times 4 = 60\\,\\text{m}$."}],"final_answer_fr":"$x = 60$ m"}},{"number":3,"stem_fr":"Vitesse à l''impact (module et angle).","points":2,"solution":{"steps":[{"text_fr":"À l''impact : $v_x = 15\\,\\text{m/s}$ (inchangé), $v_y = g t = 40\\,\\text{m/s}$."},{"text_fr":"Module : $v = \\sqrt{v_x^2 + v_y^2} = \\sqrt{225 + 1600} = \\sqrt{1825} \\approx 42{,}7\\,\\text{m/s}$."},{"text_fr":"Angle avec l''horizontale : $\\beta = \\arctan(v_y/v_x) = \\arctan(40/15) \\approx 69{,}4°$ — quasi-vertical."}],"final_answer_fr":"$v \\approx 42{,}7$ m/s, $\\beta \\approx 69°$"}}]}]}'::jsonb WHERE code = 'pc_projectile';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Énergie mécanique","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Énergies cinétique $E_c = \\frac{1}{2} m v^2$, potentielle pesanteur $E_p = mgh$, élastique $E_{pe} = \\frac{1}{2} k x^2$. Conservation $E_m = E_c + E_p$ en absence de frottement.","exercices":[{"number":1,"title_fr":"Calculs élémentaires","points":5,"preamble_fr":"Un cycliste de 70 kg roule à 36 km/h sur route plate. $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Calculer son énergie cinétique.","points":2,"solution":{"steps":[{"text_fr":"Conversion : $v = 36/3{,}6 = 10\\,\\text{m/s}$."},{"text_fr":"$E_c = \\dfrac{1}{2} m v^2 = 0{,}5 \\times 70 \\times 100 = 3500\\,\\text{J} = 3{,}5\\,\\text{kJ}$."}],"final_answer_fr":"$E_c = 3{,}5$ kJ"}},{"number":2,"stem_fr":"Énergie potentielle gagnée en montant une côte de 50 m.","points":1,"solution":{"steps":[{"text_fr":"$\\Delta E_p = m g \\Delta h = 70 \\times 10 \\times 50 = 35\\,000\\,\\text{J} = 35\\,\\text{kJ}$."}],"final_answer_fr":"$\\Delta E_p = 35$ kJ"}},{"number":3,"stem_fr":"Hauteur atteinte si toute l''énergie cinétique est convertie en énergie potentielle.","points":2,"solution":{"steps":[{"text_fr":"Conservation : $E_c \\to E_p \\iff mgh = 3500 \\Rightarrow h = \\dfrac{3500}{700} = 5\\,\\text{m}$."},{"text_fr":"Pour gravir 50 m, il faut donc fournir $35 - 3{,}5 = 31{,}5\\,\\text{kJ}$ supplémentaires (en pédalant)."}],"final_answer_fr":"$h = 5$ m"}}]},{"number":2,"title_fr":"Conservation sur toboggan","points":5,"preamble_fr":"Un enfant de 25 kg glisse depuis le haut d''un toboggan de hauteur 4 m, partant du repos. $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"En absence de frottement, vitesse en bas.","points":3,"solution":{"steps":[{"text_fr":"Conservation de l''énergie mécanique : $E_m^\\text{haut} = E_m^\\text{bas}$, soit $mgh = \\dfrac{1}{2} m v^2$."},{"text_fr":"Simplification : $v = \\sqrt{2 g h} = \\sqrt{2 \\times 10 \\times 4} = \\sqrt{80} \\approx 8{,}94\\,\\text{m/s} \\approx 32\\,\\text{km/h}$."},{"text_fr":"**Résultat indépendant de la masse** — un adulte et un enfant arrivent à la même vitesse. La masse se simplifie dans l''équation.","tip_fr":"C''est le même principe que la chute libre — toutes les masses tombent à la même vitesse en absence d''air (Galilée à Pise)."}],"final_answer_fr":"$v \\approx 8{,}94$ m/s"}},{"number":2,"stem_fr":"Si avec frottement l''enfant arrive à 7 m/s, énergie dissipée.","points":2,"solution":{"steps":[{"text_fr":"Énergie initiale : $E_m^\\text{haut} = mgh = 25 \\times 10 \\times 4 = 1000\\,\\text{J}$."},{"text_fr":"Énergie cinétique finale : $E_c^\\text{bas} = 0{,}5 \\times 25 \\times 49 = 612{,}5\\,\\text{J}$."},{"text_fr":"Énergie dissipée par frottement : $\\Delta E = 1000 - 612{,}5 = 387{,}5\\,\\text{J}$ — soit 38,7% de l''énergie initiale convertie en chaleur."}],"final_answer_fr":"$\\Delta E = 387{,}5$ J"}}]},{"number":3,"title_fr":"Ressort — énergie élastique","points":5,"preamble_fr":"Un ressort de raideur $k = 500\\,\\text{N/m}$ est comprimé de $x = 10\\,\\text{cm}$, puis libéré pour propulser une bille de masse $m = 0{,}2\\,\\text{kg}$ horizontalement.","questions":[{"number":1,"stem_fr":"Énergie potentielle élastique stockée.","points":2,"solution":{"steps":[{"text_fr":"$E_{pe} = \\dfrac{1}{2} k x^2 = 0{,}5 \\times 500 \\times (0{,}1)^2 = 2{,}5\\,\\text{J}$."}],"final_answer_fr":"$E_{pe} = 2{,}5$ J"}},{"number":2,"stem_fr":"Vitesse maximale de la bille.","points":3,"solution":{"steps":[{"text_fr":"Conservation (sans frottement) : $\\dfrac{1}{2} k x^2 = \\dfrac{1}{2} m v^2 \\Rightarrow v = x \\sqrt{\\dfrac{k}{m}}$."},{"text_fr":"$v = 0{,}1 \\times \\sqrt{500/0{,}2} = 0{,}1 \\times \\sqrt{2500} = 0{,}1 \\times 50 = 5\\,\\text{m/s}$."},{"text_fr":"**Lien avec la pulsation propre** : $\\omega_0 = \\sqrt{k/m}$. Donc $v_\\text{max} = x \\omega_0$ (vitesse maximale d''un oscillateur harmonique d''amplitude $x$).","tip_fr":"$\\omega_0 = \\sqrt{k/m}$ apparaît partout en oscillations : ressort, pendule, RLC. La formule structurale est universelle."}],"final_answer_fr":"$v = 5$ m/s"}}]},{"number":4,"title_fr":"Théorème de l''énergie cinétique avec frottement","points":5,"preamble_fr":"Une caisse de 30 kg est tirée sur un sol horizontal par une force $F = 100\\,\\text{N}$ pendant $d = 5\\,\\text{m}$. Coefficient de frottement $\\mu = 0{,}2$, $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Travaux de $F$ et du frottement.","points":3,"solution":{"steps":[{"text_fr":"**Travail de $F$** (parallèle au mouvement) : $W_F = F \\cdot d = 100 \\times 5 = 500\\,\\text{J}$."},{"text_fr":"**Frottement** : réaction normale $R = mg = 300\\,\\text{N}$ ; force de frottement $f = \\mu R = 60\\,\\text{N}$, opposée au mouvement."},{"text_fr":"Travail du frottement : $W_f = -f \\cdot d = -300\\,\\text{J}$ (négatif, force opposée)."},{"text_fr":"Travaux du poids et de la réaction normale : nuls (perpendiculaires au déplacement horizontal)."}],"final_answer_fr":"$W_F = 500$ J, $W_f = -300$ J"}},{"number":2,"stem_fr":"Vitesse finale, partant du repos.","points":2,"solution":{"steps":[{"text_fr":"**Théorème de l''énergie cinétique** : $\\Delta E_c = \\sum W_\\text{ext} = 500 - 300 = 200\\,\\text{J}$."},{"text_fr":"$\\dfrac{1}{2} m v^2 = 200 \\Rightarrow v = \\sqrt{400/30} \\approx 3{,}65\\,\\text{m/s}$."}],"final_answer_fr":"$v \\approx 3{,}65$ m/s"}}]}]}'::jsonb WHERE code = 'pc_energy_mechanical';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Pendule pesant et pendule élastique","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Pendule simple : période $T = 2\\pi\\sqrt{L/g}$. Pendule élastique : $T = 2\\pi\\sqrt{m/k}$. Équation différentielle $\\theta'''' + \\omega_0^2 \\theta = 0$ pour petites oscillations.","exercices":[{"number":1,"title_fr":"Pendule simple","points":5,"preamble_fr":"Un pendule simple est constitué d''une masse $m = 200\\,\\text{g}$ suspendue à un fil inextensible de longueur $L = 1\\,\\text{m}$. On l''écarte d''un petit angle $\\theta_0$ puis on lâche. $g = 9{,}81\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Établir l''équation différentielle du mouvement pour de petites oscillations.","points":3,"solution":{"steps":[{"text_fr":"Forces : poids $\\vec P$ et tension $\\vec T$ du fil. Projection sur la tangente à la trajectoire (axe $\\theta$) : seule la composante tangentielle du poids agit, soit $-mg \\sin\\theta$ (rappel vers la verticale)."},{"text_fr":"**2ème loi de Newton sur l''axe tangentiel** : $m L \\theta'''' = -mg \\sin\\theta$ (accélération tangentielle $= L\\theta''''$ pour un cercle)."},{"text_fr":"**Approximation des petites oscillations** : $\\sin\\theta \\approx \\theta$ (rad). L''équation devient : $\\theta'''' + \\dfrac{g}{L} \\theta = 0$.","tip_fr":"L''approximation $\\sin\\theta \\approx \\theta$ est valable pour $|\\theta| < 0{,}2\\,\\text{rad} \\approx 12°$ avec erreur < 1%. Au-delà, le pendule devient anharmonique."}],"final_answer_fr":"$\\theta'''' + (g/L) \\theta = 0$"}},{"number":2,"stem_fr":"Identifier la pulsation propre $\\omega_0$ et la période $T_0$.","points":2,"solution":{"steps":[{"text_fr":"Forme canonique $\\theta'''' + \\omega_0^2 \\theta = 0$ avec $\\omega_0^2 = g/L$."},{"text_fr":"$\\omega_0 = \\sqrt{g/L} = \\sqrt{9{,}81/1} \\approx 3{,}13\\,\\text{rad/s}$."},{"text_fr":"Période : $T_0 = \\dfrac{2\\pi}{\\omega_0} = 2\\pi\\sqrt{\\dfrac{L}{g}} = 2\\pi\\sqrt{1/9{,}81} \\approx 2{,}01\\,\\text{s}$.","tip_fr":"**Isochronisme** : la période est indépendante de l''amplitude (en petites oscillations) ET indépendante de la masse. C''est l''observation de Galilée."}],"final_answer_fr":"$\\omega_0 \\approx 3{,}13$ rad/s, $T_0 \\approx 2$ s"}}]},{"number":2,"title_fr":"Pendule élastique","points":5,"preamble_fr":"Une masse $m = 0{,}5\\,\\text{kg}$ est accrochée à un ressort horizontal de raideur $k = 50\\,\\text{N/m}$, sur un support sans frottement. On l''écarte de $x_0 = 5\\,\\text{cm}$ puis on lâche.","questions":[{"number":1,"stem_fr":"Établir l''équation différentielle.","points":2,"solution":{"steps":[{"text_fr":"Seule force horizontale (autre que la normale verticale) : force de rappel du ressort $F = -k x$ (loi de Hooke)."},{"text_fr":"2ème loi : $m x'''' = -k x \\Rightarrow x'''' + \\dfrac{k}{m} x = 0$."}],"final_answer_fr":"$x'''' + (k/m) x = 0$"}},{"number":2,"stem_fr":"Pulsation, période, fréquence.","points":2,"solution":{"steps":[{"text_fr":"$\\omega_0 = \\sqrt{k/m} = \\sqrt{50/0{,}5} = \\sqrt{100} = 10\\,\\text{rad/s}$."},{"text_fr":"Période : $T_0 = 2\\pi/\\omega_0 = 2\\pi/10 \\approx 0{,}628\\,\\text{s}$. Fréquence : $f = 1/T \\approx 1{,}59\\,\\text{Hz}$."}],"final_answer_fr":"$\\omega_0 = 10$ rad/s, $T \\approx 0{,}63$ s"}},{"number":3,"stem_fr":"Solution générale $x(t)$ avec conditions initiales $x(0) = x_0$ et $x''(0) = 0$.","points":1,"solution":{"steps":[{"text_fr":"Solution générale : $x(t) = A \\cos(\\omega_0 t) + B \\sin(\\omega_0 t)$."},{"text_fr":"CI : $x(0) = A = x_0 = 0{,}05\\,\\text{m}$. $x''(0) = B \\omega_0 = 0 \\Rightarrow B = 0$."},{"text_fr":"Donc $x(t) = 0{,}05 \\cos(10\\,t)$ (en mètres)."}],"final_answer_fr":"$x(t) = 0{,}05 \\cos(10 t)$"}}]},{"number":3,"title_fr":"Énergie d''un oscillateur","points":5,"preamble_fr":"Reprenons le pendule élastique de l''exercice 2.","questions":[{"number":1,"stem_fr":"Calculer l''énergie mécanique $E_m$ totale (constante).","points":2,"solution":{"steps":[{"text_fr":"À $t = 0$ : vitesse nulle, position $x_0 = 0{,}05\\,\\text{m}$. Toute l''énergie est potentielle élastique."},{"text_fr":"$E_m = E_{pe} = \\dfrac{1}{2} k x_0^2 = 0{,}5 \\times 50 \\times (0{,}05)^2 = 0{,}0625\\,\\text{J} = 62{,}5\\,\\text{mJ}$."}],"final_answer_fr":"$E_m = 62{,}5$ mJ"}},{"number":2,"stem_fr":"Vitesse maximale (au passage par la position d''équilibre).","points":2,"solution":{"steps":[{"text_fr":"À $x = 0$ : énergie potentielle nulle, donc $E_m = E_c = \\dfrac{1}{2} m v_\\text{max}^2$."},{"text_fr":"$v_\\text{max} = \\sqrt{2 E_m / m} = \\sqrt{0{,}125/0{,}5} = \\sqrt{0{,}25} = 0{,}5\\,\\text{m/s}$."},{"text_fr":"Vérification : $v_\\text{max} = x_0 \\omega_0 = 0{,}05 \\times 10 = 0{,}5\\,\\text{m/s}$ ✓.","tip_fr":"Pour un oscillateur harmonique : $v_\\text{max} = x_\\text{max} \\cdot \\omega_0$. Identité utile pour relier amplitudes et vitesses."}],"final_answer_fr":"$v_\\text{max} = 0{,}5$ m/s"}},{"number":3,"stem_fr":"Vérifier que $E_c + E_{pe}$ est constante en tout point.","points":1,"solution":{"steps":[{"text_fr":"À position quelconque $x$, vitesse $v$ : $E_c + E_{pe} = \\frac{1}{2} m v^2 + \\frac{1}{2} k x^2$. Conservation : valeur = $E_m = \\frac{1}{2} k x_0^2$ (initiale)."},{"text_fr":"Échange continu : à $x = 0$, tout est cinétique ; aux extrémités, tout est potentiel. Caractéristique des oscillations harmoniques sans frottement."}]}}]},{"number":4,"title_fr":"Pendule pesant — petites oscillations","points":5,"preamble_fr":"Un pendule pesant est un solide pouvant tourner autour d''un axe fixe horizontal, ne passant pas par son centre de gravité. La période s''écrit $T = 2\\pi \\sqrt{J_\\Delta/(mgd)}$ avec $J_\\Delta$ moment d''inertie, $d$ distance axe-centre de gravité.","questions":[{"number":1,"stem_fr":"Application : tige homogène de masse 1 kg et longueur 60 cm, suspendue à un bout. $J = \\frac{1}{3} m L^2$, $d = L/2$. Calculer T.","points":4,"solution":{"steps":[{"text_fr":"Données : $m = 1\\,\\text{kg}$, $L = 0{,}6\\,\\text{m}$, $d = L/2 = 0{,}3\\,\\text{m}$."},{"text_fr":"$J = \\dfrac{1}{3} m L^2 = \\dfrac{1}{3} \\times 1 \\times 0{,}36 = 0{,}12\\,\\text{kg}\\cdot\\text{m}^2$."},{"text_fr":"$T = 2\\pi \\sqrt{\\dfrac{J}{m g d}} = 2\\pi \\sqrt{\\dfrac{0{,}12}{1 \\times 9{,}81 \\times 0{,}3}} = 2\\pi \\sqrt{0{,}0408} \\approx 2\\pi \\times 0{,}202 \\approx 1{,}27\\,\\text{s}$."},{"text_fr":"**Comparaison avec un pendule simple** de longueur 60 cm : $T_\\text{simple} = 2\\pi\\sqrt{0{,}6/9{,}81} \\approx 1{,}55\\,\\text{s}$. Le pendule pesant oscille **plus vite** car sa masse est concentrée plus haut.","tip_fr":"**Longueur équivalente** $L_\\text{eq} = J/(m d)$ donne la longueur du pendule simple de même période. Pour la tige : $L_\\text{eq} = 0{,}12/0{,}3 = 0{,}4\\,\\text{m}$."}],"final_answer_fr":"$T \\approx 1{,}27$ s"}},{"number":2,"stem_fr":"Fréquence et nombre d''oscillations en 1 minute.","points":1,"solution":{"steps":[{"text_fr":"$f = 1/T \\approx 0{,}787\\,\\text{Hz}$. Nombre d''oscillations en 60 s : $N = 60/T \\approx 47\\,\\text{oscillations}$."}],"final_answer_fr":"$f \\approx 0{,}79$ Hz, $N \\approx 47$"}}]}]}'::jsonb WHERE code = 'pc_pendulum';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Dipôle RC","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Charge $u_C(t) = E(1 - e^{-t/\\tau})$ et décharge $u_C(t) = U_0 e^{-t/\\tau}$ avec $\\tau = RC$. Énergie stockée $\\frac{1}{2} C u_C^2$.","exercices":[{"number":1,"title_fr":"Charge d''un condensateur","points":5,"preamble_fr":"Circuit série : générateur idéal $E = 12\\,\\text{V}$, $R = 1\\,\\text{k}\\Omega$, $C = 470\\,\\mu\\text{F}$. À $t = 0$ on ferme l''interrupteur, condensateur initialement déchargé.","questions":[{"number":1,"stem_fr":"Établir l''équation différentielle vérifiée par $u_C(t)$.","points":2,"solution":{"steps":[{"text_fr":"Loi des mailles : $E = u_R + u_C = R i + u_C$. Avec $i = C\\,du_C/dt$ : $E = RC \\dfrac{du_C}{dt} + u_C$."},{"text_fr":"Forme canonique : $\\dfrac{du_C}{dt} + \\dfrac{1}{RC} u_C = \\dfrac{E}{RC}$, ou $\\tau \\dfrac{du_C}{dt} + u_C = E$ avec $\\tau = RC$."}],"final_answer_fr":"$\\tau \\dfrac{du_C}{dt} + u_C = E$"}},{"number":2,"stem_fr":"Calculer la constante de temps $\\tau$.","points":1,"solution":{"steps":[{"text_fr":"$\\tau = RC = 10^3 \\times 470 \\times 10^{-6} = 0{,}47\\,\\text{s} = 470\\,\\text{ms}$.","tip_fr":"Vérification dimensionnelle : $[\\tau] = \\Omega \\cdot \\text{F} = \\text{V/A} \\cdot \\text{C/V} = \\text{C/A} = \\text{s}$ ✓."}],"final_answer_fr":"$\\tau = 470$ ms"}},{"number":3,"stem_fr":"Donner $u_C(t)$.","points":1,"solution":{"steps":[{"text_fr":"Solution : $u_C(t) = E(1 - e^{-t/\\tau}) = 12(1 - e^{-t/0{,}47})\\,\\text{V}$."},{"text_fr":"Limites : $u_C(0) = 0$ ✓ ; $\\lim_{+\\infty} u_C = E = 12\\,\\text{V}$ (régime permanent)."}],"final_answer_fr":"$u_C(t) = 12(1 - e^{-t/0{,}47})$"}},{"number":4,"stem_fr":"Au bout de combien de temps $u_C$ atteint-il 95% de $E$ ?","points":1,"solution":{"steps":[{"text_fr":"$1 - e^{-t/\\tau} = 0{,}95 \\iff t = \\tau \\ln 20 \\approx 3\\tau \\approx 1{,}41\\,\\text{s}$."},{"text_fr":"**Règles pratiques** : $3\\tau$ → 95% ; $5\\tau$ → 99,3% ; le régime est considéré ''établi'' au-delà de $5\\tau$."}],"final_answer_fr":"$t \\approx 3\\tau \\approx 1{,}4$ s"}}]},{"number":2,"title_fr":"Décharge","points":5,"preamble_fr":"Le condensateur est chargé à $U_0 = 12\\,\\text{V}$. On le décharge dans une résistance $R'' = 2\\,\\text{k}\\Omega$.","questions":[{"number":1,"stem_fr":"Équation différentielle et solution $u_C(t)$.","points":3,"solution":{"steps":[{"text_fr":"Maille (sans générateur) : $0 = R'' i + u_C$ avec $i = C\\,du_C/dt$. Donc $R''C \\dfrac{du_C}{dt} + u_C = 0$."},{"text_fr":"Solution : $u_C(t) = U_0 e^{-t/\\tau''}$ avec $\\tau'' = R''C$."},{"text_fr":"$\\tau'' = 2000 \\times 470 \\times 10^{-6} = 0{,}94\\,\\text{s}$. Donc $u_C(t) = 12 e^{-t/0{,}94}\\,\\text{V}$."}],"final_answer_fr":"$u_C(t) = 12 e^{-t/0{,}94}$"}},{"number":2,"stem_fr":"Énergie initialement stockée puis dissipée par effet Joule.","points":2,"solution":{"steps":[{"text_fr":"Énergie initiale : $E_C^\\text{init} = \\dfrac{1}{2} C U_0^2 = 0{,}5 \\times 470 \\times 10^{-6} \\times 144 \\approx 33{,}8\\,\\text{mJ}$."},{"text_fr":"À long terme, $u_C \\to 0$ donc $E_C \\to 0$. **Toute** l''énergie initiale est dissipée par effet Joule dans $R''$ (conservation).","tip_fr":"**Décharge** : 100% Joule. **Charge** : 50% Joule + 50% stockée dans $C$ — résultat universel, indépendant de $R$ et $C$."}],"final_answer_fr":"$E_J \\approx 33{,}8$ mJ"}}]},{"number":3,"title_fr":"Mesure de C par chronométrage","points":5,"preamble_fr":"Un condensateur inconnu est associé à $R = 10\\,\\text{k}\\Omega$. On observe que $u_C$ passe de 12 V à 6 V en 2 secondes lors d''une décharge.","questions":[{"number":1,"stem_fr":"Que représente la durée de 2 s ?","points":2,"solution":{"steps":[{"text_fr":"$u_C$ divisé par 2 → $e^{-t/\\tau} = 1/2 \\iff t = \\tau \\ln 2$."},{"text_fr":"C''est le **temps de demi-décharge** : $t_{1/2} = \\tau \\ln 2$. Analogue à la demi-vie radioactive."}],"final_answer_fr":"$t_{1/2} = \\tau \\ln 2$"}},{"number":2,"stem_fr":"Calculer $\\tau$ puis $C$.","points":3,"solution":{"steps":[{"text_fr":"$\\tau = t_{1/2}/\\ln 2 = 2/0{,}693 \\approx 2{,}885\\,\\text{s}$."},{"text_fr":"$C = \\tau/R = 2{,}885/10\\,000 \\approx 2{,}88 \\times 10^{-4}\\,\\text{F} \\approx 288\\,\\mu\\text{F}$.","tip_fr":"Méthode standard de mesure : chronométrer la chute à mi-amplitude donne directement $\\tau$ (sans formule complexe)."}],"final_answer_fr":"$C \\approx 288$ μF"}}]},{"number":4,"title_fr":"Application — flash photographique","points":5,"preamble_fr":"Un flash utilise un condensateur $C = 1000\\,\\mu\\text{F}$ chargé à $U_0 = 300\\,\\text{V}$ qui se décharge en $\\Delta t \\approx 1\\,\\text{ms}$ à travers le tube éclair.","questions":[{"number":1,"stem_fr":"Énergie disponible pour l''éclair.","points":2,"solution":{"steps":[{"text_fr":"$E = \\dfrac{1}{2} C U_0^2 = 0{,}5 \\times 10^{-3} \\times 90\\,000 = 45\\,\\text{J}$."}],"final_answer_fr":"$E = 45$ J"}},{"number":2,"stem_fr":"Puissance moyenne pendant l''éclair.","points":2,"solution":{"steps":[{"text_fr":"$P_\\text{moy} = E/\\Delta t = 45/10^{-3} = 45\\,000\\,\\text{W} = 45\\,\\text{kW}$."},{"text_fr":"**45 kW pendant 1 ms** — puissance crête énorme. C''est ce qui permet l''éclair intense pour figer le mouvement en photographie.","tip_fr":"Principe identique pour les défibrillateurs cardiaques : on stocke lentement (charges au secteur), on décharge instantanément (kJ en quelques ms)."}],"final_answer_fr":"$P \\approx 45$ kW"}},{"number":3,"stem_fr":"Résistance équivalente du tube pour avoir $\\tau = 1\\,\\text{ms}$.","points":1,"solution":{"steps":[{"text_fr":"$\\tau = R_\\text{tube} \\cdot C \\iff R_\\text{tube} = \\tau/C = 10^{-3}/10^{-3} = 1\\,\\Omega$. Très faible — c''est un plasma conducteur."}],"final_answer_fr":"$R \\approx 1$ Ω"}}]}]}'::jsonb WHERE code = 'pc_rc_circuit';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Dipôle RL","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Établissement $i(t) = I_\\text{max}(1 - e^{-t/\\tau})$ et rupture $i(t) = I_0 e^{-t/\\tau}$ avec $\\tau = L/R$. Énergie magnétique $\\frac{1}{2} L i^2$.","exercices":[{"number":1,"title_fr":"Établissement du courant","points":5,"preamble_fr":"Circuit série : $E = 6\\,\\text{V}$, $R = 30\\,\\Omega$, bobine $L = 0{,}1\\,\\text{H}$ (résistance interne négligeable). À $t = 0$ on ferme.","questions":[{"number":1,"stem_fr":"Établir l''équation différentielle pour $i(t)$.","points":2,"solution":{"steps":[{"text_fr":"Loi des mailles : $E = u_R + u_L = R i + L \\dfrac{di}{dt}$."},{"text_fr":"Forme : $L \\dfrac{di}{dt} + R i = E$, ou $\\dfrac{di}{dt} + \\dfrac{R}{L} i = \\dfrac{E}{L}$. Avec $\\tau = L/R$ : $\\tau \\dfrac{di}{dt} + i = I_\\text{max}$ avec $I_\\text{max} = E/R$."}],"final_answer_fr":"$\\tau di/dt + i = I_\\text{max}$"}},{"number":2,"stem_fr":"Calculer $\\tau$ et $I_\\text{max}$.","points":1,"solution":{"steps":[{"text_fr":"$\\tau = L/R = 0{,}1/30 \\approx 3{,}33\\,\\text{ms}$. $I_\\text{max} = E/R = 6/30 = 0{,}2\\,\\text{A} = 200\\,\\text{mA}$.","tip_fr":"Vérification dimensionnelle : $[L/R] = \\text{H}/\\Omega = (\\text{V}\\cdot\\text{s/A})/(\\text{V/A}) = \\text{s}$ ✓."}],"final_answer_fr":"$\\tau \\approx 3{,}33$ ms, $I_\\text{max} = 200$ mA"}},{"number":3,"stem_fr":"Donner $i(t)$ et $u_L(t)$.","points":2,"solution":{"steps":[{"text_fr":"Solution : $i(t) = I_\\text{max}(1 - e^{-t/\\tau}) = 0{,}2(1 - e^{-t/0{,}00333})\\,\\text{A}$."},{"text_fr":"Tension bobine : $u_L = L\\,di/dt = L \\cdot I_\\text{max}/\\tau \\cdot e^{-t/\\tau} = E e^{-t/\\tau} = 6 e^{-t/0{,}00333}\\,\\text{V}$."},{"text_fr":"À $t = 0$ : $i = 0$ et $u_L = E = 6\\,\\text{V}$ (toute la tension est absorbée par la bobine). À l''infini : $i = I_\\text{max}$, $u_L = 0$ (la bobine se comporte comme un fil).","tip_fr":"**Comportements asymptotiques** : à l''instant initial, la bobine s''oppose au courant ($u_L$ max) ; en régime permanent, elle est invisible ($u_L = 0$)."}],"final_answer_fr":"$i = 0{,}2(1 - e^{-t/\\tau})$, $u_L = 6 e^{-t/\\tau}$"}}]},{"number":2,"title_fr":"Rupture du courant","points":5,"preamble_fr":"Après le régime établi, on bascule un interrupteur qui isole $E$ et ferme le circuit $(L, R)$.","questions":[{"number":1,"stem_fr":"Donner l''équation différentielle et la solution $i(t)$.","points":3,"solution":{"steps":[{"text_fr":"Maille (sans générateur) : $0 = R i + L\\,di/dt \\iff \\dfrac{di}{dt} + \\dfrac{R}{L} i = 0$."},{"text_fr":"Solution : $i(t) = I_0 e^{-t/\\tau}$ avec $I_0 = I_\\text{max} = 0{,}2\\,\\text{A}$ (continuité du courant dans la bobine)."},{"text_fr":"$i(t) = 0{,}2 e^{-t/0{,}00333}\\,\\text{A}$."}],"final_answer_fr":"$i(t) = 0{,}2 e^{-t/\\tau}$"}},{"number":2,"stem_fr":"Énergie stockée puis dissipée.","points":2,"solution":{"steps":[{"text_fr":"Énergie stockée à $t = 0$ (instant de bascule) : $E_L = \\dfrac{1}{2} L I_0^2 = 0{,}5 \\times 0{,}1 \\times 0{,}04 = 2 \\times 10^{-3}\\,\\text{J} = 2\\,\\text{mJ}$."},{"text_fr":"À long terme, $i \\to 0$, $E_L \\to 0$. Conservation : 2 mJ dissipés par effet Joule dans R."}],"final_answer_fr":"$E_J = 2$ mJ"}}]},{"number":3,"title_fr":"Symétrie RC vs RL","points":5,"preamble_fr":"Comparer les comportements transitoires des circuits RC et RL.","questions":[{"number":1,"stem_fr":"Compléter le tableau d''analogies.","points":4,"solution":{"steps":[{"text_fr":"| Grandeur | Circuit RC | Circuit RL |"},{"text_fr":"| Quantité qui ne saute pas | $u_C$ (charge) | $i$ (flux magnétique) |"},{"text_fr":"| Constante de temps | $\\tau = RC$ | $\\tau = L/R$ |"},{"text_fr":"| Énergie stockée | $\\frac{1}{2} C u_C^2$ (électrique) | $\\frac{1}{2} L i^2$ (magnétique) |"},{"text_fr":"| À t=0 en régime initial | $u_C$ continu | $i$ continu |"},{"text_fr":"| À l''infini en charge | $u_C \\to E$, $i \\to 0$ | $i \\to E/R$, $u_L \\to 0$ |","tip_fr":"Les deux circuits sont **mathématiquement équivalents** : équations différentielles linéaires du 1er ordre avec même structure. Seules les variables physiques diffèrent."}]}}]},{"number":4,"title_fr":"Application — protection contre les surtensions","points":5,"preamble_fr":"À la rupture d''un circuit RL, si on coupe brutalement (ouverture d''interrupteur), $di/dt$ devient très grand → $u_L = L\\,di/dt$ peut produire une étincelle.","questions":[{"number":1,"stem_fr":"Pourquoi cette surtension apparaît-elle ?","points":3,"solution":{"steps":[{"text_fr":"La bobine veut maintenir son courant ($i$ ne peut pas sauter). Si on ouvre brutalement le circuit, $i$ chute en $\\Delta t$ très petit, donc $di/dt = -i_0/\\Delta t$ très grand en valeur absolue."},{"text_fr":"$u_L = L\\,di/dt$ devient énorme — peut atteindre des centaines de volts pour ionisation de l''air → étincelle (arc électrique)."},{"text_fr":"**Conséquences** : usure des contacts, parasites électromagnétiques, danger pour les semiconducteurs avoisinants."}]}},{"number":2,"stem_fr":"Solution pratique : diode de roue libre.","points":2,"solution":{"steps":[{"text_fr":"On place une **diode** en parallèle avec la bobine, polarisée en inverse (bloquante) en fonctionnement normal."},{"text_fr":"À l''ouverture, le courant $i$ continue à circuler à travers la diode (qui devient passante grâce à la tension induite). L''énergie est dissipée progressivement, sans pic de tension.","tip_fr":"Diode de roue libre : présente sur tout relais, moteur DC, alimentation à découpage — composant invisible mais critique."}]}}]}]}'::jsonb WHERE code = 'pc_rl_circuit';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Oscillations RLC libres","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Régime libre du RLC série : trois régimes selon $R$ vs $R_c = 2\\sqrt{L/C}$ (pseudo-périodique, critique, apériodique). Pulsation propre $\\omega_0 = 1/\\sqrt{LC}$.","exercices":[{"number":1,"title_fr":"Circuit LC idéal","points":5,"preamble_fr":"Un circuit LC sans résistance : $L = 1\\,\\text{H}$, $C = 4\\,\\mu\\text{F}$. Condensateur initialement chargé à $U_0 = 10\\,\\text{V}$, $i(0) = 0$.","questions":[{"number":1,"stem_fr":"Établir l''équation différentielle vérifiée par $u_C(t)$.","points":2,"solution":{"steps":[{"text_fr":"Maille : $u_C + u_L = 0 \\iff u_C + L\\,di/dt = 0$. Avec $i = -C\\,du_C/dt$ (orientation), $di/dt = -C\\,d^2 u_C/dt^2$."},{"text_fr":"Donc $u_C - LC\\,\\dfrac{d^2 u_C}{dt^2} = 0 \\iff \\dfrac{d^2 u_C}{dt^2} + \\dfrac{1}{LC} u_C = 0$."},{"text_fr":"Forme canonique de l''oscillateur harmonique : $u_C'''' + \\omega_0^2 u_C = 0$ avec $\\omega_0 = 1/\\sqrt{LC}$."}],"final_answer_fr":"$u_C'''' + \\omega_0^2 u_C = 0$"}},{"number":2,"stem_fr":"Calculer $\\omega_0$, période $T_0$ et fréquence $f_0$.","points":2,"solution":{"steps":[{"text_fr":"$\\omega_0 = 1/\\sqrt{LC} = 1/\\sqrt{4 \\times 10^{-6}} = 1/(2 \\times 10^{-3}) = 500\\,\\text{rad/s}$."},{"text_fr":"$T_0 = 2\\pi/\\omega_0 \\approx 12{,}57\\,\\text{ms}$. $f_0 = 1/T_0 \\approx 79{,}6\\,\\text{Hz}$."}],"final_answer_fr":"$\\omega_0 = 500$ rad/s, $T_0 \\approx 12{,}6$ ms"}},{"number":3,"stem_fr":"Solution $u_C(t)$ et courant $i(t)$.","points":1,"solution":{"steps":[{"text_fr":"Solution générale : $u_C(t) = A\\cos(\\omega_0 t) + B\\sin(\\omega_0 t)$. CI : $u_C(0) = U_0 = A$ ; $i(0) = -C\\,u_C''(0) = -C B\\omega_0 = 0 \\Rightarrow B = 0$."},{"text_fr":"Donc $u_C(t) = U_0\\cos(\\omega_0 t) = 10\\cos(500\\,t)\\,\\text{V}$. Courant : $i(t) = -C u_C'' = C U_0 \\omega_0 \\sin(\\omega_0 t) = 0{,}02\\sin(500 t)\\,\\text{A}$."}],"final_answer_fr":"$u_C = 10\\cos(500t)$, $i = 0{,}02\\sin(500t)$"}}]},{"number":2,"title_fr":"Conservation de l''énergie","points":5,"preamble_fr":"On reprend le circuit LC précédent.","questions":[{"number":1,"stem_fr":"Énergie totale stockée.","points":2,"solution":{"steps":[{"text_fr":"À $t = 0$ : $i = 0$ donc $E_L = 0$ ; tout est dans le condensateur : $E_C = \\dfrac{1}{2} C U_0^2 = 0{,}5 \\times 4 \\times 10^{-6} \\times 100 = 2 \\times 10^{-4}\\,\\text{J} = 0{,}2\\,\\text{mJ}$."},{"text_fr":"Par conservation (pas de R) : $E_\\text{tot} = E_C + E_L = 0{,}2\\,\\text{mJ}$ à tout instant."}],"final_answer_fr":"$E_\\text{tot} = 0{,}2$ mJ"}},{"number":2,"stem_fr":"Quand $u_C = 0$, quel est le courant ? Vérifier la conservation.","points":3,"solution":{"steps":[{"text_fr":"À cet instant : $E_C = 0$, donc $E_L = E_\\text{tot} = 0{,}2\\,\\text{mJ}$."},{"text_fr":"$\\dfrac{1}{2} L i^2 = 2 \\times 10^{-4} \\iff |i| = \\sqrt{4 \\times 10^{-4}/1} = 0{,}02\\,\\text{A} = 20\\,\\text{mA}$."},{"text_fr":"Cohérent avec l''amplitude $I_\\text{max} = 0{,}02\\,\\text{A}$ trouvée précédemment. **L''énergie oscille entre $C$ (électrique) et $L$ (magnétique)** sans perte.","tip_fr":"Analogue mécanique : oscillateur ressort-masse — l''énergie oscille entre cinétique et potentielle élastique, sans amortissement."}],"final_answer_fr":"$|i| = I_\\text{max} = 20$ mA"}}]},{"number":3,"title_fr":"RLC réel — trois régimes","points":5,"preamble_fr":"On ajoute une résistance $R$ en série dans le circuit.","questions":[{"number":1,"stem_fr":"Donner le critère de régime selon $R$.","points":3,"solution":{"steps":[{"text_fr":"Équation : $L\\,d^2 q/dt^2 + R\\,dq/dt + q/C = 0$. Équation caractéristique : $L r^2 + R r + 1/C = 0$."},{"text_fr":"Discriminant : $\\Delta = R^2 - 4L/C$. **Trois cas** :"},{"text_fr":"**$\\Delta < 0$** ($R < R_c = 2\\sqrt{L/C}$) : régime **pseudo-périodique** (oscillations amorties exponentiellement)."},{"text_fr":"**$\\Delta = 0$** ($R = R_c$) : régime **critique** (retour le plus rapide sans oscillation)."},{"text_fr":"**$\\Delta > 0$** ($R > R_c$) : régime **apériodique** (retour lent sans oscillation, somme de deux exponentielles)."}],"final_answer_fr":"Critère: $R$ vs $R_c = 2\\sqrt{L/C}$"}},{"number":2,"stem_fr":"Calculer $R_c$ pour $L = 1\\,\\text{H}$, $C = 4\\,\\mu\\text{F}$.","points":2,"solution":{"steps":[{"text_fr":"$R_c = 2\\sqrt{L/C} = 2\\sqrt{1/(4 \\times 10^{-6})} = 2 \\times 500 = 1000\\,\\Omega = 1\\,\\text{k}\\Omega$."},{"text_fr":"Pour $R < 1\\,\\text{k}\\Omega$ : oscillations amorties. Pour $R > 1\\,\\text{k}\\Omega$ : retour exponentiel sans oscillation.","tip_fr":"$R_c$ est la résistance critique. **Au seuil**, le système revient à l''équilibre le plus rapidement possible — utilisé en suspension automobile (amortisseurs réglés au critique)."}],"final_answer_fr":"$R_c = 1$ kΩ"}}]},{"number":4,"title_fr":"Décrément logarithmique","points":5,"preamble_fr":"En régime pseudo-périodique faiblement amorti, l''amplitude décroît selon $A(t) = A_0 e^{-t/\\tau_a}$ avec $\\tau_a = 2L/R$.","questions":[{"number":1,"stem_fr":"Si l''amplitude passe de 5 V à 1 V en 4 pseudo-périodes, calculer $\\tau_a$ (avec $T \\approx T_0 \\approx 12{,}57\\,\\text{ms}$).","points":3,"solution":{"steps":[{"text_fr":"Durée totale : $\\Delta t = 4 T \\approx 4 \\times 12{,}57 = 50{,}28\\,\\text{ms}$."},{"text_fr":"Rapport : $A_1/A_0 = e^{-\\Delta t/\\tau_a} = 1/5 \\iff \\tau_a = \\Delta t / \\ln 5 = 0{,}05028/1{,}609 \\approx 31{,}2\\,\\text{ms}$."}],"final_answer_fr":"$\\tau_a \\approx 31{,}2$ ms"}},{"number":2,"stem_fr":"En déduire la résistance $R$ correspondante.","points":1,"solution":{"steps":[{"text_fr":"$\\tau_a = 2L/R \\iff R = 2L/\\tau_a = 2/0{,}0312 \\approx 64\\,\\Omega$."},{"text_fr":"$R \\ll R_c = 1\\,\\text{k}\\Omega$, cohérent avec un amortissement faible (oscillations bien visibles avant disparition)."}],"final_answer_fr":"$R \\approx 64$ Ω"}},{"number":3,"stem_fr":"Décrément logarithmique $\\delta = T/\\tau_a$ et nombre d''oscillations significatives.","points":1,"solution":{"steps":[{"text_fr":"$\\delta = T/\\tau_a \\approx 12{,}57/31{,}2 \\approx 0{,}403$. Quantifie la dissipation par cycle."},{"text_fr":"Nombre d''oscillations ''visibles'' ($A > A_0/e^3 \\approx 5\\%$ initial) : $3\\tau_a/T \\approx 3 \\times 31{,}2/12{,}57 \\approx 7\\,\\text{oscillations}$ avant amortissement complet.","tip_fr":"Décrément logarithmique : utilisé en mesure de viscosité (oscillation amortie d''un pendule torsionel), caractérisation de matériaux."}],"final_answer_fr":"$\\delta \\approx 0{,}40$, ~7 oscillations"}}]}]}'::jsonb WHERE code = 'pc_rlc_oscillations';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Ondes mécaniques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Onde mécanique = propagation d''une perturbation dans un milieu, sans transport de matière. Célérité $v$, longueur d''onde $\\lambda = v T = v/f$. Transversale vs longitudinale.","exercices":[{"number":1,"title_fr":"Vocabulaire et relations fondamentales","points":5,"preamble_fr":"Une onde se propage le long d''une corde tendue avec célérité $v = 30\\,\\text{m/s}$, fréquence $f = 60\\,\\text{Hz}$.","questions":[{"number":1,"stem_fr":"Calculer la période $T$ et la longueur d''onde $\\lambda$.","points":2,"solution":{"steps":[{"text_fr":"**Période** : $T = 1/f = 1/60 \\approx 16{,}7\\,\\text{ms}$."},{"text_fr":"**Longueur d''onde** : $\\lambda = v T = v/f = 30/60 = 0{,}5\\,\\text{m}$."}],"final_answer_fr":"$T \\approx 16{,}7$ ms, $\\lambda = 0{,}5$ m"}},{"number":2,"stem_fr":"Que représente $\\lambda$ géométriquement sur la corde ?","points":1,"solution":{"steps":[{"text_fr":"Distance entre **deux maxima consécutifs** (ou deux points dans le même état de vibration) à un instant donné, soit $\\lambda = 0{,}5\\,\\text{m}$."}]}},{"number":3,"stem_fr":"Si on double la fréquence ($v$ inchangée), comment varie $\\lambda$ ?","points":2,"solution":{"steps":[{"text_fr":"$\\lambda = v/f$ → si $f$ est doublée, $\\lambda$ est **divisée par 2** : $\\lambda'' = 0{,}25\\,\\text{m}$."},{"text_fr":"Relation fondamentale : $\\lambda \\propto 1/f$ à célérité constante. Vraie pour toute onde dans un milieu donné.","tip_fr":"La célérité dépend du milieu (tension de la corde, densité). La fréquence est imposée par la source. $\\lambda$ s''ajuste pour satisfaire $\\lambda = v/f$."}],"final_answer_fr":"$\\lambda$ divisée par 2"}}]},{"number":2,"title_fr":"Types d''ondes","points":5,"preamble_fr":"Comparer ondes transversales et longitudinales.","questions":[{"number":1,"stem_fr":"Le son est-il transversal ou longitudinal ? Justifier.","points":2,"solution":{"steps":[{"text_fr":"**Longitudinal** : dans l''air, les molécules oscillent **parallèlement à la direction de propagation**, créant des compressions/raréfactions."},{"text_fr":"**Contre-exemple** : une corde vibre **transversalement** — chaque point se déplace perpendiculairement à la corde."}],"final_answer_fr":"Longitudinale"}},{"number":2,"stem_fr":"Le son se propage-t-il dans le vide ?","points":1,"solution":{"steps":[{"text_fr":"**Non** — les ondes mécaniques nécessitent un milieu matériel. Sans matière à comprimer, pas de propagation."},{"text_fr":"Contraste : la **lumière** (onde électromagnétique) se propage dans le vide → on voit le soleil sans entendre les explosions solaires."}]}},{"number":3,"stem_fr":"Célérité du son dans différents milieux.","points":2,"solution":{"steps":[{"text_fr":"Air (20°C) : $v \\approx 340\\,\\text{m/s}$. Eau : $v \\approx 1500\\,\\text{m/s}$. Acier : $v \\approx 5000\\,\\text{m/s}$."},{"text_fr":"**Règle** : célérité ↑ avec rigidité du milieu. Solide > liquide > gaz. $v_\\text{son} \\propto \\sqrt{K/\\rho}$ ($K$ = module de compression, $\\rho$ = densité).","tip_fr":"Application : les baleines communiquent à grande distance dans l''eau grâce à la célérité élevée (1500 m/s contre 340 dans l''air)."}]}}]},{"number":3,"title_fr":"Retard et déphasage","points":5,"preamble_fr":"Une source S émet une onde de fréquence $f = 200\\,\\text{Hz}$ dans l''air (célérité 340 m/s). Un récepteur M est à distance $d = 5{,}1\\,\\text{m}$.","questions":[{"number":1,"stem_fr":"Retard $\\tau$ entre S et M.","points":1,"solution":{"steps":[{"text_fr":"$\\tau = d/v = 5{,}1/340 = 0{,}015\\,\\text{s} = 15\\,\\text{ms}$."}],"final_answer_fr":"$\\tau = 15$ ms"}},{"number":2,"stem_fr":"Déphasage $\\Delta\\varphi$ entre S et M en radians, modulo $2\\pi$.","points":3,"solution":{"steps":[{"text_fr":"$\\Delta\\varphi = 2\\pi f \\tau = 2\\pi \\times 200 \\times 0{,}015 = 6\\pi\\,\\text{rad}$."},{"text_fr":"Modulo $2\\pi$ : $6\\pi = 3 \\times 2\\pi \\equiv 0$. Les deux points sont **en phase**."},{"text_fr":"**Vérification** : $\\lambda = v/f = 340/200 = 1{,}7\\,\\text{m}$. $d/\\lambda = 5{,}1/1{,}7 = 3$ (entier) → en phase ✓.","tip_fr":"**Critère synthétique** : en phase si $d$ est un multiple entier de $\\lambda$, en opposition de phase si multiple impair de $\\lambda/2$."}],"final_answer_fr":"En phase ($\\Delta\\varphi \\equiv 0$)"}}]},{"number":4,"title_fr":"Onde stationnaire sur corde fixée","points":5,"preamble_fr":"Une corde de longueur $L = 1\\,\\text{m}$ est fixée à ses deux extrémités. On l''excite dans son mode fondamental.","questions":[{"number":1,"stem_fr":"Longueur d''onde du mode fondamental.","points":2,"solution":{"steps":[{"text_fr":"Mode fondamental = un seul ventre au milieu, nœuds aux extrémités fixes."},{"text_fr":"Donc $L = \\lambda/2 \\iff \\lambda = 2 L = 2\\,\\text{m}$."}],"final_answer_fr":"$\\lambda_1 = 2$ m"}},{"number":2,"stem_fr":"Si $f_1 = 220\\,\\text{Hz}$, célérité sur la corde ?","points":1,"solution":{"steps":[{"text_fr":"$v = \\lambda_1 f_1 = 2 \\times 220 = 440\\,\\text{m/s}$."}],"final_answer_fr":"$v = 440$ m/s"}},{"number":3,"stem_fr":"Fréquence et longueur d''onde du 3ème harmonique ($f_3 = 3 f_1$).","points":2,"solution":{"steps":[{"text_fr":"$f_3 = 3 \\times 220 = 660\\,\\text{Hz}$. $\\lambda_3 = v/f_3 = 440/660 = 2/3\\,\\text{m}$."},{"text_fr":"Géométriquement : 3 ventres sur la corde, $L = 3 \\lambda_3 / 2$ ✓.","tip_fr":"Sur une corde fixée aux 2 bouts : $f_n = n \\cdot f_1$ (harmoniques entiers). Cette série produit la sonorité ''musicale'' des instruments à cordes."}],"final_answer_fr":"$f_3 = 660$ Hz, $\\lambda_3 = 2/3$ m"}}]}]}'::jsonb WHERE code = 'pc_mechanical_waves';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Diffraction et interférences","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Diffraction par une fente : $\\theta \\approx \\lambda/a$. Interférences de Young (deux fentes) : interfrange $i = \\lambda D/a$. Conditions : ondes cohérentes, monochromatiques.","exercices":[{"number":1,"title_fr":"Diffraction par une fente","points":5,"preamble_fr":"Un laser de longueur d''onde $\\lambda = 632\\,\\text{nm}$ (rouge) traverse une fente de largeur $a = 0{,}1\\,\\text{mm}$. L''écran est à $D = 2\\,\\text{m}$.","questions":[{"number":1,"stem_fr":"Calculer l''angle $\\theta$ du 1er minimum de diffraction.","points":2,"solution":{"steps":[{"text_fr":"**Formule** : 1er minimum à $\\sin\\theta = \\lambda/a$ (pour petits angles : $\\theta \\approx \\lambda/a$ en rad)."},{"text_fr":"$\\theta \\approx 6{,}32 \\times 10^{-7} / 10^{-4} = 6{,}32 \\times 10^{-3}\\,\\text{rad} \\approx 0{,}36°$."}],"final_answer_fr":"$\\theta \\approx 6{,}32 \\times 10^{-3}$ rad"}},{"number":2,"stem_fr":"Demi-largeur $\\ell$ et largeur totale $L$ de la tache centrale sur l''écran.","points":2,"solution":{"steps":[{"text_fr":"$\\ell = D \\tan\\theta \\approx D \\theta = 2 \\times 6{,}32 \\times 10^{-3} \\approx 1{,}26 \\times 10^{-2}\\,\\text{m} = 12{,}6\\,\\text{mm}$."},{"text_fr":"Largeur totale : $L = 2\\ell \\approx 25\\,\\text{mm} = 2{,}5\\,\\text{cm}$. Bien plus large que la fente initiale (0,1 mm) !"}],"final_answer_fr":"$L \\approx 2{,}5$ cm"}},{"number":3,"stem_fr":"Si on réduit la fente à $a'' = 0{,}05\\,\\text{mm}$, comment varie la tache ?","points":1,"solution":{"steps":[{"text_fr":"$\\theta \\propto 1/a$. Donc $\\theta$ double, et la tache double aussi : $L'' = 5\\,\\text{cm}$."},{"text_fr":"**Contre-intuitif** : plus la fente est étroite, plus la tache diffractée est large. Au contraire du sens commun.","tip_fr":"Conséquence pratique : pour obtenir une image nette (objectif microscope, photographie), il faut une **grande** ouverture, pas une petite — sinon la diffraction limite la résolution."}],"final_answer_fr":"$L''$ double"}}]},{"number":2,"title_fr":"Interférences à deux ondes (Young)","points":5,"preamble_fr":"Deux fentes de Young espacées de $a = 0{,}2\\,\\text{mm}$, écran à $D = 1{,}5\\,\\text{m}$, laser à $\\lambda = 500\\,\\text{nm}$ (vert).","questions":[{"number":1,"stem_fr":"Calculer l''interfrange $i$.","points":2,"solution":{"steps":[{"text_fr":"**Formule** : $i = \\lambda D / a$ (distance entre deux franges brillantes consécutives)."},{"text_fr":"$i = 5 \\times 10^{-7} \\times 1{,}5 / (2 \\times 10^{-4}) = 3{,}75 \\times 10^{-3}\\,\\text{m} = 3{,}75\\,\\text{mm}$."}],"final_answer_fr":"$i = 3{,}75$ mm"}},{"number":2,"stem_fr":"Position de la 5ème frange brillante (par rapport à la frange centrale).","points":1,"solution":{"steps":[{"text_fr":"Frange brillante d''ordre $k$ : $x_k = k \\cdot i$. Pour $k = 5$ : $x_5 = 5 \\times 3{,}75 = 18{,}75\\,\\text{mm}$."}],"final_answer_fr":"$x_5 = 18{,}75$ mm"}},{"number":3,"stem_fr":"On change le laser pour du rouge ($\\lambda'' = 700\\,\\text{nm}$). Comment varie $i$ ?","points":2,"solution":{"steps":[{"text_fr":"$i \\propto \\lambda$. Nouvel interfrange : $i'' = 3{,}75 \\times 700/500 = 5{,}25\\,\\text{mm}$."},{"text_fr":"**Conséquence pour lumière blanche** : chaque couleur produit ses propres franges, donc l''écran présente un spectre coloré (sauf à l''ordre 0 où toutes coïncident — frange blanche centrale).","tip_fr":"L''analyse spectroscopique exploite cette propriété : interférences sélectives → mesure précise de $\\lambda$ et donc identification de l''élément chimique émetteur."}],"final_answer_fr":"$i'' = 5{,}25$ mm"}}]},{"number":3,"title_fr":"Conditions d''interférence","points":5,"preamble_fr":"Discuter les conditions pour observer des interférences nettes.","questions":[{"number":1,"stem_fr":"Pourquoi utilise-t-on un **laser** plutôt qu''une ampoule classique ?","points":3,"solution":{"steps":[{"text_fr":"**Cohérence temporelle** : un laser émet une lumière (quasi-)monochromatique — une seule longueur d''onde bien définie. Une ampoule émet un spectre large."},{"text_fr":"**Cohérence spatiale** : les rayons d''un laser sont quasi-parallèles, depuis la même source ponctuelle. Une ampoule émet dans toutes les directions, depuis un filament étendu."},{"text_fr":"**Conséquence** : avec une ampoule, les déphasages varient aléatoirement → les franges s''effacent. Avec un laser, les franges sont stables.","tip_fr":"Avant l''invention du laser (1960), on utilisait des sources spectralement filtrées (lampe sodium + fente fine) pour obtenir une cohérence suffisante."}]}},{"number":2,"stem_fr":"Si on bouche une fente de Young, que voit-on sur l''écran ?","points":2,"solution":{"steps":[{"text_fr":"Plus d''interférences (une seule source) — on observe la **figure de diffraction** d''une seule fente : tache centrale large + taches latérales décroissantes."},{"text_fr":"Les franges fines disparaissent. Démonstration que les interférences viennent bien de **deux** sources qui se superposent."}]}}]},{"number":4,"title_fr":"Mesure d''une longueur d''onde","points":5,"preamble_fr":"On observe les interférences de Young avec $a = 0{,}3\\,\\text{mm}$ et $D = 2\\,\\text{m}$. La distance entre la 1ère et la 10ème frange brillante (situées du même côté) est mesurée à $L = 36\\,\\text{mm}$.","questions":[{"number":1,"stem_fr":"Déduire l''interfrange.","points":2,"solution":{"steps":[{"text_fr":"Entre la 1ère et la 10ème frange : il y a **9 interfranges**. $L = 9 i \\iff i = 36/9 = 4\\,\\text{mm}$.","mistake_fr":"Erreur classique : compter 10 intervalles au lieu de 9. Entre la frange n°1 et la frange n°10, il y a 10 - 1 = 9 intervalles."}],"final_answer_fr":"$i = 4$ mm"}},{"number":2,"stem_fr":"En déduire la longueur d''onde du laser.","points":3,"solution":{"steps":[{"text_fr":"$i = \\lambda D / a \\iff \\lambda = a i / D$."},{"text_fr":"$\\lambda = (3 \\times 10^{-4}) \\times (4 \\times 10^{-3}) / 2 = 6 \\times 10^{-7}\\,\\text{m} = 600\\,\\text{nm}$."},{"text_fr":"Domaine du visible (380-780 nm), couleur **orange-jaune** (proche du sodium 589 nm).","tip_fr":"Méthode classique de spectroscopie : interféromètre + mesure d''interfrange → $\\lambda$. Précision en $\\mu\\text{m}$ atteignable avec optique fine."}],"final_answer_fr":"$\\lambda = 600$ nm (orange)"}}]}]}'::jsonb WHERE code = 'pc_diffraction_interference';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Modulation d''amplitude (AM)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Modulation AM : signal modulé $u(t) = [A + s(t)] \\cos(2\\pi f_p t)$ avec porteuse $f_p$ et signal informatif $s(t)$. Taux de modulation $m = S_\\text{max}/A$. Démodulation par détection d''enveloppe (diode + RC).","exercices":[{"number":1,"title_fr":"Principe de la modulation","points":5,"preamble_fr":"Une porteuse sinusoïdale $u_p(t) = A \\cos(2\\pi f_p t)$ avec $A = 5\\,\\text{V}$ et $f_p = 100\\,\\text{kHz}$. Signal informatif $s(t) = S_0 \\cos(2\\pi f_s t)$ avec $S_0 = 2\\,\\text{V}$ et $f_s = 1\\,\\text{kHz}$.","questions":[{"number":1,"stem_fr":"Donner l''expression du signal modulé en amplitude $u(t) = [A + s(t)] \\cos(2\\pi f_p t)$.","points":2,"solution":{"steps":[{"text_fr":"$u(t) = [5 + 2\\cos(2\\pi \\cdot 1000\\,t)] \\cos(2\\pi \\cdot 10^5\\,t)$, en volts."},{"text_fr":"L''amplitude de la porteuse $\\cos(2\\pi f_p t)$ varie au rythme du signal $s(t)$. L''enveloppe du signal modulé est $A + s(t)$."}],"final_answer_fr":"$u(t) = [5 + 2\\cos(2\\pi \\cdot 10^3 t)] \\cos(2\\pi \\cdot 10^5 t)$"}},{"number":2,"stem_fr":"Calculer le taux de modulation $m = S_0/A$.","points":1,"solution":{"steps":[{"text_fr":"$m = 2/5 = 0{,}4 = 40\\%$."}],"final_answer_fr":"$m = 0{,}4$"}},{"number":3,"stem_fr":"Condition de bonne modulation et conséquence si $m > 1$.","points":2,"solution":{"steps":[{"text_fr":"**Condition** : $m < 1$ (soit $S_0 < A$). L''enveloppe $A + s(t)$ reste positive → l''information est récupérable."},{"text_fr":"Si $m > 1$ : surmodulation. L''enveloppe devient négative par moments → la diode du démodulateur ne suit plus → **distorsion** du signal récupéré.","tip_fr":"En radio AM commerciale, $m \\approx 0{,}3-0{,}5$ typiquement pour garantir une bonne qualité audio."}],"final_answer_fr":"$m < 1$ requis"}}]},{"number":2,"title_fr":"Spectre du signal modulé","points":5,"preamble_fr":"Le signal modulé $u(t) = [A + S_0\\cos(2\\pi f_s t)]\\cos(2\\pi f_p t)$ peut être développé.","questions":[{"number":1,"stem_fr":"Développer $u(t)$ en somme de cosinus de fréquences pures.","points":3,"solution":{"steps":[{"text_fr":"$u(t) = A\\cos(2\\pi f_p t) + S_0\\cos(2\\pi f_s t)\\cos(2\\pi f_p t)$."},{"text_fr":"Identité : $\\cos a \\cos b = \\frac{1}{2}[\\cos(a - b) + \\cos(a + b)]$."},{"text_fr":"Donc $u(t) = A\\cos(2\\pi f_p t) + \\dfrac{S_0}{2}\\cos[2\\pi(f_p - f_s) t] + \\dfrac{S_0}{2}\\cos[2\\pi(f_p + f_s) t]$."}],"final_answer_fr":"3 raies : $f_p$, $f_p \\pm f_s$"}},{"number":2,"stem_fr":"Identifier les fréquences présentes pour $f_p = 100\\,\\text{kHz}$, $f_s = 1\\,\\text{kHz}$.","points":1,"solution":{"steps":[{"text_fr":"Trois raies spectrales : **99 kHz**, **100 kHz**, **101 kHz**."},{"text_fr":"**Largeur de bande** : 2 kHz (de 99 à 101). Le signal AM occupe 2 fois la bande passante de $s(t)$."}],"final_answer_fr":"99, 100, 101 kHz"}},{"number":3,"stem_fr":"Pourquoi cette propriété est-elle importante pour la radio ?","points":1,"solution":{"steps":[{"text_fr":"Les stations radio occupent chacune une bande étroite (~10 kHz pour la voix). On peut les **espacer** sur le spectre sans qu''elles se chevauchent : France Info à 105,5 MHz, Europe 1 à 106,2 MHz, etc."},{"text_fr":"Un récepteur sélectionne **une seule** station par un filtre accordé à sa fréquence $f_p$, puis démodule."}]}}]},{"number":3,"title_fr":"Démodulation par détection d''enveloppe","points":5,"preamble_fr":"Le démodulateur AM le plus simple : une **diode** (redresse) + un **filtre RC passe-bas** (lisse).","questions":[{"number":1,"stem_fr":"Rôle de chaque composant.","points":3,"solution":{"steps":[{"text_fr":"**Diode** : passante uniquement aux alternances positives → ne laisse passer que les pics positifs du signal modulé. Élimine les oscillations négatives."},{"text_fr":"**Condensateur C** : se charge sur chaque pic positif (à travers la diode passante) et se décharge lentement pendant l''alternance négative (diode bloquée, décharge via R)."},{"text_fr":"**Résistance R** : règle la constante de temps de décharge $\\tau = RC$."}]}},{"number":2,"stem_fr":"Condition sur $\\tau = RC$.","points":2,"solution":{"steps":[{"text_fr":"On veut suivre l''enveloppe (qui oscille à $f_s$) mais filtrer les oscillations rapides (à $f_p$)."},{"text_fr":"**Critère** : $T_p \\ll \\tau \\ll T_s$, soit $\\dfrac{1}{f_p} \\ll RC \\ll \\dfrac{1}{f_s}$."},{"text_fr":"Avec $f_p = 100\\,\\text{kHz}$ ($T_p = 10\\,\\mu\\text{s}$) et $f_s = 1\\,\\text{kHz}$ ($T_s = 1\\,\\text{ms}$) : $10\\,\\mu\\text{s} \\ll RC \\ll 1\\,\\text{ms}$. Par exemple $RC = 100\\,\\mu\\text{s}$ convient.","tip_fr":"Si $\\tau$ trop petit : ondulation HF résiduelle. Si $\\tau$ trop grand : l''enveloppe BF est lissée et perdue."}],"final_answer_fr":"$T_p \\ll RC \\ll T_s$"}}]},{"number":4,"title_fr":"Choix des composants","points":5,"preamble_fr":"On dispose de $f_p = 540\\,\\text{kHz}$ (porteuse GO de Radio Bleue), signal vocal jusqu''à $f_s^\\text{max} = 5\\,\\text{kHz}$. Choisir $C$ si $R = 10\\,\\text{k}\\Omega$.","questions":[{"number":1,"stem_fr":"Calculer les périodes $T_p$ et $T_s^\\text{min}$.","points":1,"solution":{"steps":[{"text_fr":"$T_p = 1/540\\,000 \\approx 1{,}85\\,\\mu\\text{s}$. $T_s^\\text{min} = 1/5000 = 200\\,\\mu\\text{s}$."}],"final_answer_fr":"$T_p \\approx 1{,}85$ μs, $T_s \\approx 200$ μs"}},{"number":2,"stem_fr":"Choisir $\\tau = RC$ dans la fenêtre admissible et en déduire $C$.","points":3,"solution":{"steps":[{"text_fr":"Fenêtre : $1{,}85\\,\\mu\\text{s} \\ll \\tau \\ll 200\\,\\mu\\text{s}$. Choix raisonnable : $\\tau \\approx 20\\,\\mu\\text{s}$ (un ordre de grandeur de chaque limite)."},{"text_fr":"$C = \\tau/R = 20 \\times 10^{-6} / 10^4 = 2\\,\\text{nF}$."},{"text_fr":"Vérifications : $1{,}85\\,\\mu\\text{s} \\ll 20\\,\\mu\\text{s}$ (rapport ~10) ✓ ; $20\\,\\mu\\text{s} \\ll 200\\,\\mu\\text{s}$ (rapport 10) ✓. La voix sera bien démodulée sans résidu HF ni perte de fréquence audio."}],"final_answer_fr":"$C = 2$ nF"}},{"number":3,"stem_fr":"Conséquence d''un $C$ 100 fois trop grand ($C = 200\\,\\text{nF}$).","points":1,"solution":{"steps":[{"text_fr":"$\\tau = 2\\,\\text{ms} = 10 \\times T_s^\\text{min}$ — bien trop grand. Le condensateur ne se décharge plus assez vite pour suivre l''enveloppe BF."},{"text_fr":"**Conséquence** : les variations rapides du signal audio (consonnes, attaque des mots) sont aplaties → son grave et bouché. Distorsion clairement audible."}]}}]}]}'::jsonb WHERE code = 'pc_am_modulation';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Radioactivité","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Désintégrations $\\alpha$, $\\beta^-$, $\\beta^+$. Loi de décroissance $N(t) = N_0 e^{-\\lambda t}$. Activité $A = \\lambda N$. Demi-vie $t_{1/2} = \\ln 2/\\lambda$.","exercices":[{"number":1,"title_fr":"Types de désintégrations","points":5,"preamble_fr":"On note un noyau $\\,^A_Z X$ avec $A$ = nombre de masse, $Z$ = numéro atomique.","questions":[{"number":1,"stem_fr":"Donner l''équation de la désintégration $\\alpha$ du polonium 210 ($^{210}_{84}\\text{Po}$). Lois de conservation utilisées ?","points":3,"solution":{"steps":[{"text_fr":"**Désintégration $\\alpha$** : émission d''un noyau d''hélium $^4_2\\text{He}$."},{"text_fr":"Conservation : $A_X = A_Y + 4$ (masse) et $Z_X = Z_Y + 2$ (charge)."},{"text_fr":"Équation : $^{210}_{84}\\text{Po} \\to ^{206}_{82}\\text{Pb} + ^4_2\\text{He}$ (production de plomb 206).","tip_fr":"Lois de Soddy : conservation simultanée du nombre de masse $A$ et de la charge électrique $Z$. À appliquer systématiquement."}],"final_answer_fr":"$^{210}_{84}\\text{Po} \\to ^{206}_{82}\\text{Pb} + ^4_2\\text{He}$"}},{"number":2,"stem_fr":"Désintégration $\\beta^-$ du carbone 14 ($^{14}_6\\text{C}$).","points":2,"solution":{"steps":[{"text_fr":"**$\\beta^-$** : émission d''un électron $^0_{-1}\\text{e}$ ; un neutron se transforme en proton. $A$ inchangé, $Z$ augmente de 1."},{"text_fr":"$^{14}_6\\text{C} \\to ^{14}_7\\text{N} + ^0_{-1}\\text{e} + \\bar\\nu_e$ (avec antineutrino, souvent omis au Bac)."}],"final_answer_fr":"$^{14}_6\\text{C} \\to ^{14}_7\\text{N} + ^0_{-1}\\text{e}$"}},{"number":3,"stem_fr":"Désintégration $\\beta^+$ du fluor 18 ($^{18}_9\\text{F}$).","points":0,"solution":{"steps":[{"text_fr":"**$\\beta^+$** : émission d''un positron $^0_{+1}\\text{e}$ ; un proton se transforme en neutron. $A$ inchangé, $Z$ diminue de 1."},{"text_fr":"$^{18}_9\\text{F} \\to ^{18}_8\\text{O} + ^0_{+1}\\text{e}$. Le fluor 18 est utilisé en imagerie médicale (TEP — tomographie par émission de positrons)."}],"final_answer_fr":"$^{18}_9\\text{F} \\to ^{18}_8\\text{O} + ^0_{+1}\\text{e}$"}}]},{"number":2,"title_fr":"Loi de décroissance","points":5,"preamble_fr":"Un échantillon contient $N_0 = 10^{12}$ noyaux radioactifs à $t = 0$. La demi-vie est $t_{1/2} = 8\\,\\text{jours}$.","questions":[{"number":1,"stem_fr":"Calculer la constante de désintégration $\\lambda$.","points":2,"solution":{"steps":[{"text_fr":"**Relation fondamentale** : $t_{1/2} = \\ln 2 / \\lambda \\iff \\lambda = \\ln 2 / t_{1/2}$."},{"text_fr":"$\\lambda = 0{,}693/8 \\approx 0{,}0866\\,\\text{jour}^{-1}$."},{"text_fr":"En SI : $\\lambda \\approx 0{,}0866/(86400) \\approx 1{,}00 \\times 10^{-6}\\,\\text{s}^{-1}$."}],"final_answer_fr":"$\\lambda \\approx 0{,}087$ /jour"}},{"number":2,"stem_fr":"Donner $N(t)$ et calculer $N(24\\,\\text{jours})$.","points":2,"solution":{"steps":[{"text_fr":"$N(t) = N_0 e^{-\\lambda t}$. À $t = 24\\,\\text{jours} = 3 \\times t_{1/2}$ : $N = N_0/2^3 = N_0/8 = 1{,}25 \\times 10^{11}$."},{"text_fr":"Vérification : $N(24) = 10^{12} \\times e^{-0{,}0866 \\times 24} = 10^{12} \\times e^{-2{,}08} \\approx 10^{12} \\times 0{,}125 = 1{,}25 \\times 10^{11}$ ✓.","tip_fr":"Méthode rapide : si $t = n \\cdot t_{1/2}$, alors $N = N_0/2^n$. Évite le calcul avec exponentielles."}],"final_answer_fr":"$N(24) = 1{,}25 \\times 10^{11}$"}},{"number":3,"stem_fr":"Combien de temps pour qu''il reste 1% des noyaux initiaux ?","points":1,"solution":{"steps":[{"text_fr":"$N/N_0 = 0{,}01 \\iff e^{-\\lambda t} = 0{,}01 \\iff t = \\ln 100/\\lambda = 4{,}605/0{,}0866 \\approx 53\\,\\text{jours}$."},{"text_fr":"**Règle pratique** : il reste 1% après ~7 demi-vies ($1/2^7 \\approx 0{,}008$). Ici 53/8 ≈ 6,6 demi-vies. Cohérent."}],"final_answer_fr":"$t \\approx 53$ jours"}}]},{"number":3,"title_fr":"Activité radioactive","points":5,"preamble_fr":"L''activité $A$ est le nombre de désintégrations par seconde. Unité : becquerel (1 Bq = 1 désint./s). $A(t) = \\lambda N(t) = A_0 e^{-\\lambda t}$.","questions":[{"number":1,"stem_fr":"Calculer l''activité initiale $A_0$ de l''échantillon de l''exercice 2.","points":2,"solution":{"steps":[{"text_fr":"$A_0 = \\lambda N_0 = 1{,}00 \\times 10^{-6} \\times 10^{12} = 10^6\\,\\text{Bq} = 1\\,\\text{MBq}$.","tip_fr":"Toujours utiliser $\\lambda$ en s⁻¹ pour obtenir l''activité en Bq (désint./s). Ne pas mélanger jours et secondes !"}],"final_answer_fr":"$A_0 = 10^6$ Bq = 1 MBq"}},{"number":2,"stem_fr":"Activité après 24 jours.","points":1,"solution":{"steps":[{"text_fr":"Même décroissance que $N$ : $A(24) = A_0/2^3 = 125\\,\\text{kBq}$."}],"final_answer_fr":"$A = 125$ kBq"}},{"number":3,"stem_fr":"Pourquoi un radio-isotope à courte demi-vie est-il plus ''actif'' à masse égale ?","points":2,"solution":{"steps":[{"text_fr":"À masse égale (nombre de noyaux égal $N$), $A = \\lambda N$. $\\lambda = \\ln 2/t_{1/2}$ → $A \\propto 1/t_{1/2}$."},{"text_fr":"**Conséquence** : 1 mg de radium 226 ($t_{1/2} \\approx 1600\\,\\text{ans}$) est ~50 fois moins actif que 1 mg de cobalt 60 ($t_{1/2} \\approx 5{,}3\\,\\text{ans}$).","tip_fr":"C''est pourquoi le tritium ou le radon (vies brèves) sont dangereux malgré leurs faibles quantités — leur activité spécifique est énorme."}]}}]},{"number":4,"title_fr":"Application — datation au carbone 14","points":5,"preamble_fr":"Le $^{14}\\text{C}$ est produit dans l''atmosphère par les rayons cosmiques. Sa concentration dans les organismes vivants est constante. À la mort, plus d''assimilation : $N$ décroît. $t_{1/2} = 5730\\,\\text{ans}$.","questions":[{"number":1,"stem_fr":"On retrouve un os ancien dont l''activité spécifique en $^{14}\\text{C}$ est 25% de celle d''un os actuel. Âge ?","points":4,"solution":{"steps":[{"text_fr":"$A/A_0 = 0{,}25 = 1/4 = 1/2^2$ → l''échantillon a vécu **2 demi-vies** après la mort."},{"text_fr":"Âge : $t = 2 \\times t_{1/2} = 2 \\times 5730 = 11\\,460\\,\\text{ans}$."},{"text_fr":"**Vérification par log** : $t = -\\ln(0{,}25)/\\lambda = \\ln 4/\\lambda = 1{,}386 \\times 5730/0{,}693 \\approx 11\\,460\\,\\text{ans}$ ✓.","tip_fr":"Datation $^{14}\\text{C}$ : utilisable jusqu''à ~50 000 ans (8-9 demi-vies). Au-delà, l''activité résiduelle est trop faible pour mesurer."}],"final_answer_fr":"$t \\approx 11\\,460$ ans"}},{"number":2,"stem_fr":"Limite supérieure de la méthode (en âge).","points":1,"solution":{"steps":[{"text_fr":"Vers 10 demi-vies (~57 000 ans), $A \\approx A_0/1024 < 0{,}1\\%$ — sous le seuil de détection. Pratiquement : limite ~50 000 ans."},{"text_fr":"Pour des roches plus anciennes (millions d''années), on utilise d''autres couples : potassium-argon ($t_{1/2} = 1{,}25 \\times 10^9\\) ans), uranium-plomb."}],"final_answer_fr":"~50 000 ans"}}]}]}'::jsonb WHERE code = 'pc_radioactivity';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Vitesse de réaction (cinétique chimique)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Vitesse volumique $v = \\dfrac{1}{V} \\dfrac{d\\xi}{dt}$ ou en fonction des concentrations. Facteurs cinétiques : température, concentration, catalyseur. Temps de demi-réaction $t_{1/2}$.","exercices":[{"number":1,"title_fr":"Définition et calcul","points":5,"preamble_fr":"On suit la réaction $2 \\text{H}_2\\text{O}_2 \\to 2 \\text{H}_2\\text{O} + \\text{O}_2$ (décomposition de l''eau oxygénée). À $t = 0$, $[\\text{H}_2\\text{O}_2]_0 = 0{,}1\\,\\text{mol/L}$.","questions":[{"number":1,"stem_fr":"Définir la vitesse volumique $v(t)$ en fonction de $[\\text{H}_2\\text{O}_2]$.","points":2,"solution":{"steps":[{"text_fr":"**Vitesse volumique** : $v = \\dfrac{1}{V} \\dfrac{d\\xi}{dt}$ avec $\\xi$ = avancement."},{"text_fr":"Pour un réactif R avec coefficient stoechiométrique $\\nu_R$ : $v = -\\dfrac{1}{\\nu_R} \\dfrac{d[R]}{dt}$."},{"text_fr":"Ici $\\nu = 2$ pour $\\text{H}_2\\text{O}_2$ : $v = -\\dfrac{1}{2} \\dfrac{d[\\text{H}_2\\text{O}_2]}{dt}$.","mistake_fr":"Ne pas oublier le signe **moins** pour un réactif (concentration qui décroît) et la division par le coefficient stoechiométrique."}],"final_answer_fr":"$v = -\\dfrac{1}{2} \\dfrac{d[H_2O_2]}{dt}$"}},{"number":2,"stem_fr":"À $t_1 = 30\\,\\text{s}$, on mesure $[\\text{H}_2\\text{O}_2] = 0{,}08\\,\\text{mol/L}$ et la tangente locale a une pente de $-1{,}2 \\times 10^{-3}\\,\\text{mol/(L·s)}$. Calculer $v(30\\,\\text{s})$.","points":2,"solution":{"steps":[{"text_fr":"$v = -\\dfrac{1}{2} \\times (-1{,}2 \\times 10^{-3}) = 6 \\times 10^{-4}\\,\\text{mol/(L·s)}$."},{"text_fr":"**Unités** : la vitesse volumique s''exprime en mol·L⁻¹·s⁻¹ (ou mol·L⁻¹·min⁻¹ selon le contexte)."}],"final_answer_fr":"$v = 6 \\times 10^{-4}$ mol/(L·s)"}},{"number":3,"stem_fr":"Comment varie $v$ au cours du temps ? Pourquoi ?","points":1,"solution":{"steps":[{"text_fr":"$v$ **diminue** au cours du temps : la concentration de réactif diminue (consommation), les chocs efficaces diminuent. À $t \\to \\infty$, $v \\to 0$ (réaction terminée)."}]}}]},{"number":2,"title_fr":"Facteurs cinétiques","points":5,"preamble_fr":"Quatre facteurs principaux modifient la vitesse d''une réaction.","questions":[{"number":1,"stem_fr":"Effet de la **température**.","points":2,"solution":{"steps":[{"text_fr":"$T \\nearrow$ → $v \\nearrow$. Une augmentation de **10°C** double approximativement la vitesse (règle empirique de van''t Hoff)."},{"text_fr":"**Explication moléculaire** : agitation thermique accrue → fraction plus élevée de chocs assez énergétiques pour franchir la barrière d''activation $E_a$ (loi d''Arrhenius : $k \\propto e^{-E_a/RT}$).","tip_fr":"Applications : réfrigération (ralentit la dégradation des aliments), cuisson (accélère les réactions de Maillard, etc.)."}]}},{"number":2,"stem_fr":"Effet de la **concentration** des réactifs.","points":1,"solution":{"steps":[{"text_fr":"$[R] \\nearrow$ → $v \\nearrow$. Plus de molécules par unité de volume → plus de chocs par unité de temps. Pour une réaction d''ordre 1 : $v = k[R]$."}]}},{"number":3,"stem_fr":"Effet d''un **catalyseur**.","points":1,"solution":{"steps":[{"text_fr":"Le catalyseur **diminue $E_a$** sans être consommé. $v \\nearrow$ sans changer l''équilibre thermodynamique (juste la cinétique)."},{"text_fr":"Exemples : MnO₂ pour décomposer H₂O₂, enzymes en biologie (vitesses multipliées par 10⁶ à 10¹²)."}]}},{"number":4,"stem_fr":"Effet de la **surface de contact** (réactifs solides).","points":1,"solution":{"steps":[{"text_fr":"Surface $\\nearrow$ → $v \\nearrow$. Pulvérisation, broyage augmentent la surface de contact réactif/milieu."},{"text_fr":"Exemple spectaculaire : poudre de fer dans l''air = combustion explosive ; bloc de fer = oxydation très lente (rouille)."}]}}]},{"number":3,"title_fr":"Temps de demi-réaction","points":5,"preamble_fr":"Pour une réaction où un réactif est limitant : $t_{1/2}$ = durée pour atteindre $[R] = [R]_0/2$.","questions":[{"number":1,"stem_fr":"Cas d''une réaction d''ordre 1 : $v = k[R]$. Déduire $[R](t)$ et $t_{1/2}$.","points":3,"solution":{"steps":[{"text_fr":"Équation : $d[R]/dt = -k[R]$. Solution : $[R](t) = [R]_0 e^{-k t}$ (EDO du 1er ordre)."},{"text_fr":"Temps de demi-réaction : $[R](t_{1/2}) = [R]_0/2 \\iff e^{-k t_{1/2}} = 1/2 \\iff t_{1/2} = \\ln 2/k$."},{"text_fr":"**Propriété remarquable** : $t_{1/2}$ est **indépendant** de $[R]_0$ pour une réaction d''ordre 1. Mêmes proportions, mêmes durées.","tip_fr":"Analogie parfaite avec la radioactivité (qui est aussi une cinétique d''ordre 1) : même formule $t_{1/2} = \\ln 2/\\lambda$."}],"final_answer_fr":"$t_{1/2} = \\ln 2/k$"}},{"number":2,"stem_fr":"Si $k = 0{,}01\\,\\text{s}^{-1}$ pour une décomposition d''ordre 1, calculer $t_{1/2}$.","points":2,"solution":{"steps":[{"text_fr":"$t_{1/2} = \\ln 2/k = 0{,}693/0{,}01 \\approx 69{,}3\\,\\text{s}$."},{"text_fr":"Au bout de $5 t_{1/2} \\approx 347\\,\\text{s} \\approx 6\\,\\text{min}$, il reste $1/2^5 \\approx 3\\%$ du réactif initial → réaction quasi-terminée."}],"final_answer_fr":"$t_{1/2} \\approx 69$ s"}}]},{"number":4,"title_fr":"Méthodes de suivi","points":5,"preamble_fr":"Comment suit-on l''évolution d''une concentration en cours de réaction ?","questions":[{"number":1,"stem_fr":"Méthode **spectrophotométrique** (UV-visible).","points":2,"solution":{"steps":[{"text_fr":"**Principe** : on mesure l''absorbance $A$ à une longueur d''onde où **un seul** participant absorbe. Loi de Beer-Lambert : $A = \\varepsilon \\ell C$ (linéaire avec la concentration)."},{"text_fr":"**Applications** : suivi de réactions colorées (diiode, permanganate, complexes). Non-invasif (pas de prélèvement)."}]}},{"number":2,"stem_fr":"Méthode **conductimétrique**.","points":2,"solution":{"steps":[{"text_fr":"**Principe** : on mesure la conductance $G$ de la solution. Si la réaction produit ou consomme des ions, $G$ varie : $G = \\sigma S/\\ell$ avec $\\sigma = \\sum \\lambda_i c_i$ (conductivité = somme pondérée par mobilités ioniques)."},{"text_fr":"**Applications** : hydrolyses, dosages acide-base, précipitations."}]}},{"number":3,"stem_fr":"Méthode **par dégagement gazeux** (volumétrique).","points":1,"solution":{"steps":[{"text_fr":"Mesurer le volume de gaz produit en fonction du temps (ex : décomposition H₂O₂ → O₂). PV = nRT donne la quantité de matière."},{"text_fr":"Simple et peu coûteux, mais limité aux réactions à dégagement gazeux mesurable.","tip_fr":"Critère de choix : adapter la méthode à la réaction. Coloré → spectro. Avec ions → conductimétrie. Gaz produit → volumétrie. pH variable → pHmétrie."}]}}]}]}'::jsonb WHERE code = 'pc_reaction_speed';

COMMIT;
